function sanitizeAnamnesisTemplate(input: any) {
  const safeType = (value: any) => {
    const parsed = sanitizeString(value, 40);
    return ['dissertativa', 'multipla_escolha', 'multipla_selecao', 'data', 'numero', 'telefone', 'sim_nao'].includes(parsed)
      ? parsed
      : 'dissertativa';
  };

  const sanitizeSection = (section: any, fallbackOrder: number) => cleanObject({
    id: sanitizeString(section?.id, 120) || `section_${fallbackOrder}`,
    title: sanitizeString(section?.title, 220) || `Seção ${fallbackOrder}`,
    order: Number.isFinite(Number(section?.order)) ? Number(section?.order) : fallbackOrder,
    active: section?.active !== false
  });

  const sanitizeQuestion = (question: any, fallbackOrder: number) => {
    const type = safeType(question?.type);
    const options =
      type === 'multipla_escolha' || type === 'multipla_selecao'
        ? Array.isArray(question?.options)
          ? question.options.map((option: any) => sanitizeString(option, 120)).filter(Boolean).slice(0, 30)
          : []
        : undefined;
    return cleanObject({
      id: sanitizeString(question?.id, 120) || `q_${Date.now()}_${fallbackOrder}`,
      sectionId: sanitizeString(question?.sectionId, 120),
      label: sanitizeString(question?.label, 240),
      type,
      options,
      required: question?.required === true,
      active: question?.active !== false,
      order: Number.isFinite(Number(question?.order)) ? Number(question?.order) : fallbackOrder
    });
  };

  const sanitizeProfile = (profileInput: any, profileFallback: any) => {
    const sections = (Array.isArray(profileInput?.sections) ? profileInput.sections : profileFallback.sections)
      .slice(0, 120)
      .map((section: any, index: number) => sanitizeSection(section, index + 1))
      .filter((section: any) => section.id && section.title);
    const sectionIds = new Set(sections.map((section: any) => section.id));

    const questions = (Array.isArray(profileInput?.questions) ? profileInput.questions : profileFallback.questions)
      .slice(0, 1000)
      .map((question: any, index: number) => sanitizeQuestion(question, index + 1))
      .filter((question: any) => question.id && question.sectionId && sectionIds.has(question.sectionId) && question.label);

    return {
      sections: sections.sort((a: any, b: any) => Number(a.order || 0) - Number(b.order || 0)),
      questions: questions.sort((a: any, b: any) => Number(a.order || 0) - Number(b.order || 0))
    };
  };

  const defaultTemplate = getDefaultAnamnesisTemplate();
  const legacyHidden = new Set(Array.isArray(input?.hiddenFields) ? input.hiddenFields.map((f: any) => sanitizeString(f, 120)) : []);
  const legacyDeleted = new Set(Array.isArray(input?.deletedFields) ? input.deletedFields.map((f: any) => sanitizeString(f, 120)) : []);
  const legacyCustom = Array.isArray(input?.customQuestions) ? input.customQuestions.slice(0, 300) : [];
  const looksLegacy = legacyHidden.size > 0 || legacyDeleted.size > 0 || legacyCustom.length > 0;

  const mergedInput = looksLegacy
    ? {
        ...defaultTemplate,
        profiles: {
          adult: {
            ...defaultTemplate.profiles.adult,
            questions: [
              ...defaultTemplate.profiles.adult.questions.map((question: any) => ({
                ...question,
                active: !(legacyHidden.has(question.id) || legacyDeleted.has(question.id))
              })),
              ...legacyCustom
                .filter((question: any) => ['both', 'adult', ''].includes(sanitizeString(question?.appliesTo, 20)))
                .map((question: any, index: number) => ({
                  id: sanitizeString(question?.id, 120) || `legacy_adult_${index + 1}`,
                  sectionId: 'personalizadas',
                  label: sanitizeString(question?.label, 240) || `Pergunta personalizada ${index + 1}`,
                  type: safeType(question?.type),
                  options: Array.isArray(question?.options) ? question.options : [],
                  required: question?.required === true,
                  active: question?.active !== false,
                  order: 900 + index
                }))
            ]
          },
          child: {
            ...defaultTemplate.profiles.child,
            questions: [
              ...defaultTemplate.profiles.child.questions.map((question: any) => ({
                ...question,
                active: !(legacyHidden.has(question.id) || legacyDeleted.has(question.id))
              })),
              ...legacyCustom
                .filter((question: any) => ['both', 'child', ''].includes(sanitizeString(question?.appliesTo, 20)))
                .map((question: any, index: number) => ({
                  id: sanitizeString(question?.id, 120) || `legacy_child_${index + 1}`,
                  sectionId: 'personalizadas',
                  label: sanitizeString(question?.label, 240) || `Pergunta personalizada ${index + 1}`,
                  type: safeType(question?.type),
                  options: Array.isArray(question?.options) ? question.options : [],
                  required: question?.required === true,
                  active: question?.active !== false,
                  order: 900 + index
                }))
            ]
          }
        }
      }
    : input;

  const version = Number.isFinite(Number(mergedInput?.version)) ? Math.max(1, Number(mergedInput.version)) : 1;
  const profileType = sanitizeString(mergedInput?.profileType, 20) === 'child' ? 'child' : 'adult';

  return {
    version,
    profileType,
    profiles: {
      adult: sanitizeProfile(mergedInput?.profiles?.adult, defaultTemplate.profiles.adult),
      child: sanitizeProfile(mergedInput?.profiles?.child, defaultTemplate.profiles.child)
    }
  };
}

function listAnamnesisTemplateChanges(previousTemplate: any, nextTemplate: any): string[] {
  const changes: string[] = [];
  const safePrev = sanitizeAnamnesisTemplate(previousTemplate || {});
  const safeNext = sanitizeAnamnesisTemplate(nextTemplate || {});

  (['adult', 'child'] as Array<'adult' | 'child'>).forEach((profileType) => {
    const prevProfile = safePrev.profiles?.[profileType];
    const nextProfile = safeNext.profiles?.[profileType];

    const prevSections = new Map((prevProfile?.sections || []).map((section: any) => [section.id, section]));
    const nextSections = new Map((nextProfile?.sections || []).map((section: any) => [section.id, section]));

    nextSections.forEach((section: any, sectionId: string) => {
      const prevSection = prevSections.get(sectionId);
      if (!prevSection) {
        changes.push(`[${profileType}] Seção criada: ${section.title}`);
        return;
      }
      if (prevSection.title !== section.title) {
        changes.push(`[${profileType}] Seção editada: ${prevSection.title} -> ${section.title}`);
      }
      if (prevSection.active !== section.active) {
        changes.push(`[${profileType}] Seção ${section.active ? 'reativada' : 'desativada'}: ${section.title}`);
      }
    });

    const prevQuestions = new Map((prevProfile?.questions || []).map((question: any) => [question.id, question]));
    const nextQuestions = new Map((nextProfile?.questions || []).map((question: any) => [question.id, question]));

    nextQuestions.forEach((question: any, questionId: string) => {
      const prevQuestion = prevQuestions.get(questionId);
      if (!prevQuestion) {
        changes.push(`[${profileType}] Pergunta criada: ${question.label}`);
        return;
      }
      if (prevQuestion.label !== question.label || prevQuestion.type !== question.type || prevQuestion.required !== question.required) {
        changes.push(`[${profileType}] Pergunta editada: ${question.label}`);
      }
      if (prevQuestion.active !== question.active) {
        changes.push(`[${profileType}] Pergunta ${question.active ? 'reativada' : 'desativada'}: ${question.label}`);
      }
    });
  });

  if (safePrev.version !== safeNext.version) {
    changes.push(`Publicação de versão da anamnese: v${safePrev.version} -> v${safeNext.version}`);
  }

  return Array.from(new Set(changes)).slice(0, 40);
}

function currentClinicId(user: any): string | null {
  const id = sanitizeString(
    user?.activeWorkspaceId || user?.clinicId || user?.clinic_id,
    120
  );
  return id || null;
}

function currentClinicTimeZone(user: any): string {
  return sanitizeString(
    user?.clinicTimeZone ||
      user?.clinic_timezone ||
      user?.timezone ||
      user?.time_zone ||
      process.env.DEFAULT_CLINIC_TIMEZONE ||
      'America/Sao_Paulo',
    80
  ) || 'America/Sao_Paulo';
}

function dateGroupForClinic(value: unknown, user: any): string {
  const date = value ? new Date(String(value)) : new Date();
  const safeDate = Number.isNaN(date.getTime()) ? new Date() : date;
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: currentClinicTimeZone(user),
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
  return formatter.format(safeDate);
}

function hasGlobalClinicAccess(user: any): boolean {
  const role = sanitizeString(user?.role, 40).toLowerCase();
  return role === 'admin' || role === 'owner';
}

function canAccessClinicFinance(user: any): boolean {
  const role = sanitizeString(user?.role, 40).toLowerCase();
  return role === 'coordinator' || role === 'admin' || role === 'owner';
}

const TEAM_ACCESS_PER_ACTIVE_PATIENT = 10;
const MIN_TEAM_ACCESS_LIMIT = 10;

async function getClinicTeamAccessUsage(clinicId: string) {
  const safeClinicId = sanitizeString(clinicId, 120);
  if (!safeClinicId) {
    return {
      activePatients: 0,
      activeMembers: 0,
      pendingInvitations: 0,
      limit: MIN_TEAM_ACCESS_LIMIT,
      used: 0
    };
  }

  const [patientsResult, membersResult, invitationsResult] = await Promise.all([
    supabase
      .from('patients')
      .select('id', { count: 'exact', head: true })
      .eq('clinic_id', safeClinicId)
      .eq('is_active', true)
      .is('deleted_at', null),
    supabase
      .from('clinic_memberships')
      .select('user_id', { count: 'exact', head: true })
      .eq('clinic_id', safeClinicId)
      .eq('status', 'active')
      .in('role', ['coordinator', 'therapist', 'receptionist']),
    supabase
      .from('invitations')
      .select('id', { count: 'exact', head: true })
      .eq('clinic_id', safeClinicId)
      .eq('status', 'pending')
      .in('role', ['coordinator', 'therapist', 'receptionist'])
  ]);

  const activePatients = Math.max(0, Number(patientsResult.count || 0));
  const activeMembers = Math.max(0, Number(membersResult.count || 0));
  const pendingInvitations = Math.max(0, Number(invitationsResult.count || 0));
  const limit = Math.max(MIN_TEAM_ACCESS_LIMIT, activePatients * TEAM_ACCESS_PER_ACTIVE_PATIENT);
  return {
    activePatients,
    activeMembers,
    pendingInvitations,
    limit,
    used: activeMembers + pendingInvitations
  };
}

type PatientSchemaFallbackFilter = {
  op: 'eq' | 'is' | 'ilike';
  column: string;
  value: any;
  onMissing?: 'omit' | 'empty' | 'throw';
};

async function queryPatientsWithSchemaFallback(params: {
  selectColumns: string[] | string;
  filters?: PatientSchemaFallbackFilter[];
  limit?: number;
  context?: string;
}): Promise<any[]> {
  let selectColumns = Array.isArray(params.selectColumns)
    ? params.selectColumns.map((column) => sanitizeString(column, 120)).filter(Boolean)
    : String(params.selectColumns || '')
      .split(',')
      .map((column) => sanitizeString(column, 120))
      .filter(Boolean);
  if (selectColumns.length === 0) selectColumns = ['id'];

  let filters = (params.filters || [])
    .map((filter) => ({
      ...filter,
      column: sanitizeString(filter.column, 120),
      onMissing: filter.onMissing || 'throw'
    }))
    .filter((filter) => filter.column);

  let lastError: any = null;
  for (let attempt = 0; attempt < 20; attempt += 1) {
    let query = supabase
      .from('patients')
      .select(selectColumns.join(','));

    for (const filter of filters) {
      if (filter.op === 'eq') query = query.eq(filter.column, filter.value);
      if (filter.op === 'is') query = query.is(filter.column, filter.value);
      if (filter.op === 'ilike') query = query.ilike(filter.column, filter.value);
    }
    if (params.limit) query = query.limit(params.limit);

    const { data, error } = await query;
    if (!error) return Array.isArray(data) ? data : [];

    lastError = error;
    const missingColumn = extractMissingColumnName(error);
    if (!missingColumn) throw error;

    const filterIndex = filters.findIndex((filter) => filter.column === missingColumn);
    if (filterIndex >= 0) {
      const filter = filters[filterIndex];
      if (filter.onMissing === 'empty') return [];
      if (filter.onMissing === 'omit') {
        filters = filters.filter((_, index) => index !== filterIndex);
        console.warn('[Patients] filtro opcional removido por schema legado:', {
          context: sanitizeString(params.context, 120) || 'patients',
          missingColumn
        });
        continue;
      }
      throw error;
    }

    if (selectColumns.includes(missingColumn) && selectColumns.length > 1) {
      selectColumns = selectColumns.filter((column) => column !== missingColumn);
      console.warn('[Patients] coluna opcional removida do select por schema legado:', {
        context: sanitizeString(params.context, 120) || 'patients',
        missingColumn
      });
      continue;
    }

    throw error;
  }

  if (lastError) throw lastError;
  return [];
}

async function upsertPatientWithSchemaFallback(payload: Record<string, any>) {
  let safePayload: Record<string, any> = cleanObject({ ...payload });
  let selectColumns = PATIENT_MUTATION_SELECT
    .split(',')
    .map((column) => sanitizeString(column, 120))
    .filter(Boolean);
  let lastResult: { data: any; error: any } = { data: null, error: null };
  let triedLegacyPendingStatus = false;

  for (let attempt = 0; attempt < 30; attempt += 1) {
    const result = await supabase
      .from('patients')
      .upsert([safePayload], { onConflict: 'id' })
      .select(selectColumns.join(','))
      .single();
    lastResult = result;
    if (!result.error) return result;

    const missingColumn = extractMissingColumnName(result.error);
    if (!missingColumn) {
      const message = extractSupabaseErrorMessage(result.error).toLowerCase();
      if (
        !triedLegacyPendingStatus &&
        Object.prototype.hasOwnProperty.call(safePayload, 'status') &&
        (sanitizeString(result.error?.code, 20) === '23514' || message.includes('check constraint'))
      ) {
        triedLegacyPendingStatus = true;
        safePayload.status = 'pending';
        console.warn('[Patients] status clinico pendente adaptado para schema legado.');
        continue;
      }
      return result;
    }

    if (Object.prototype.hasOwnProperty.call(safePayload, missingColumn)) {
      delete safePayload[missingColumn];
      console.warn('[Patients] coluna opcional removida do payload de cadastro:', { missingColumn });
      continue;
    }

    if (selectColumns.includes(missingColumn) && selectColumns.length > 1) {
      selectColumns = selectColumns.filter((column) => column !== missingColumn);
      console.warn('[Patients] coluna opcional removida do retorno de cadastro:', { missingColumn });
      continue;
    }

    return result;
  }

  return lastResult;
}

async function insertRowWithSchemaFallback(tableName: string, payload: Record<string, any>, context = tableName) {
  let safePayload: Record<string, any> = cleanObject({ ...payload });
  let lastError: any = null;

  for (let attempt = 0; attempt < 30; attempt += 1) {
    const { error } = await supabase.from(tableName).insert([safePayload]);
    if (!error) return { success: true, data: safePayload, error: null };
    lastError = error;

    const missingColumn = extractMissingColumnName(error);
    if (missingColumn && Object.prototype.hasOwnProperty.call(safePayload, missingColumn)) {
      delete safePayload[missingColumn];
      console.warn('[SchemaFallback] coluna opcional removida do insert:', {
        table: tableName,
        context: sanitizeString(context, 160),
        missingColumn
      });
      continue;
    }

    return { success: false, data: null, error };
  }

  return { success: false, data: null, error: lastError || new Error('Falha ao inserir registro.') };
}

async function updateRowsWithSchemaFallback(params: {
  tableName: string;
  payload: Record<string, any>;
  filters: Array<{ column: string; value: any }>;
  context?: string;
}) {
  let safePayload: Record<string, any> = cleanObject({ ...params.payload });
  let lastError: any = null;

  for (let attempt = 0; attempt < 30; attempt += 1) {
    let query = supabase.from(params.tableName).update(safePayload);
    for (const filter of params.filters || []) {
      const column = sanitizeString(filter.column, 120);
      if (column) query = query.eq(column, filter.value);
    }

    const { error } = await query;
    if (!error) return { success: true, error: null };
    lastError = error;

    const missingColumn = extractMissingColumnName(error);
    if (missingColumn && Object.prototype.hasOwnProperty.call(safePayload, missingColumn)) {
      delete safePayload[missingColumn];
      console.warn('[SchemaFallback] coluna opcional removida do update:', {
        table: params.tableName,
        context: sanitizeString(params.context || params.tableName, 160),
        missingColumn
      });
      continue;
    }

    return { success: false, error };
  }

  return { success: false, error: lastError || new Error('Falha ao atualizar registro.') };
}

function stableHashPayload(input: any): string {
  const normalize = (value: any): any => {
    if (Array.isArray(value)) return value.map(normalize);
    if (value && typeof value === 'object') {
      return Object.keys(value)
        .sort()
        .reduce((acc: Record<string, any>, key) => {
          acc[key] = normalize(value[key]);
          return acc;
        }, {});
    }
    return value;
  };
  return crypto.createHash('sha256').update(JSON.stringify(normalize(input || {}))).digest('hex');
}

function normalizeTimelineVisibility(value: any): 'PRIVATE' | 'PATIENT' | 'PROFESSIONALS' | 'PORTABLE' | 'IMPORTED' {
  const normalized = sanitizeString(value, 40).toUpperCase();
  if (['PATIENT', 'FAMILY', 'FAMILIA'].includes(normalized)) return 'PATIENT';
  if (['PROFESSIONALS', 'PROFESSIONAL', 'TEAM'].includes(normalized)) return 'PROFESSIONALS';
  if (normalized === 'PORTABLE') return 'PORTABLE';
  if (normalized === 'IMPORTED') return 'IMPORTED';
  return 'PRIVATE';
}

function isShareableTimelineVisibility(value: any): boolean {
  const visibility = normalizeTimelineVisibility(value);
  return visibility === 'PATIENT' || visibility === 'PROFESSIONALS' || visibility === 'PORTABLE' || visibility === 'IMPORTED';
}

function buildTimelineItemsFromSharedSnapshot(params: {
  snapshot: any;
  patientId: string;
  clinicId: string;
  actorId?: string | null;
}) {
  const snapshotData = parseStoredJsonObject(params.snapshot?.snapshot_data || params.snapshot?.snapshotData);
  const scope = normalizePatientPortabilityScope(params.snapshot?.scope || snapshotData?.scope);
  const snapshotId = sanitizeString(params.snapshot?.id, 120);
  const sourceOrganizationId = sanitizeString(
    params.snapshot?.organization_id_source || params.snapshot?.organizationIdSource || snapshotData?.sourceOrganizationId,
    120,
  );
  const sourcePatientId = sanitizeString(params.snapshot?.patient_id_source || params.snapshot?.patientIdSource, 120);
  const generatedAt = sanitizeString(params.snapshot?.generated_at || params.snapshot?.generatedAt, 80) || new Date().toISOString();
  const base = {
    organization_id: params.clinicId,
    patient_id: params.patientId,
    source_organization_id: sourceOrganizationId || null,
    source_patient_id: sourcePatientId || null,
    imported_from_snapshot_id: snapshotId || null,
    is_imported: true,
    is_read_only: true,
    created_by: sanitizeString(params.actorId, 120) || null,
    imported_at: new Date().toISOString()
  };
  const items: any[] = [];

  if (snapshotData?.demographics && scope.demographics) {
    const itemData = sanitizeClinicalPayload({ demographics: snapshotData.demographics });
    items.push({
      ...base,
      item_type: 'PORTABILITY_IMPORT',
      item_title: 'Dados cadastrais compartilhados',
      item_date: generatedAt,
      item_data: itemData,
      visibility: 'IMPORTED',
      portability_scope: scope,
      metadata: { source: 'patient_portability_snapshot', section: 'demographics' }
    });
  }

  for (const note of Array.isArray(snapshotData?.notes) ? snapshotData.notes : []) {
    const visibility = normalizeTimelineVisibility(note?.type || note?.visibility);
    if (!isShareableTimelineVisibility(visibility)) continue;
    const itemData = sanitizeClinicalPayload({
      subject: note?.subject || null,
      content: note?.content || null,
      createdAt: note?.createdAt || note?.created_at || null
    });
    items.push({
      ...base,
      item_type: 'SHARED_NOTE',
      item_title: sanitizeString(note?.subject || 'Anotação compartilhada', 180) || 'Anotação compartilhada',
      item_date: sanitizeString(note?.createdAt || note?.created_at || generatedAt, 80) || generatedAt,
      item_data: itemData,
      visibility: 'IMPORTED',
      portability_scope: scope,
      metadata: { source: 'patient_portability_snapshot', originalVisibility: visibility }
    });
  }

  const priorTimeline = Array.isArray(snapshotData?.timelineItems)
    ? snapshotData.timelineItems
    : Array.isArray(snapshotData?.timeline_items)
      ? snapshotData.timeline_items
      : [];
  for (const prior of priorTimeline) {
    const visibility = normalizeTimelineVisibility(prior?.visibility);
    if (!isShareableTimelineVisibility(visibility)) continue;
    const itemType = sanitizeString(prior?.itemType || prior?.item_type || 'OTHER', 80).toUpperCase();
    const itemData = sanitizeClinicalPayload(prior?.itemData || prior?.item_data || prior?.data || {});
    items.push({
      ...base,
      source_organization_id: sanitizeString(prior?.sourceOrganizationId || prior?.source_organization_id || sourceOrganizationId, 120) || null,
      source_patient_id: sanitizeString(prior?.sourcePatientId || prior?.source_patient_id || sourcePatientId, 120) || null,
      item_type: itemType,
      item_title: sanitizeString(prior?.itemTitle || prior?.item_title || 'Histórico compartilhado', 180) || 'Histórico compartilhado',
      item_date: sanitizeString(prior?.itemDate || prior?.item_date || generatedAt, 80) || generatedAt,
      item_data: itemData,
      visibility: 'IMPORTED',
      portability_scope: prior?.portabilityScope || prior?.portability_scope || scope,
      metadata: { source: 'previous_imported_timeline' }
    });
  }

  return items.map((item) => ({
    ...item,
    source_hash: stableHashPayload({
      snapshotId,
      sourceOrganizationId: item.source_organization_id,
      sourcePatientId: item.source_patient_id,
      patientId: params.patientId,
      itemType: item.item_type,
      itemDate: item.item_date,
      itemTitle: item.item_title,
      itemData: item.item_data
    })
  }));
}

async function importSharedSnapshotIntoLongitudinalTimeline(params: {
  snapshot: any;
  patientId: string;
  clinicId: string;
  actorId?: string | null;
}) {
  const snapshotId = sanitizeString(params.snapshot?.id, 120);
  const idempotencyKey = stableHashPayload({
    snapshotId,
    patientId: params.patientId,
    clinicId: params.clinicId,
    action: 'shared-history-import'
  });
  const items = buildTimelineItemsFromSharedSnapshot(params);

  const { data: existingImport, error: existingImportError } = await supabase
    .from('patient_history_imports')
    .select('id, status, imported_items_count, skipped_duplicates_count')
    .eq('organization_id', params.clinicId)
    .eq('patient_id', params.patientId)
    .eq('source_snapshot_id', snapshotId)
    .eq('idempotency_key', idempotencyKey)
    .limit(1)
    .maybeSingle();
  if (existingImportError && !isMissingRelationError(existingImportError)) throw existingImportError;
  if (existingImport?.id && sanitizeString(existingImport.status, 40).toUpperCase() === 'COMPLETED') {
    return {
      success: true,
      idempotent: true,
      importedItemsCount: Number(existingImport.imported_items_count || 0),
      skippedDuplicatesCount: Number(existingImport.skipped_duplicates_count || items.length),
      message: 'Histórico compartilhado já estava importado.'
    };
  }

  const sourceHashes = items.map((item) => sanitizeString(item.source_hash, 120)).filter(Boolean);
  const existingHashes = new Set<string>();
  if (sourceHashes.length > 0) {
    const { data: existingItems, error: existingItemsError } = await supabase
      .from('patient_longitudinal_timeline_items')
      .select('source_hash')
      .eq('organization_id', params.clinicId)
      .eq('patient_id', params.patientId)
      .in('source_hash', sourceHashes)
      .limit(500);
    if (existingItemsError && !isMissingRelationError(existingItemsError)) throw existingItemsError;
    for (const row of Array.isArray(existingItems) ? existingItems : []) {
      const hash = sanitizeString(row?.source_hash, 120);
      if (hash) existingHashes.add(hash);
    }
  }

  let importedItemsCount = 0;
  let skippedDuplicatesCount = 0;
  for (const item of items) {
    if (existingHashes.has(sanitizeString(item.source_hash, 120))) {
      skippedDuplicatesCount += 1;
      continue;
    }
    const insert = await insertRowWithSchemaFallback('patient_longitudinal_timeline_items', item, 'shared-history-import-timeline-item');
    if (!insert.success) {
      if (isMissingRelationError(insert.error)) break;
      throw insert.error;
    }
    importedItemsCount += 1;
  }

  const importInsert = await insertRowWithSchemaFallback('patient_history_imports', {
    organization_id: params.clinicId,
    patient_id: params.patientId,
    source_snapshot_id: snapshotId,
    source_organization_id: sanitizeString(params.snapshot?.organization_id_source, 120) || null,
    imported_by: sanitizeString(params.actorId, 120) || null,
    imported_at: new Date().toISOString(),
    status: 'COMPLETED',
    imported_items_count: importedItemsCount,
    skipped_duplicates_count: skippedDuplicatesCount,
    idempotency_key: idempotencyKey,
    metadata: { source: 'shared_history_snapshot', readOnly: true }
  }, 'shared-history-import-record');
  if (!importInsert.success && !isMissingRelationError(importInsert.error)) throw importInsert.error;

  return {
    success: true,
    idempotent: importedItemsCount === 0 && skippedDuplicatesCount > 0,
    importedItemsCount,
    skippedDuplicatesCount,
    message: importedItemsCount === 0 && skippedDuplicatesCount > 0
      ? 'Histórico compartilhado já estava importado.'
      : 'Histórico compartilhado importado.'
  };
}

async function updatePatientOnboardingWithSchemaFallback(params: {
  patientId: string;
  clinicId?: string | null;
  patch: Record<string, any>;
  context?: string;
}) {
  const patientId = sanitizeString(params.patientId, 120);
  if (!isUuid(patientId)) return { success: false, error: new Error('Paciente inválido.') };
  const filters = [{ column: 'id', value: patientId }];
  const clinicId = sanitizeString(params.clinicId, 120);
  if (isUuid(clinicId)) filters.push({ column: 'clinic_id', value: clinicId });

  let triedLegacyPendingStatus = false;
  let payload = cleanObject({
    ...params.patch,
    updated_at: new Date().toISOString()
  });

  for (let attempt = 0; attempt < 5; attempt += 1) {
    const result = await updateRowsWithSchemaFallback({
      tableName: 'patients',
      payload,
      filters,
      context: params.context || 'patient-onboarding'
    });
    if (result.success) return result;

    const errorMessage = extractSupabaseErrorMessage(result.error).toLowerCase();
    if (
      !triedLegacyPendingStatus &&
      Object.prototype.hasOwnProperty.call(payload, 'status') &&
      (sanitizeString(result.error?.code, 20) === '23514' || errorMessage.includes('check constraint'))
    ) {
      triedLegacyPendingStatus = true;
      payload = { ...payload, status: 'pending' };
      continue;
    }

    return result;
  }

  return { success: false, error: new Error('Falha ao atualizar status do paciente.') };
}

async function findDuplicatePatientInClinic(params: {
  clinicId?: unknown;
  name?: unknown;
  email?: unknown;
  cpf?: unknown;
  excludePatientId?: unknown;
  clientRecordId?: unknown;
  includeLegacyRecordScan?: boolean;
}): Promise<{ field: 'email' | 'cpf' | 'client_record_id'; patientId: string; patientName: string; value: string; row?: any } | null> {
  const safeClinicId = sanitizeString(params.clinicId, 120);
  if (!safeClinicId || !isUuid(safeClinicId)) return null;

  const normalizePatientMatchName = (value: unknown) =>
    sanitizeString(value, 180)
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();

  const safeName = normalizePatientMatchName(params.name);
  const safeEmail = sanitizeEmail(params.email);
  const safeCpf = normalizeCpf(params.cpf);
  const safeClientRecordId = sanitizeString(params.clientRecordId, 120);
  const excludedId = sanitizeString(params.excludePatientId, 120);
  const isExcluded = (candidateId: unknown) =>
    Boolean(excludedId && sanitizeString(candidateId, 120) === excludedId);

  if (safeClientRecordId) {
    const clientRows = await queryPatientsWithSchemaFallback({
      context: 'duplicate-client-record',
      selectColumns: ['id', 'name', 'email', 'cpf', 'client_record_id', 'status'],
      filters: [
        { op: 'eq', column: 'clinic_id', value: safeClinicId },
        { op: 'eq', column: 'client_record_id', value: safeClientRecordId, onMissing: 'empty' },
        { op: 'eq', column: 'is_active', value: true, onMissing: 'omit' },
        { op: 'is', column: 'deleted_at', value: null, onMissing: 'omit' }
      ],
      limit: 10
    });

    const hit = (clientRows || []).find((row: any) => !isExcluded(row?.id));
    if (hit?.id) {
      return {
        field: 'client_record_id',
        patientId: sanitizeString(hit.id, 120),
        patientName: sanitizeString(hit.name, 180) || 'Paciente',
        value: safeClientRecordId,
        row: hit
      };
    }
  }

  if (safeCpf) {
    const cpfRows = await queryPatientsWithSchemaFallback({
      context: 'duplicate-cpf',
      selectColumns: ['id', 'name', 'cpf', 'status'],
      filters: [
        { op: 'eq', column: 'clinic_id', value: safeClinicId },
        { op: 'eq', column: 'cpf', value: safeCpf, onMissing: 'empty' },
        { op: 'eq', column: 'is_active', value: true, onMissing: 'omit' },
        { op: 'is', column: 'deleted_at', value: null, onMissing: 'omit' }
      ],
      limit: 10
    });

    const hit = (cpfRows || []).find((row: any) => !isExcluded(row?.id));
    if (hit?.id) {
      return {
        field: 'cpf',
        patientId: sanitizeString(hit.id, 120),
        patientName: sanitizeString(hit.name, 180) || 'Paciente',
        value: safeCpf,
        row: hit
      };
    }

    if (params.includeLegacyRecordScan === true) {
      // Fallback de CPF para ambientes legados: busca no payload criptografado.
      // Mantido opt-in porque o scan pode ser caro em produção durante cadastro.
      const { data: recordRows, error: recordError } = await supabase
        .from('patient_records')
        .select('patient_id, payload_encrypted')
        .eq('clinic_id', safeClinicId)
        .limit(300);

      if (recordError) {
        const missingTable = String(recordError?.message || '')
          .toLowerCase()
          .includes('patient_records');
        if (!missingTable) throw recordError;
      } else {
        for (const row of recordRows || []) {
          const candidatePatientId = sanitizeString((row as any)?.patient_id, 120);
          if (!candidatePatientId || isExcluded(candidatePatientId)) continue;
          const decryptedPayload = decryptJsonPayload(
            sanitizeString((row as any)?.payload_encrypted, 2_000_000),
          );
          const payloadCpf = normalizeCpf((decryptedPayload as any)?.cpf);
          if (payloadCpf && payloadCpf === safeCpf) {
            const { data: patientRow } = await supabase
              .from('patients')
              .select('id, name')
              .eq('id', candidatePatientId)
              .maybeSingle();
            return {
              field: 'cpf',
              patientId: sanitizeString(patientRow?.id || candidatePatientId, 120),
              patientName: sanitizeString(patientRow?.name, 180) || 'Paciente',
              value: safeCpf,
              row: patientRow
            };
          }
        }
      }
    }
  }

  if (safeEmail && safeName) {
    const emailRows = await queryPatientsWithSchemaFallback({
      context: 'duplicate-email',
      selectColumns: ['id', 'name', 'email', 'cpf', 'status'],
      filters: [
        { op: 'eq', column: 'clinic_id', value: safeClinicId },
        { op: 'eq', column: 'email', value: safeEmail },
        { op: 'eq', column: 'is_active', value: true, onMissing: 'omit' },
        { op: 'is', column: 'deleted_at', value: null, onMissing: 'omit' }
      ],
      limit: 20
    });

    const hit = (emailRows || []).find((row: any) => (
      !isExcluded(row?.id) &&
      normalizePatientMatchName(row?.name) === safeName
    ));
    if (hit?.id) {
      return {
        field: 'email',
        patientId: sanitizeString(hit.id, 120),
        patientName: sanitizeString(hit.name, 180) || 'Paciente',
        value: safeEmail,
        row: hit
      };
    }
  }

  return null;
}

function normalizePatientSpecialtyKey(value: unknown, fallback?: unknown): string {
  const direct = normalizePatientFinancialServiceType(value, fallback);
  if (direct && direct !== 'CUSTOM') return direct;
  const fallbackNormalized = normalizePatientFinancialServiceType('', fallback ?? value);
  if (fallbackNormalized && fallbackNormalized !== 'CUSTOM') return fallbackNormalized;
  const custom = sanitizeString(fallback ?? value, 120)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/gi, '_')
    .replace(/^_+|_+$/g, '')
    .toUpperCase();
  return custom ? `CUSTOM:${custom}` : '';
}

function derivePatientSpecialtyKeysFromPayload(input: any): string[] {
  const keys = new Set<string>();
  const add = (value: unknown, fallback?: unknown) => {
    const key = normalizePatientSpecialtyKey(value, fallback);
    if (key) keys.add(key);
  };

  const plans = Array.isArray(input?.financialPlans)
    ? input.financialPlans
    : Array.isArray(input?.financial_plans)
      ? input.financial_plans
      : [];
  plans.forEach((plan: any) => {
    add(
      plan?.serviceType || plan?.service_type,
      plan?.customServiceName ||
        plan?.custom_service_name ||
        plan?.serviceNameSnapshot ||
        plan?.service_name_snapshot ||
        plan?.specialty
    );
  });

  add(input?.serviceType || input?.service_type, input?.specialty || input?.specialtyName);
  add(input?.approach);
  const rawType = sanitizeString(input?.type, 120).toLowerCase();
  if (rawType && !['kids_tea', 'adult_tea', 'adult_conventional', 'conventional'].includes(rawType)) {
    add(input?.type);
  }

  const profileType = normalizePatientProfileType(
    input?.patientProfileType ||
      input?.patient_profile_type ||
      input?.panelType ||
      input?.panel_type ||
      input?.profileType ||
      input?.profile_type ||
      input?.type,
    'ADULT' as any
  );
  if (profileType === 'KIDS' || profileType === 'ABA') keys.add('ABA');

  return Array.from(keys);
}

async function fetchSpecialtyKeysForPatientRows(patientRows: any[]): Promise<Map<string, Set<string>>> {
  const result = new Map<string, Set<string>>();
  const patientIds = Array.from(
    new Set(
      (patientRows || [])
        .map((row: any) => sanitizeString(row?.id, 120))
        .filter((id: string) => isUuid(id))
    )
  );
  const ensureSet = (patientId: string) => {
    const existing = result.get(patientId) || new Set<string>();
    result.set(patientId, existing);
    return existing;
  };

  patientRows.forEach((row: any) => {
    const patientId = sanitizeString(row?.id, 120);
    if (!patientId) return;
    derivePatientSpecialtyKeysFromPayload(row).forEach((key) => ensureSet(patientId).add(key));
  });

  if (patientIds.length) {
    try {
      const { data: plans, error } = await supabase
        .from('patient_financial_plans')
        .select('patient_id, service_type, service_name_snapshot')
        .in('patient_id', patientIds)
        .limit(Math.min(500, patientIds.length * 20));
      if (!error) {
        (plans || []).forEach((plan: any) => {
          const patientId = sanitizeString(plan?.patient_id, 120);
          if (!patientId) return;
          derivePatientSpecialtyKeysFromPayload({
            financialPlans: [{
              serviceType: plan?.service_type,
              serviceNameSnapshot: plan?.service_name_snapshot
            }]
          }).forEach((key) => ensureSet(patientId).add(key));
        });
      } else if (!isMissingRelationError(error)) {
        console.warn('[PatientSpecialty] patient_financial_plans indisponivel:', sanitizeString(error?.message || String(error), 180));
      }
    } catch (error: any) {
      console.warn('[PatientSpecialty] falha ao buscar planos financeiros:', sanitizeString(error?.message || String(error), 180));
    }

    try {
      const { data: records, error } = await supabase
        .from('patient_records')
        .select('patient_id, payload_encrypted')
        .in('patient_id', patientIds)
        .limit(patientIds.length);
      if (!error) {
        (records || []).forEach((record: any) => {
          const patientId = sanitizeString(record?.patient_id, 120);
          if (!patientId) return;
          const payload = decryptJsonPayload(sanitizeString(record?.payload_encrypted, 2_000_000));
          derivePatientSpecialtyKeysFromPayload(payload).forEach((key) => ensureSet(patientId).add(key));
        });
      } else if (!isMissingRelationError(error)) {
        console.warn('[PatientSpecialty] patient_records indisponivel:', sanitizeString(error?.message || String(error), 180));
      }
    } catch (error: any) {
      console.warn('[PatientSpecialty] falha ao buscar prontuarios:', sanitizeString(error?.message || String(error), 180));
    }
  }

  return result;
}

async function findPatientSpecialtyConflictAcrossClinics(params: {
  clinicId?: unknown;
  email?: unknown;
  cpf?: unknown;
  requestedSpecialtyKeys?: string[];
  excludePatientId?: unknown;
}): Promise<{ patientId: string; patientName: string; clinicId: string; specialtyKey: string; row?: any } | null> {
  const safeClinicId = sanitizeString(params.clinicId, 120);
  const safeEmail = sanitizeEmail(params.email);
  const safeCpf = normalizeCpf(params.cpf);
  const excludedId = sanitizeString(params.excludePatientId, 120);
  const requested = new Set((params.requestedSpecialtyKeys || []).filter(Boolean));
  if (!safeClinicId || requested.size === 0 || (!safeEmail && !safeCpf)) return null;

  const rowsById = new Map<string, any>();
  const collect = (rows: any[] = []) => {
    rows.forEach((row: any) => {
      const id = sanitizeString(row?.id, 120);
      if (!id || id === excludedId) return;
      const rowClinicId = sanitizeString(row?.clinic_id, 120);
      if (!rowClinicId || rowClinicId === safeClinicId) return;
      rowsById.set(id, row);
    });
  };

  const select = ['id', 'name', 'email', 'cpf', 'clinic_id', 'status', 'patient_profile_type', 'panel_type', 'profile_type', 'type'];
  if (safeEmail) {
    try {
      const data = await queryPatientsWithSchemaFallback({
        context: 'specialty-conflict-email',
        selectColumns: select,
        filters: [
          { op: 'ilike', column: 'email', value: safeEmail },
          { op: 'eq', column: 'is_active', value: true, onMissing: 'omit' },
          { op: 'is', column: 'deleted_at', value: null, onMissing: 'omit' }
        ],
        limit: 50
      });
      collect(data || []);
    } catch (error: any) {
      console.warn('[PatientSpecialty] falha ao buscar paciente por e-mail:', sanitizeString(error?.message || String(error), 180));
    }
  }

  if (safeCpf) {
    try {
      const data = await queryPatientsWithSchemaFallback({
        context: 'specialty-conflict-cpf',
        selectColumns: select,
        filters: [
          { op: 'eq', column: 'cpf', value: safeCpf, onMissing: 'empty' },
          { op: 'eq', column: 'is_active', value: true, onMissing: 'omit' },
          { op: 'is', column: 'deleted_at', value: null, onMissing: 'omit' }
        ],
        limit: 50
      });
      collect(data || []);
    } catch (error: any) {
      console.warn('[PatientSpecialty] falha ao buscar paciente por CPF:', sanitizeString(error?.message || String(error), 180));
    }
  }

  const rows = Array.from(rowsById.values());
  if (!rows.length) return null;
  const specialtiesByPatient = await fetchSpecialtyKeysForPatientRows(rows);

  for (const row of rows) {
    const patientId = sanitizeString(row?.id, 120);
    const rowKeys = specialtiesByPatient.get(patientId) || new Set<string>();
    for (const key of rowKeys) {
      if (requested.has(key)) {
        return {
          patientId,
          patientName: sanitizeString(row?.name, 180) || 'Paciente',
          clinicId: sanitizeString(row?.clinic_id, 120),
          specialtyKey: key,
          row
        };
      }
    }
  }

  return null;
}

async function getClinicPatientIdsByEmail(clinicId: string, patientEmail: string): Promise<string[]> {
  const { data, error } = await supabase
    .from('patients')
    .select('id')
    .eq('clinic_id', clinicId)
    .eq('email', patientEmail)
    .eq('is_active', true)
    .is('deleted_at', null)
    .limit(500);

  if (error) return [];
  return (data || [])
    .map((row: any) => sanitizeString(row?.id, 120))
    .filter((id: string) => isUuid(id));
}

async function getPatientIdsByEmailAcrossClinics(patientEmail: string): Promise<string[]> {
  const safeEmail = sanitizeEmail(patientEmail);
  if (!safeEmail) return [];
  const { data, error } = await supabase
    .from('patients')
    .select('id')
    .ilike('email', safeEmail)
    .eq('is_active', true)
    .is('deleted_at', null)
    .limit(1000);
  if (error) return [];
  return (data || [])
    .map((row: any) => sanitizeString(row?.id, 120))
    .filter((id: string) => isUuid(id));
}

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
function isUuid(value: string | null | undefined): boolean {
  if (!value) return false;
  return UUID_REGEX.test(value);
}

function parseTaskScheduleToMs(value: string | null | undefined): number | null {
  const raw = sanitizeString(value, 80);
  if (!raw) return null;

  const direct = new Date(raw).getTime();
  if (Number.isFinite(direct)) return direct;

  const brMatch = raw.match(/^(\d{2})\/(\d{2})\/(\d{4})(?:[ T](\d{2}):(\d{2})(?::(\d{2}))?)?$/);
  if (brMatch) {
    const [, dd, mm, yyyy, hh = '00', min = '00', ss = '00'] = brMatch;
    const isoLike = `${yyyy}-${mm}-${dd}T${hh}:${min}:${ss}`;
    const parsed = new Date(isoLike).getTime();
    if (Number.isFinite(parsed)) return parsed;
  }

  return null;
}

function derivePatientNameFromLegacyId(rawId: string): string {
  const base = rawId
    .replace(/^mock-/i, '')
    .replace(/-\d+$/i, '')
    .replace(/[_-]+/g, ' ')
    .trim();
  if (!base) return 'Paciente';
  return base
    .split(' ')
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1).toLowerCase())
    .join(' ');
}

async function resolvePatientIdForRequest(
  rawPatientId: string,
  user: any,
  options: { createIfMissing?: boolean; fallbackName?: string } = {}
): Promise<string | null> {
  const safeRaw = sanitizeString(rawPatientId, 120);
  if (!safeRaw) return null;
  if (isUuid(safeRaw)) {
    const role = sanitizeString(user?.role, 40).toLowerCase();
    const safeEmail = sanitizeEmail(user?.email);
    const clinicId = currentClinicId(user);

    const { data: byId, error: byIdError } = await supabase
      .from('patients')
      .select('id')
      .eq('id', safeRaw)
      .eq('is_active', true)
      .is('deleted_at', null)
      .maybeSingle();

    if (!byIdError && byId?.id) return sanitizeString(byId.id, 120);

    // Patient sessions can send auth user UUID instead of patients.id.
    // In this case, resolve by e-mail to keep persistence linked correctly.
    if (role === 'patient' && safeEmail) {
      const resolveByEmailRows = async (scopedToClinic: boolean) => {
        let byEmailQuery = supabase
          .from('patients')
          .select('id')
          .ilike('email', safeEmail)
          .eq('is_active', true)
          .is('deleted_at', null)
          .order('created_at', { ascending: false })
          .limit(1);
        if (scopedToClinic && clinicId) {
          byEmailQuery = byEmailQuery.eq('clinic_id', clinicId);
        }
        return await byEmailQuery;
      };

      // 1) Try clinic-scoped match first (when session has clinic context)
      const { data: byEmailScopedRows, error: byEmailScopedError } = await resolveByEmailRows(true);
      if (!byEmailScopedError && Array.isArray(byEmailScopedRows) && byEmailScopedRows[0]?.id) {
        return sanitizeString(byEmailScopedRows[0].id, 120);
      }

      // 2) Fallback to any clinic match for this e-mail
      const { data: byEmailRows, error: byEmailError } = await resolveByEmailRows(false);
      if (!byEmailError && Array.isArray(byEmailRows) && byEmailRows[0]?.id) {
        return sanitizeString(byEmailRows[0].id, 120);
      }
      return null;
    }

    return safeRaw;
  }

  const clinicId = currentClinicId(user);
  if (!clinicId) return null;

  const guessedName = sanitizeString(options.fallbackName, 160) || derivePatientNameFromLegacyId(safeRaw);
  let { data: foundByName } = await supabase
    .from('patients')
    .select('id, name')
    .eq('clinic_id', clinicId)
    .ilike('name', guessedName)
    .eq('is_active', true)
    .is('deleted_at', null)
    .limit(1)
    .maybeSingle();

  if (!foundByName && guessedName) {
    const relaxed = await supabase
      .from('patients')
      .select('id, name')
      .eq('clinic_id', clinicId)
      .ilike('name', `%${guessedName}%`)
      .eq('is_active', true)
      .is('deleted_at', null)
      .limit(1)
      .maybeSingle();
    foundByName = relaxed.data || null;
  }

  if (foundByName?.id) return sanitizeString(foundByName.id, 120);
  if (!options.createIfMissing) return null;

  const role = sanitizeString(user?.role, 40).toLowerCase();
  if (!['owner', 'admin', 'coordinator', 'receptionist', 'therapist'].includes(role)) return null;

  const insertPayload = {
    name: guessedName || 'Paciente',
    email: null,
    phone: null,
    age: null,
    diagnosis: null,
    status: 'active',
    clinic_id: clinicId,
    therapist_id: sanitizeString(user?.id, 120) || null,
    created_at: new Date().toISOString()
  };

  const { data: created, error: createError } = await supabase
    .from('patients')
    .insert([insertPayload])
    .select('id')
    .single();

  if (createError || !created?.id) return null;
  return sanitizeString(created.id, 120);
}

function normalizeAppointmentStatusForTable(status: unknown): string {
  const normalized = sanitizeString(status || 'scheduled', 40).toLowerCase();
  if (normalized === 'pending') return 'scheduled';
  if (normalized === 'canceled') return 'cancelled';
  if (normalized === 'reschedule') return 'rescheduled';
  if (normalized === 'missed') return 'no_show';
  if (
    normalized === 'confirmed' ||
    normalized === 'completed' ||
    normalized === 'cancelled' ||
    normalized === 'rescheduled' ||
    normalized === 'in_progress' ||
    normalized === 'no_show' ||
    normalized === 'deleted'
  ) {
    return normalized;
  }
  return 'scheduled';
}

function normalizeAppointmentStatusForUi(status: unknown): string {
  const normalized = sanitizeString(status || 'pending', 40).toLowerCase();
  if (normalized === 'scheduled') return 'pending';
  if (normalized === 'cancelled') return 'canceled';
  if (normalized === 'rescheduled') return 'reschedule';
  return normalized || 'pending';
}

function normalizeAppointmentResponseAction(action: unknown): 'confirmed' | 'reschedule' | 'canceled' | '' {
  const normalized = sanitizeString(action, 40).toLowerCase();
  if (['verto_confirm_appointment', 'confirm', 'confirmed', 'confirmar', 'accepted', 'accept'].includes(normalized)) return 'confirmed';
  if (['verto_reschedule_appointment', 'reschedule', 'rescheduled', 'remarcar', 'remarcado'].includes(normalized)) return 'reschedule';
  if (['cancel', 'canceled', 'cancelled', 'cancelar', 'cancelado'].includes(normalized)) return 'canceled';
  return '';
}

function normalizeOperationalAppointmentStatus(status: unknown): string {
  const normalized = sanitizeString(status || 'SCHEDULED', 80)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  if (['PENDING', 'PENDENTE', 'SCHEDULED', 'AGENDADA', 'AGENDADO'].includes(normalized)) return 'SCHEDULED';
  if (['PENDING_CONFIRMATION', 'PENDENTE_DE_CONFIRMACAO'].includes(normalized)) return 'PENDING_CONFIRMATION';
  if (['CONFIRMED', 'CONFIRMADA', 'CONFIRMADO'].includes(normalized)) return 'CONFIRMED';
  if (['RESCHEDULE', 'RESCHEDULE_REQUESTED', 'REMARCAR', 'REMARCACAO_SOLICITADA'].includes(normalized)) return 'RESCHEDULE_REQUESTED';
  if (['RESCHEDULED', 'REMARCADA', 'REMARCADO'].includes(normalized)) return 'RESCHEDULED';
  if (['CANCEL_REQUESTED', 'CANCELAMENTO_SOLICITADO'].includes(normalized)) return 'CANCEL_REQUESTED';
  if (['CANCEL', 'CANCELLED', 'CANCELED', 'CANCELADA', 'CANCELADO'].includes(normalized)) return 'CANCELLED';
  if (['IN_PROGRESS', 'ANDAMENTO', 'EM_ANDAMENTO'].includes(normalized)) return 'IN_PROGRESS';
  if (['COMPLETED', 'CONCLUIDA', 'CONCLUIDO'].includes(normalized)) return 'COMPLETED';
  if (['NO_SHOW', 'MISSED', 'FALTA', 'FALTOU'].includes(normalized)) return 'NO_SHOW';
  return normalized || 'SCHEDULED';
}

function isAppointmentTerminalForPortalAction(status: unknown): boolean {
  return ['CANCELLED', 'COMPLETED', 'NO_SHOW'].includes(normalizeOperationalAppointmentStatus(status));
}

function isTrustedPushNotificationAction(action: unknown): boolean {
  return ['verto_confirm_appointment', 'verto_reschedule_appointment'].includes(
    sanitizeString(action, 80).toLowerCase()
  );
}

function buildAppointmentScheduledAt(appointment: any): string | null {
  const source = parseStoredJsonObject(appointment?.source_payload || appointment?.sourcePayload);
  const explicit = sanitizeString(
    appointment?.scheduled_at ||
      appointment?.scheduledAt ||
      appointment?.scheduled_start_at ||
      appointment?.scheduledStartAt ||
      appointment?.scheduled_start ||
      appointment?.scheduledStart,
    80
  );
  const sourceExplicit = sanitizeString(
    source?.scheduled_at ||
      source?.scheduledAt ||
      source?.scheduled_start_at ||
      source?.scheduledStartAt ||
      source?.scheduled_start ||
      source?.scheduledStart,
    80
  );
  const resolvedExplicit = explicit || sourceExplicit;
  if (resolvedExplicit) {
    const parsed = new Date(resolvedExplicit);
    if (!Number.isNaN(parsed.getTime())) return parsed.toISOString();
  }

  const date = sanitizeDate(appointment?.date || source?.date);
  const time = sanitizeString(appointment?.time || source?.time, 10);
  if (!date || !/^\d{2}:\d{2}$/.test(time)) return null;

  const parsed = new Date(`${date}T${time}:00-03:00`);
  if (Number.isNaN(parsed.getTime())) return null;
  return parsed.toISOString();
}

function getAppointmentRecurrenceGroupId(appointment: any): string {
  const source = parseStoredJsonObject(appointment?.source_payload || appointment?.sourcePayload);
  return sanitizeString(
    appointment?.recurrenceGroupId ||
      appointment?.recurrence_group_id ||
      source?.recurrenceGroupId ||
      source?.recurrence_group_id,
    120,
  );
}

function getAppointmentRecurrenceIndex(appointment: any): number {
  const source = parseStoredJsonObject(appointment?.source_payload || appointment?.sourcePayload);
  const rawValue = Number(
    appointment?.recurrenceIndex ??
      appointment?.recurrence_index ??
      source?.recurrenceIndex ??
      source?.recurrence_index ??
      0,
  );
  return Number.isFinite(rawValue) ? rawValue : 0;
}

function getAppointmentPatientSeriesKey(appointment: any): string {
  const source = parseStoredJsonObject(appointment?.source_payload || appointment?.sourcePayload);
  const patientId = sanitizeString(
    appointment?.patientId || appointment?.patient_id || source?.patientId || source?.patient_id,
    120,
  );
  if (patientId) return `id:${patientId}`;
  const patientName = sanitizeString(
    appointment?.patientName || appointment?.patient_name || appointment?.name || source?.patientName || source?.patient_name || source?.name,
    180,
  )
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
  return patientName ? `name:${patientName}` : '';
}

function getAppointmentProfessionalSeriesKey(appointment: any): string {
  const source = parseStoredJsonObject(appointment?.source_payload || appointment?.sourcePayload);
  const professionalId = sanitizeString(
    appointment?.therapistId || appointment?.therapist_id || appointment?.professionalId || appointment?.professional_id ||
      source?.therapistId || source?.therapist_id || source?.professionalId || source?.professional_id,
    120,
  );
  if (professionalId) return `id:${professionalId}`;
  const professionalName = sanitizeString(
    appointment?.therapistName || appointment?.therapist_name || appointment?.professional || source?.therapistName || source?.therapist_name || source?.professional,
    180,
  )
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
  return professionalName ? `name:${professionalName}` : '';
}

function getAppointmentSeriesClockTime(appointment: any): string {
  const source = parseStoredJsonObject(appointment?.source_payload || appointment?.sourcePayload);
  const explicitTime = sanitizeString(appointment?.time || source?.time, 10).slice(0, 5);
  if (/^\d{2}:\d{2}$/.test(explicitTime)) return explicitTime;
  const scheduledAt = buildAppointmentScheduledAt(appointment);
  if (!scheduledAt) return '';
  const parsed = new Date(scheduledAt);
  if (Number.isNaN(parsed.getTime())) return '';
  return formatTimeInAppointmentTimezone(parsed);
}

function getAppointmentOccurrenceTime(appointment: any): number {
  const scheduledAt = buildAppointmentScheduledAt(appointment);
  if (scheduledAt) {
    const parsed = new Date(scheduledAt).getTime();
    if (!Number.isNaN(parsed)) return parsed;
  }

  const fallbackDate = sanitizeDate(appointment?.date);
  const fallbackTime = sanitizeString(appointment?.time, 10);
  if (fallbackDate && /^\d{2}:\d{2}$/.test(fallbackTime)) {
    const parsed = new Date(`${fallbackDate}T${fallbackTime}:00-03:00`).getTime();
    if (!Number.isNaN(parsed)) return parsed;
  }

  return Number.POSITIVE_INFINITY;
}

function isSameOrFutureRecurringAppointment(referenceAppointment: any, candidateAppointment: any): boolean {
  const referenceGroupId = getAppointmentRecurrenceGroupId(referenceAppointment);
  const candidateGroupId = getAppointmentRecurrenceGroupId(candidateAppointment);
  if (!referenceGroupId || referenceGroupId !== candidateGroupId) return false;

  const referenceIndex = getAppointmentRecurrenceIndex(referenceAppointment);
  const candidateIndex = getAppointmentRecurrenceIndex(candidateAppointment);
  if (referenceIndex > 0 && candidateIndex > 0) {
    return candidateIndex >= referenceIndex;
  }

  return getAppointmentOccurrenceTime(candidateAppointment) >= getAppointmentOccurrenceTime(referenceAppointment);
}

function isSameOrFuturePatientSeriesAppointment(referenceAppointment: any, candidateAppointment: any): boolean {
  if (String(candidateAppointment?.id) === String(referenceAppointment?.id)) return true;
  const referencePatientKey = getAppointmentPatientSeriesKey(referenceAppointment);
  const candidatePatientKey = getAppointmentPatientSeriesKey(candidateAppointment);
  if (!referencePatientKey || referencePatientKey !== candidatePatientKey) return false;

  const referenceProfessionalKey = getAppointmentProfessionalSeriesKey(referenceAppointment);
  const candidateProfessionalKey = getAppointmentProfessionalSeriesKey(candidateAppointment);
  if (referenceProfessionalKey && candidateProfessionalKey && referenceProfessionalKey !== candidateProfessionalKey) return false;

  const referenceTime = getAppointmentSeriesClockTime(referenceAppointment);
  const candidateTime = getAppointmentSeriesClockTime(candidateAppointment);
  if (referenceTime && candidateTime && referenceTime !== candidateTime) return false;

  return getAppointmentOccurrenceTime(candidateAppointment) >= getAppointmentOccurrenceTime(referenceAppointment);
}

function resetAppointmentReminderStateAfterScheduleChange(appointment: any) {
  return {
    ...appointment,
    status: 'pending',
    patientResponse: null,
    patient_response: null,
    patientRespondedAt: null,
    patient_responded_at: null,
    patientConfirmationStatus: null,
    patient_confirmation_status: null,
    patientConfirmationAt: null,
    patient_confirmation_at: null,
    patientConfirmationBy: null,
    patient_confirmation_by: null,
    patientConfirmationSource: null,
    patient_confirmation_source: null,
    notification_24h_sent_at: null,
    notification24hSentAt: null,
    notification_sent_at: null,
    notification_sent: false,
    notification_12h_sent_at: null,
    notification12hSentAt: null,
    notification_12h_sent: false
  };
}

function formatAppointmentLogDate(date: unknown) {
  const safeDate = sanitizeDate(date);
  if (!safeDate) return '';
  const [, month, day] = safeDate.split('-');
  return `${day}/${month}`;
}

function buildAppointmentLogWhen(appointment: any) {
  const dateLabel = formatAppointmentLogDate(appointment?.date);
  const timeLabel = sanitizeString(appointment?.time, 10);
  if (dateLabel && timeLabel) return `para o dia ${dateLabel} às ${timeLabel}`;
  if (dateLabel) return `para o dia ${dateLabel}`;
  if (timeLabel) return `às ${timeLabel}`;
  return '';
}

function appointmentStatusLabelForLog(status: unknown) {
  const normalized = normalizeAppointmentStatusForUi(status);
  if (normalized === 'confirmed') return { title: 'Consulta confirmada', verb: 'confirmou', actionType: 'appointment_confirmed' };
  if (normalized === 'reschedule') return { title: 'Consulta marcada para remarcação', verb: 'solicitou remarcação da', actionType: 'appointment_reschedule_requested' };
  if (normalized === 'canceled') return { title: 'Consulta cancelada', verb: 'cancelou', actionType: 'appointment_cancelled' };
  return { title: 'Consulta atualizada', verb: 'atualizou', actionType: 'appointment_status_updated' };
}

function buildAppointmentStatusLogContent(params: {
  actorName?: string | null;
  isPatientActor?: boolean;
  patientName?: string | null;
  appointment?: any;
  status?: string | null;
  note?: string | null;
}) {
  const patientName = sanitizeString(params.patientName, 180) || 'paciente';
  const when = buildAppointmentLogWhen(params.appointment);
  const statusInfo = appointmentStatusLabelForLog(params.status || params.appointment?.status);
  const note = sanitizeString(params.note, 800);
  const actorName = sanitizeString(params.actorName, 180);
  const content = params.isPatientActor
    ? `Paciente ${patientName} ${statusInfo.verb} consulta${when ? ` ${when}` : ''}.`
    : `${actorName || 'Equipe'} ${statusInfo.verb} a consulta de ${patientName}${when ? ` ${when}` : ''}.`;
  return note ? `${content} Observação: ${note}` : content;
}

function resetRescheduledAppointmentsForNewReminderCycle(nextAppointments: any[], previousAppointments: any[]) {
  const previousById = new Map(
    (previousAppointments || [])
      .map((appointment: any) => [sanitizeString(appointment?.id, 120), appointment])
      .filter(([id]) => Boolean(id))
  );

  return (nextAppointments || []).map((appointment: any) => {
    const appointmentId = sanitizeString(appointment?.id, 120);
    const previous = previousById.get(appointmentId);
    if (!previous) return appointment;

    const previousScheduledAt = buildAppointmentScheduledAt(previous);
    const nextScheduledAt = buildAppointmentScheduledAt(appointment);
    const scheduleChanged =
      Boolean(previousScheduledAt && nextScheduledAt && previousScheduledAt !== nextScheduledAt) ||
      sanitizeDate(previous?.date) !== sanitizeDate(appointment?.date) ||
      sanitizeString(previous?.time, 10) !== sanitizeString(appointment?.time, 10);

    return scheduleChanged
      ? resetAppointmentReminderStateAfterScheduleChange(appointment)
      : appointment;
  });
}

function getClinicStateAppointmentStatusBlocksConflict(appointment: any) {
  const normalized = sanitizeString(appointment?.status || 'scheduled', 40).toLowerCase();
  if (['canceled', 'cancelled', 'no_show', 'missed', 'deleted', 'completed'].includes(normalized)) return false;
  return ['scheduled', 'pending', 'confirmed', 'in_progress'].includes(normalized);
}

function getClinicStateAppointmentDurationMinutes(appointment: any, specialtySettings: Record<string, any> = {}) {
  const approach = sanitizeString(appointment?.type || appointment?.approach || appointment?.service_type, 120);
  return normalizeDurationMinutes(
    appointment?.duration_minutes ||
      appointment?.durationMinutes ||
      appointment?.scheduled_duration_minutes ||
      appointment?.scheduledDurationMinutes ||
      specialtySettings?.[approach] ||
      50,
    50
  );
}

function getClinicStateAppointmentProfessionals(appointment: any) {
  const ids = Array.from(new Set([
    appointment?.professionalId,
    appointment?.professional_id,
    appointment?.therapistId,
    appointment?.therapist_id,
    ...(Array.isArray(appointment?.professionalIds) ? appointment.professionalIds : []),
    ...(Array.isArray(appointment?.professional_ids) ? appointment.professional_ids : []),
    ...(Array.isArray(appointment?.teamProfessionalIds) ? appointment.teamProfessionalIds : []),
    ...(Array.isArray(appointment?.team_professional_ids) ? appointment.team_professional_ids : [])
  ].map((value) => sanitizeString(value, 120)).filter(Boolean)));
  const names = Array.from(new Set([
    appointment?.professional,
    appointment?.professionalName,
    appointment?.professional_name,
    appointment?.therapistName,
    appointment?.therapist_name,
    ...(Array.isArray(appointment?.professionalNames) ? appointment.professionalNames : []),
    ...(Array.isArray(appointment?.professional_names) ? appointment.professional_names : []),
    ...(Array.isArray(appointment?.teamProfessionalNames) ? appointment.teamProfessionalNames : [])
  ].map((value) => sanitizeString(value, 180)).filter(Boolean)));
  return { ids, names };
}

function validateClinicStateAppointmentsForScheduleConflicts(params: {
  appointments: any[];
  rooms?: any[];
  specialtySettings?: Record<string, any>;
}) {
  const appointments = Array.isArray(params.appointments) ? params.appointments : [];
  const roomsById = new Map(
    (Array.isArray(params.rooms) ? params.rooms : [])
      .map((room: any) => [sanitizeString(room?.id, 180), room])
      .filter(([id]) => Boolean(id))
  );
  const active = appointments
    .map((appointment: any, index: number) => {
      const date = sanitizeDate(appointment?.date);
      const startTime = sanitizeString(appointment?.time, 10).slice(0, 5);
      const durationMinutes = getClinicStateAppointmentDurationMinutes(appointment, params.specialtySettings || {});
      const endTime = addMinutesToTime(startTime, durationMinutes);
      const locationType = normalizeScheduleLocationType(
        appointment?.location_type ||
          appointment?.locationType ||
          appointment?.location ||
          (appointment?.room || appointment?.room_id || appointment?.roomId ? 'clinica' : 'outro')
      );
      const roomId = locationType === 'clinica'
        ? sanitizeString(appointment?.room_id || appointment?.roomId || appointment?.room, 180)
        : '';
      const room = roomId ? roomsById.get(roomId) : null;
      const roomName = sanitizeString(appointment?.room_name || appointment?.roomName || room?.name || roomId, 180);
      const patientId = sanitizeString(appointment?.patientId || appointment?.patient_id, 120);
      const patientName = sanitizeString(appointment?.patientName || appointment?.patient_name || appointment?.name, 180);
      const professionals = getClinicStateAppointmentProfessionals(appointment);
      return {
        index,
        id: sanitizeString(appointment?.id, 180),
        date,
        startTime,
        endTime,
        durationMinutes,
        locationType,
        roomId,
        roomName,
        patientId,
        patientName,
        professionalIds: professionals.ids,
        professionalNames: professionals.names,
        blocks: getClinicStateAppointmentStatusBlocksConflict(appointment)
      };
    })
    .filter((appointment) => appointment.blocks && appointment.date && appointment.startTime);

  for (const appointment of active) {
    if (appointment.locationType === 'clinica' && !appointment.roomId) {
      return {
        ok: false,
        status: 409,
        error: 'Selecione uma sala da clínica para este atendimento.'
      };
    }
  }

  for (let index = 0; index < active.length; index += 1) {
    const current = active[index];
    for (let otherIndex = index + 1; otherIndex < active.length; otherIndex += 1) {
      const other = active[otherIndex];
      if (current.date !== other.date) continue;
      if (!appointmentTimesOverlap(current.startTime, current.endTime, other.startTime, other.endTime)) continue;

      const samePatient =
        (current.patientId && other.patientId && current.patientId === other.patientId) ||
        (!current.patientId && !other.patientId && current.patientName && current.patientName === other.patientName);
      if (samePatient) {
        return {
          ok: false,
          status: 409,
          error: `${current.patientName || 'Paciente'} já possui outra sessão nesse horário.`
        };
      }

      const sameRoom =
        current.locationType === 'clinica' &&
        other.locationType === 'clinica' &&
        current.roomId &&
        current.roomId === other.roomId;
      if (sameRoom) {
        return {
          ok: false,
          status: 409,
          error: `${current.roomName || 'Sala'} já está ocupada das ${other.startTime} às ${other.endTime} com ${other.patientName || 'outro paciente'}.`
        };
      }

      const professionalIdConflict = current.professionalIds.some((id: string) => other.professionalIds.includes(id));
      const professionalNameConflict = current.professionalNames.some((name: string) => other.professionalNames.includes(name));
      if (professionalIdConflict || professionalNameConflict) {
        const professionalName =
          current.professionalNames.find((name: string) => other.professionalNames.includes(name)) ||
          current.professionalNames[0] ||
          other.professionalNames[0] ||
          'Profissional';
        return {
          ok: false,
          status: 409,
          error: `${professionalName} já possui atendimento das ${other.startTime} às ${other.endTime}.`
        };
      }
    }
  }

  return { ok: true, status: 200, error: '' };
}

async function upsertAppointmentMirrorRow(row: Record<string, any>, logger: Pick<Console, 'warn'> = console) {
  let payload: Record<string, any> = cleanObject(row);
  let triedLegacyPendingStatus = false;

  while (Object.keys(payload).length > 0) {
    const { error } = await supabase
      .from('appointments')
      .upsert([payload], { onConflict: 'id' });

    if (!error) return true;

    const missingColumn = extractMissingColumnName(error);
    if (missingColumn && missingColumn in payload) {
      delete payload[missingColumn];
      continue;
    }

    if (!triedLegacyPendingStatus && /status|check constraint/i.test(String(error.message || ''))) {
      triedLegacyPendingStatus = true;
      payload.status = normalizeAppointmentStatusForUi(payload.status);
      continue;
    }

    logger.warn('[Appointments] Falha ao espelhar agenda na tabela appointments.', {
      appointmentId: row?.id,
      message: error.message
    });
    return false;
  }

  return false;
}

async function syncAppointmentProfessionalsMirrorRows(params: {
  appointmentId: string;
  organizationId: string;
  clinicId: string;
  professionalIds: string[];
  professionalName?: string | null;
}) {
  const appointmentId = sanitizeString(params.appointmentId, 180);
  if (!isUuid(appointmentId)) return;
  const professionalIds = Array.from(new Set((params.professionalIds || []).filter((id) => isUuid(id)))).slice(0, 20);
  if (professionalIds.length === 0) return;
  const deleteResult = await supabase
    .from('appointment_professionals')
    .delete()
    .eq('appointment_id', appointmentId);
  if (deleteResult.error) {
    if (hasMissingFinancialSchema(deleteResult.error)) return;
    console.warn('[Appointments] Falha ao atualizar equipe do agendamento.', deleteResult.error.message);
    return;
  }
  const now = new Date().toISOString();
  const rows = professionalIds.map((professionalId, index) => ({
    organization_id: isUuid(params.organizationId) ? params.organizationId : params.clinicId,
    clinic_id: isUuid(params.clinicId) ? params.clinicId : null,
    appointment_id: appointmentId,
    professional_id: professionalId,
    professional_name: index === 0 ? sanitizeString(params.professionalName, 180) || null : null,
    role: index === 0 ? 'responsavel' : 'equipe',
    created_at: now
  }));
  const upsertResult = await supabase
    .from('appointment_professionals')
    .upsert(rows, { onConflict: 'appointment_id,professional_id' });
  if (upsertResult.error && !hasMissingFinancialSchema(upsertResult.error)) {
    console.warn('[Appointments] Falha ao espelhar equipe do agendamento.', upsertResult.error.message);
  }
}

function normalizeBillingServiceMatchKey(value: any): string {
  const raw = sanitizeString(value, 120)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  const aliases: Record<string, string> = {
    aba: 'ABA',
    fono: 'SPEECH_THERAPY',
    fonoaudiologia: 'SPEECH_THERAPY',
    speech_therapy: 'SPEECH_THERAPY',
    psicologia: 'PSYCHOLOGY',
    psychology: 'PSYCHOLOGY',
    terapia_ocupacional: 'OCCUPATIONAL_THERAPY',
    occupational_therapy: 'OCCUPATIONAL_THERAPY',
    to: 'OCCUPATIONAL_THERAPY',
    psicopedagogia: 'PSYCHOPEDAGOGY',
    physiotherapy: 'PHYSIOTHERAPY',
    fisioterapia: 'PHYSIOTHERAPY',
    therapy: 'THERAPY',
    terapia: 'THERAPY'
  };
  return aliases[raw] || raw.toUpperCase();
}

function financialPlanMatchesAppointmentService(plan: any, appointmentServiceType: any): boolean {
  const appointmentKey = normalizeBillingServiceMatchKey(appointmentServiceType);
  if (!appointmentKey) return false;
  const planKeys = [
    plan?.service_type,
    plan?.serviceType,
    plan?.custom_service_name,
    plan?.customServiceName,
    plan?.service_name_snapshot,
    plan?.serviceNameSnapshot
  ]
    .map(normalizeBillingServiceMatchKey)
    .filter(Boolean);
  return planKeys.includes(appointmentKey);
}

async function resolveAppointmentBillingSuggestion(params: {
  organizationId: string;
  patientId: string;
  serviceType?: string | null;
}) {
  const organizationId = sanitizeString(params.organizationId, 120);
  const patientId = sanitizeString(params.patientId, 120);
  if (!isUuid(organizationId) || !isUuid(patientId)) return null;
  const serviceType = sanitizeString(params.serviceType, 120);

  const planResult = await supabase
    .from('patient_financial_plans')
    .select(PATIENT_FINANCIAL_PLAN_SELECT)
    .eq('organization_id', organizationId)
    .eq('patient_id', patientId)
    .eq('status', 'ACTIVE')
    .eq('billing_mode', 'INSURANCE')
    .limit(20);
  if (planResult.error && !hasMissingFinancialSchema(planResult.error)) throw planResult.error;
  const plans = planResult.error ? [] : Array.isArray(planResult.data) ? planResult.data : [];
  const patientResult = await supabase
    .from('patients')
    .select('id, insurance_type, insurance_name, insurance_card_number')
    .eq('id', patientId)
    .eq('clinic_id', organizationId)
    .limit(1)
    .maybeSingle();
  if (patientResult.error) {
    if (!hasMissingFinancialSchema(patientResult.error)) throw patientResult.error;
  }
  const patientBillingRow = patientResult.error ? null : patientResult.data;
  const patientInsuranceCardNumber = sanitizeString(patientBillingRow?.insurance_card_number, 120);
  const usablePlans = plans.filter((plan: any) =>
    isUuid(sanitizeString(plan?.payer_id, 120)) || Boolean(sanitizeString(plan?.payer_name_snapshot, 180))
  );
  const matchingPlans = serviceType
    ? usablePlans.filter((plan: any) => financialPlanMatchesAppointmentService(plan, serviceType))
    : [];
  const selectedPlan =
    matchingPlans.length === 1
      ? matchingPlans[0]
      : !serviceType && usablePlans.length === 1
        ? usablePlans[0]
        : null;
  if (selectedPlan) {
    let payerName = sanitizeString(selectedPlan.payer_name_snapshot, 180);
    const payerId = sanitizeString(selectedPlan.payer_id, 120);
    if (!payerName && isUuid(payerId)) {
      const payerResult = await supabase
        .from('clinic_payers')
        .select('id, name')
        .eq('organization_id', organizationId)
        .eq('id', payerId)
        .limit(1)
        .maybeSingle();
      if (payerResult.error && !hasMissingFinancialSchema(payerResult.error)) throw payerResult.error;
      payerName = sanitizeString(payerResult.data?.name, 180);
    }
    return {
      payerId: isUuid(payerId) ? payerId : null,
      payerName: payerName || null,
      serviceType: sanitizeString(selectedPlan.service_type || serviceType, 120) || null,
      insuranceCardNumber: patientInsuranceCardNumber || null,
      insurancePlanName: sanitizeString(selectedPlan.insurance_plan_name, 160) || null,
      authorizationCode: sanitizeString(selectedPlan.authorization_code, 120) || null,
      guideNumber: null,
      notes: sanitizeTextField(selectedPlan.notes, 1200) || null,
      source: 'PATIENT_DEFAULT'
    };
  }

  const insuranceName = sanitizeString(patientBillingRow?.insurance_name, 180);
  const insuranceType = sanitizeString(patientBillingRow?.insurance_type, 80)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
  if (!insuranceName || insuranceType === 'particular' || insuranceType === 'private') return null;
  const payerResult = await supabase
    .from('clinic_payers')
    .select('id, name')
    .eq('organization_id', organizationId)
    .ilike('name', insuranceName)
    .limit(2);
  if (payerResult.error && !hasMissingFinancialSchema(payerResult.error)) throw payerResult.error;
  const matchingPayer = Array.isArray(payerResult.data) && payerResult.data.length === 1 ? payerResult.data[0] : null;
  return {
    payerId: isUuid(sanitizeString(matchingPayer?.id, 120)) ? sanitizeString(matchingPayer.id, 120) : null,
    payerName: sanitizeString(matchingPayer?.name || insuranceName, 180) || null,
    serviceType: serviceType || null,
    insuranceCardNumber: patientInsuranceCardNumber || null,
    insurancePlanName: null,
    authorizationCode: null,
    guideNumber: null,
    notes: null,
    source: 'PATIENT_DEFAULT'
  };
}

async function upsertInitialBillingContextFromAppointment(params: {
  organizationId: string;
  appointmentId: string;
  patientId: string;
  appointment: any;
}) {
  const organizationId = sanitizeString(params.organizationId, 120);
  const appointmentId = sanitizeString(params.appointmentId, 120);
  const patientId = sanitizeString(params.patientId, 120);
  if (!isUuid(organizationId) || !isUuid(appointmentId) || !isUuid(patientId)) return;
  const existing = await supabase
    .from('appointment_billing_contexts')
    .select('id')
    .eq('organization_id', organizationId)
    .eq('appointment_id', appointmentId)
    .limit(1)
    .maybeSingle();
  if (existing.error) {
    if (hasMissingFinancialSchema(existing.error)) return;
    throw existing.error;
  }
  if (existing.data?.id) return;

  const rawPayerId = sanitizeString(params.appointment?.payerId || params.appointment?.payer_id, 120);
  let payer: any = null;
  if (isUuid(rawPayerId)) {
    const payerResult = await supabase
      .from('clinic_payers')
      .select('id, name')
      .eq('organization_id', organizationId)
      .eq('id', rawPayerId)
      .limit(1)
      .maybeSingle();
    if (payerResult.error && !hasMissingFinancialSchema(payerResult.error)) throw payerResult.error;
    payer = payerResult.data || null;
  }
  const serviceType = sanitizeString(
    params.appointment?.service_type ||
      params.appointment?.serviceType ||
      params.appointment?.approach ||
      params.appointment?.type,
    120
  );
  let payerName = sanitizeString(
    payer?.name ||
      params.appointment?.payerName ||
      params.appointment?.payer_name_snapshot ||
      params.appointment?.payerNameSnapshot,
    180
  );
  let suggestedBilling: any = null;
  if (!payer?.id && !payerName) {
    suggestedBilling = await resolveAppointmentBillingSuggestion({
      organizationId,
      patientId,
      serviceType
    });
    const suggestedPayerId = sanitizeString(suggestedBilling?.payerId || suggestedBilling?.payer_id, 120);
    if (isUuid(suggestedPayerId)) {
      const suggestedPayerResult = await supabase
        .from('clinic_payers')
        .select('id, name')
        .eq('organization_id', organizationId)
        .eq('id', suggestedPayerId)
        .limit(1)
        .maybeSingle();
      if (suggestedPayerResult.error && !hasMissingFinancialSchema(suggestedPayerResult.error)) throw suggestedPayerResult.error;
      payer = suggestedPayerResult.data || null;
    }
    payerName = sanitizeString(payer?.name || suggestedBilling?.payerName || suggestedBilling?.payer_name_snapshot, 180);
  }
  const payload = cleanObject({
    id: crypto.randomUUID(),
    organization_id: organizationId,
    appointment_id: appointmentId,
    patient_id: patientId,
    payer_id: payer?.id || null,
    payer_name_snapshot: payerName || null,
    service_type: serviceType || sanitizeString(suggestedBilling?.serviceType || suggestedBilling?.service_type, 120) || null,
    insurance_card_number: sanitizeString(params.appointment?.insuranceCardNumber || params.appointment?.insurance_card_number || params.appointment?.cardNumber || params.appointment?.card_number || suggestedBilling?.insuranceCardNumber || suggestedBilling?.insurance_card_number, 120) || null,
    insurance_plan_name: sanitizeString(params.appointment?.insurancePlanName || params.appointment?.insurance_plan_name || suggestedBilling?.insurancePlanName || suggestedBilling?.insurance_plan_name, 160) || null,
    authorization_code: sanitizeString(params.appointment?.authorizationCode || params.appointment?.authorization_code || suggestedBilling?.authorizationCode || suggestedBilling?.authorization_code, 120) || null,
    guide_number: sanitizeString(params.appointment?.guideNumber || params.appointment?.guide_number || suggestedBilling?.guideNumber || suggestedBilling?.guide_number, 120) || null,
    procedure_code: sanitizeString(params.appointment?.procedureCode || params.appointment?.procedure_code, 80) || null,
    notes: sanitizeTextField(params.appointment?.billingNotes || params.appointment?.billing_notes || suggestedBilling?.notes, 1200) || null,
    source: sanitizeString(suggestedBilling?.source || (suggestedBilling ? 'PATIENT_DEFAULT' : 'MANUAL'), 60) || null,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  });
  const hasContextValue = Boolean(
    payload.payer_id ||
      payload.payer_name_snapshot ||
      payload.authorization_code ||
      payload.guide_number ||
      payload.insurance_card_number ||
      payload.insurance_plan_name ||
      payload.procedure_code ||
      payload.notes
  );
  if (!hasContextValue) return;
  const upsertResult = await supabase
    .from('appointment_billing_contexts')
    .upsert([payload], { onConflict: 'organization_id,appointment_id' });
  if (upsertResult.error && extractMissingColumnName(upsertResult.error)) {
    const legacyPayload = { ...payload };
    delete legacyPayload.payer_type;
    delete legacyPayload.insurance_card_number;
    delete legacyPayload.insurance_plan_name;
    delete legacyPayload.source;
    delete legacyPayload.metadata;
    delete legacyPayload.created_by;
    delete legacyPayload.updated_by;
    const legacyResult = await supabase
      .from('appointment_billing_contexts')
      .upsert([cleanObject(legacyPayload)], { onConflict: 'organization_id,appointment_id' });
    if (legacyResult.error && !hasMissingFinancialSchema(legacyResult.error)) throw legacyResult.error;
    return;
  }
  if (upsertResult.error && !hasMissingFinancialSchema(upsertResult.error)) throw upsertResult.error;
}

async function syncAppointmentsTableFromClinicState(params: {
  clinicId: string | null;
  appointments: any[];
  actorId: string;
  specialtySettings?: Record<string, any>;
}) {
  const clinicId = sanitizeString(params.clinicId, 120);
  const actorId = sanitizeString(params.actorId, 120);
  if (!isUuid(clinicId) || !Array.isArray(params.appointments)) return { mirrored: 0, skipped: 0 };

  let mirrored = 0;
  let skipped = 0;
  const appointmentIds = Array.from(
    new Set(
      params.appointments
        .map((appointment: any) => sanitizeString(appointment?.id, 120))
        .filter((id: string) => isUuid(id))
    )
  );
  const existingById = new Map<string, any>();
  if (appointmentIds.length > 0) {
    const { data: existingRows, error: existingError } = await supabase
      .from('appointments')
      .select('id, status, patient_response, patient_responded_at, patient_confirmation_status, patient_confirmation_at, patient_confirmation_by, patient_confirmation_source, notification_24h_sent_at, notification_12h_sent_at, notification_sent, notification_sent_at, notification_12h_sent')
      .in('id', appointmentIds);
    if (!existingError) {
      for (const row of existingRows || []) {
        existingById.set(sanitizeString(row?.id, 120), row);
      }
    }
  }
  const hasOwn = (source: any, key: string) =>
    Object.prototype.hasOwnProperty.call(source || {}, key);
  const hasAnyOwn = (source: any, keys: string[]) =>
    keys.some((key) => hasOwn(source, key));
  const firstOwnValue = (source: any, keys: string[]) => {
    for (const key of keys) {
      if (hasOwn(source, key)) return source?.[key];
    }
    return undefined;
  };

  for (const appointment of params.appointments) {
    const appointmentId = sanitizeString(appointment?.id, 120);
    const scheduledAt = buildAppointmentScheduledAt(appointment);
    const rawPatientId = sanitizeString(appointment?.patientId || appointment?.patient_id, 120);
    const patientEmail = sanitizeEmail(appointment?.patientEmail || appointment?.patient_email);
    const resolvedPatientIds = await resolvePatientIdsForPush({
      supabase,
      patientId: rawPatientId,
      patientEmail,
      clinicId
    });
    const patientId = resolvedPatientIds[0] || '';

    if (!isUuid(appointmentId) || !scheduledAt || !isUuid(patientId)) {
      skipped += 1;
      continue;
    }

    const therapistIdCandidates = [
      appointment?.therapistId,
      appointment?.therapist_id,
      appointment?.professionalId,
      appointment?.professional_id,
      actorId
    ];
    const therapistId = therapistIdCandidates
      .map((value) => sanitizeString(value, 120))
      .find((value) => isUuid(value));
    if (!therapistId) {
      skipped += 1;
      continue;
    }

    const approach = sanitizeString(appointment?.type || appointment?.approach, 120);
    const configuredDuration = Number(params.specialtySettings?.[approach]);
    const duration = Number(
      appointment?.duration_minutes ||
      appointment?.durationMinutes ||
      appointment?.scheduled_duration_minutes ||
      appointment?.scheduledDurationMinutes ||
      configuredDuration ||
      50
    );
    const safeDuration = Number.isFinite(duration) && duration > 0 ? Math.round(duration) : 50;
    const scheduledEndAt = new Date(new Date(scheduledAt).getTime() + safeDuration * 60 * 1000).toISOString();
    const roomId = sanitizeString(
      appointment?.room_id || appointment?.roomId || appointment?.room,
      180
    );
    const roomName = sanitizeString(
      appointment?.room_name || appointment?.roomName || appointment?.roomDisplayName,
      180
    );
    const locationType = normalizeScheduleLocationType(
      appointment?.location_type || appointment?.locationType || appointment?.location || (roomId ? 'clinica' : '')
    );
    const professionalIds = Array.from(
      new Set(
        [
          therapistId,
          appointment?.professionalId,
          appointment?.professional_id,
          ...(Array.isArray(appointment?.professionalIds) ? appointment.professionalIds : []),
          ...(Array.isArray(appointment?.professional_ids) ? appointment.professional_ids : []),
          ...(Array.isArray(appointment?.teamProfessionalIds) ? appointment.teamProfessionalIds : []),
          ...(Array.isArray(appointment?.team_professional_ids) ? appointment.team_professional_ids : [])
        ]
          .map((value) => sanitizeString(value, 120))
          .filter((value) => isUuid(value))
      )
    );
    const statusForTable = normalizeAppointmentStatusForTable(appointment?.status);
    const patientResponse =
      sanitizeString(appointment?.patient_response || appointment?.patientResponse, 40) ||
      (
        ['confirmed', 'reschedule', 'cancelled', 'canceled'].includes(normalizeAppointmentStatusForUi(appointment?.status))
          ? normalizeAppointmentStatusForUi(appointment?.status)
          : null
      );
    const existing = existingById.get(appointmentId) || {};
    const hasIncomingPatientResponse = hasAnyOwn(appointment, [
      'patient_response',
      'patientResponse',
      'patientConfirmationStatus',
      'patient_confirmation_status',
      'patientRespondedAt',
      'patient_responded_at',
      'patientConfirmationAt',
      'patient_confirmation_at'
    ]) || Boolean(patientResponse);
    const existingResponseStatus =
      normalizeAppointmentResponseAction(existing.patient_response || existing.patient_confirmation_status) ||
      normalizeAppointmentStatusForUi(existing.status);
    const incomingUiStatus = normalizeAppointmentStatusForUi(appointment?.status);
    const shouldPreserveExistingResponseStatus =
      !hasIncomingPatientResponse &&
      ['confirmed', 'reschedule', 'canceled'].includes(existingResponseStatus) &&
      (incomingUiStatus === 'pending' || incomingUiStatus === 'scheduled');
    const effectiveStatusForTable = shouldPreserveExistingResponseStatus
      ? normalizeAppointmentStatusForTable(existingResponseStatus)
      : statusForTable;
    const resolvedPatientResponse = hasIncomingPatientResponse
      ? (patientResponse === 'canceled' ? 'cancelled' : patientResponse)
      : (existing.patient_response || null);
    const resolvedPatientRespondedAt = hasIncomingPatientResponse
      ? (appointment?.patient_responded_at || appointment?.patientRespondedAt || appointment?.patientConfirmationAt || null)
      : (existing.patient_responded_at || null);
    const resolvedPatientConfirmationStatus = hasIncomingPatientResponse
      ? (appointment?.patientConfirmationStatus || appointment?.patient_confirmation_status || patientResponse || null)
      : (existing.patient_confirmation_status || null);
    const resolvedPatientConfirmationAt = hasIncomingPatientResponse
      ? (appointment?.patientConfirmationAt || appointment?.patient_confirmation_at || appointment?.patient_responded_at || null)
      : (existing.patient_confirmation_at || null);
    const resolvedPatientConfirmationBy = hasIncomingPatientResponse
      ? (appointment?.patientConfirmationBy || appointment?.patient_confirmation_by || null)
      : (existing.patient_confirmation_by || null);
    const resolvedPatientConfirmationSource = hasIncomingPatientResponse
      ? (appointment?.patientConfirmationSource || appointment?.patient_confirmation_source || null)
      : (existing.patient_confirmation_source || null);
    const hasIncoming24hMarker = hasAnyOwn(appointment, [
      'notification_24h_sent_at',
      'notification24hSentAt',
      'notification_sent_at',
      'notification_sent'
    ]);
    const incoming24hSentAt = firstOwnValue(appointment, [
      'notification_24h_sent_at',
      'notification24hSentAt',
      'notification_sent_at'
    ]);
    const resolved24hSentAt = hasIncoming24hMarker
      ? (incoming24hSentAt || null)
      : (existing.notification_24h_sent_at || existing.notification_sent_at || null);
    const resolvedNotificationSent = hasIncoming24hMarker
      ? (hasOwn(appointment, 'notification_sent') ? Boolean(appointment.notification_sent) : Boolean(resolved24hSentAt))
      : Boolean(existing.notification_sent || existing.notification_24h_sent_at || existing.notification_sent_at);
    const hasIncoming12hMarker = hasAnyOwn(appointment, [
      'notification_12h_sent_at',
      'notification12hSentAt',
      'notification_12h_sent'
    ]);
    const incoming12hSentAt = firstOwnValue(appointment, [
      'notification_12h_sent_at',
      'notification12hSentAt'
    ]);
    const resolved12hSentAt = hasIncoming12hMarker
      ? (incoming12hSentAt || null)
      : (existing.notification_12h_sent_at || null);
    const resolvedNotification12hSent = hasIncoming12hMarker
      ? (hasOwn(appointment, 'notification_12h_sent') ? Boolean(appointment.notification_12h_sent) : Boolean(resolved12hSentAt))
      : Boolean(existing.notification_12h_sent || existing.notification_12h_sent_at);

    const row = {
      id: appointmentId,
      organization_id: isUuid(sanitizeString(appointment?.organization_id || appointment?.organizationId, 120))
        ? sanitizeString(appointment?.organization_id || appointment?.organizationId, 120)
        : clinicId,
      clinic_id: clinicId,
      patient_id: patientId,
      therapist_id: therapistId,
      scheduled_at: scheduledAt,
      scheduled_start_at: appointment?.scheduled_start_at || appointment?.scheduledStartAt || scheduledAt,
      scheduled_end_at: appointment?.scheduled_end_at || appointment?.scheduledEndAt || scheduledEndAt,
      scheduled_duration_minutes: safeDuration,
      actual_start_at: appointment?.actual_start_at || appointment?.actualStartAt || appointment?.actual_start || appointment?.actualStart || null,
      actual_end_at: appointment?.actual_end_at || appointment?.actualEndAt || appointment?.actual_end || appointment?.actualEnd || null,
      actual_duration_minutes:
        Number.isFinite(Number(appointment?.actual_duration_minutes ?? appointment?.actualDurationMinutes))
          ? Math.max(0, Math.round(Number(appointment?.actual_duration_minutes ?? appointment?.actualDurationMinutes)))
          : null,
      duration_minutes: safeDuration,
      status: effectiveStatusForTable,
      notes: sanitizeString(appointment?.notes || appointment?.note, 2000) || null,
      patient_response: resolvedPatientResponse,
      patient_responded_at: resolvedPatientRespondedAt,
      notification_24h_sent_at: resolved24hSentAt,
      notification_12h_sent_at: resolved12hSentAt,
      notification_sent: resolvedNotificationSent,
      notification_sent_at: resolved24hSentAt,
      notification_12h_sent: resolvedNotification12hSent,
      patient_confirmation_status: resolvedPatientConfirmationStatus,
      patient_confirmation_at: resolvedPatientConfirmationAt,
      patient_confirmation_by: resolvedPatientConfirmationBy,
      patient_confirmation_source: resolvedPatientConfirmationSource,
      patient_email: patientEmail || null,
      patient_name: sanitizeString(appointment?.patientName || appointment?.name || appointment?.patient_name, 180) || null,
      therapist_name: sanitizeString(appointment?.therapistName || appointment?.professional || appointment?.therapist_name, 180) || null,
      approach,
      service_type: sanitizeString(appointment?.service_type || appointment?.serviceType || approach, 120) || null,
      room_id: roomId || null,
      room_name: roomName || (roomId && !isUuid(roomId) ? roomId : null),
      location_type: locationType,
      location_notes: sanitizeString(appointment?.location_notes || appointment?.locationNotes || appointment?.addressNote, 1000) || null,
      call_link: sanitizeString(appointment?.call_link || appointment?.callLink, 500) || null,
      recurrence_group_id: sanitizeString(appointment?.recurrenceGroupId || appointment?.recurrence_group_id, 120) || null,
      recurrence_index: Number.isFinite(Number(appointment?.recurrenceIndex ?? appointment?.recurrence_index))
        ? Math.max(0, Math.round(Number(appointment?.recurrenceIndex ?? appointment?.recurrence_index)))
        : null,
      recurrence_total: Number.isFinite(Number(appointment?.recurrenceTotal ?? appointment?.recurrence_total))
        ? Math.max(1, Math.round(Number(appointment?.recurrenceTotal ?? appointment?.recurrence_total)))
        : null,
      recurrence_frequency: sanitizeString(appointment?.recurrenceFrequency || appointment?.recurrence_frequency, 60) || null,
      source_payload: {
        ...appointment,
        professionalIds,
        professional_ids: professionalIds,
        room_id: roomId || appointment?.room_id || appointment?.roomId || null,
        roomName: roomName || appointment?.roomName || null,
        locationType,
        location_type: locationType,
        durationMinutes: safeDuration,
        duration_minutes: safeDuration,
        scheduled_end_at: appointment?.scheduled_end_at || appointment?.scheduledEndAt || scheduledEndAt
      },
      is_active: !['cancelled', 'canceled', 'deleted'].includes(effectiveStatusForTable),
      updated_at: new Date().toISOString()
    };

    const ok = await upsertAppointmentMirrorRow(row);
    if (ok) {
      mirrored += 1;
      await syncAppointmentProfessionalsMirrorRows({
        appointmentId,
        organizationId: row.organization_id,
        clinicId,
        professionalIds,
        professionalName: row.therapist_name
      });
      await upsertInitialBillingContextFromAppointment({
        organizationId: row.organization_id,
        appointmentId,
        patientId,
        appointment
      });
      await flagPendingMaintenanceProbesForAppointment({
        appointmentId,
        organizationId: row.organization_id,
        clinicId,
        patientId,
        scheduledAt,
        actorId
      });
    } else skipped += 1;
  }

  return { mirrored, skipped };
}

async function ensureAppointmentMirrorForBillingContext(params: {
  organizationId: string;
  appointment: any;
  user: any;
}) {
  const organizationId = sanitizeString(params.organizationId, 120);
  const appointmentId = sanitizeString(params.appointment?.id || params.appointment?.appointment_id, 120);
  if (!isUuid(organizationId) || !isUuid(appointmentId)) return false;

  const existingResult = await supabase
    .from('appointments')
    .select('id')
    .eq('id', appointmentId)
    .limit(1)
    .maybeSingle();
  if (!existingResult.error && existingResult.data?.id) return true;
  if (existingResult.error && !hasMissingFinancialSchema(existingResult.error)) {
    const missingColumn = extractMissingColumnName(existingResult.error);
    if (!missingColumn) throw existingResult.error;
  }

  const sourceAppointment = parseStoredJsonObject(params.appointment?.source_payload || params.appointment?.sourcePayload);
  const appointmentForMirror = cleanObject({
    ...sourceAppointment,
    ...params.appointment,
    id: appointmentId,
    patientId: params.appointment?.patient_id || params.appointment?.patientId || sourceAppointment?.patientId || sourceAppointment?.patient_id,
    patient_id: params.appointment?.patient_id || params.appointment?.patientId || sourceAppointment?.patient_id || sourceAppointment?.patientId,
    therapistId: params.appointment?.therapist_id || params.appointment?.therapistId || params.appointment?.professional_id || params.appointment?.professionalId || sourceAppointment?.therapistId || sourceAppointment?.therapist_id || sourceAppointment?.professionalId || sourceAppointment?.professional_id || params.user?.id,
    therapist_id: params.appointment?.therapist_id || params.appointment?.therapistId || params.appointment?.professional_id || params.appointment?.professionalId || sourceAppointment?.therapist_id || sourceAppointment?.therapistId || sourceAppointment?.professional_id || sourceAppointment?.professionalId || params.user?.id,
    organization_id: organizationId,
    organizationId,
    clinic_id: params.appointment?.clinic_id || params.appointment?.clinicId || organizationId,
    clinicId: params.appointment?.clinic_id || params.appointment?.clinicId || organizationId,
    serviceType: params.appointment?.service_type || params.appointment?.serviceType || params.appointment?.approach || sourceAppointment?.serviceType || sourceAppointment?.service_type || sourceAppointment?.approach,
    service_type: params.appointment?.service_type || params.appointment?.serviceType || params.appointment?.approach || sourceAppointment?.service_type || sourceAppointment?.serviceType || sourceAppointment?.approach
  });

  const summary = await syncAppointmentsTableFromClinicState({
    clinicId: organizationId,
    appointments: [appointmentForMirror],
    actorId: sanitizeString(params.user?.id, 120),
    specialtySettings: {}
  });
  if (summary.mirrored > 0) return true;

  const retryResult = await supabase
    .from('appointments')
    .select('id')
    .eq('id', appointmentId)
    .limit(1)
    .maybeSingle();
  if (retryResult.error && !hasMissingFinancialSchema(retryResult.error)) throw retryResult.error;
  return Boolean(retryResult.data?.id);
}

async function syncClinicRoomsTableFromClinicState(params: {
  clinicId: string | null;
  rooms: any[];
  organizationId?: string | null;
}) {
  const clinicId = sanitizeString(params.clinicId, 120);
  const organizationId = sanitizeString(params.organizationId || clinicId, 120);
  if (!isUuid(clinicId) || !Array.isArray(params.rooms)) return { mirrored: 0, skipped: 0 };
  let mirrored = 0;
  let skipped = 0;
  for (const room of params.rooms.slice(0, 400)) {
    const roomId = sanitizeString(room?.id, 180);
    const name = sanitizeString(room?.name, 180);
    if (!isUuid(roomId) || !name) {
      skipped += 1;
      continue;
    }
    const payload = cleanObject({
      id: roomId,
      organization_id: isUuid(organizationId) ? organizationId : clinicId,
      clinic_id: clinicId,
      name,
      specialties: normalizeClinicRoomSpecialties(room?.specialties || room?.specialty),
      description: sanitizeString(room?.description, 1000) || null,
      capacity: Number.isFinite(Number(room?.capacity)) ? Math.max(0, Math.round(Number(room.capacity))) : null,
      is_active: room?.is_active !== false && room?.isActive !== false,
      updated_at: new Date().toISOString()
    });
    const { error } = await supabase
      .from('clinic_rooms')
      .upsert([payload], { onConflict: 'id' });
    if (!error) mirrored += 1;
    else {
      if (hasMissingFinancialSchema(error)) return { mirrored, skipped: skipped + 1 };
      skipped += 1;
      console.warn('[Rooms] Falha ao espelhar sala da clínica.', { roomId, message: error.message });
    }
  }
  return { mirrored, skipped };
}

function normalizeClinicRoomSpecialties(value: any) {
  if (Array.isArray(value)) {
    return value.map((item) => sanitizeString(item, 120)).filter(Boolean).slice(0, 12).join(', ') || null;
  }
  return sanitizeString(value, 1000) || null;
}

async function fetchUserWorkspaces(userId: string) {
  const { data, error } = await supabase
    .from('clinic_memberships')
    .select(`
      clinic_id,
      role,
      status,
      clinics:clinic_id (
        id,
        name,
        logo_url
      )
    `)
    .eq('user_id', userId)
    .eq('status', 'active');

  if (error) {
    return [];
  }

  return (data || []).map((membership: any) => {
    const clinic = membership.clinics || {};
    return {
      clinicId: sanitizeString(clinic.id || membership.clinic_id, 120),
      clinicName: sanitizeString(clinic.name, 160) || 'Clinica',
      clinicLogoUrl: sanitizeSessionUrl(clinic.logo_url),
      role: ensureRole(membership.role) ? membership.role : 'therapist'
    };
  }).filter((w: any) => w.clinicId);
}

async function findAuthUserByEmail(email: string): Promise<any | null> {
  if (!supabase) return null;
  const target = sanitizeEmail(email);
  if (!target) return null;

  let page = 1;
  const perPage = 200;
  for (;;) {
    const listResult = await withTimeoutOrFallback(
      supabase.auth.admin.listUsers({ page, perPage }),
      7000,
      { data: { users: [] }, error: null } as any,
      'supabase.auth.admin.listUsers'
    );
    const { data, error } = listResult;
    if (error) return null;
    const users = data?.users || [];
    const found = users.find((u: any) => sanitizeEmail(u.email) === target);
    if (found) return found;
    if (users.length < perPage) break;
    page += 1;
    if (page > 20) break;
  }
  return null;
}

async function findRecoverableAuthUserByEmail(email: string): Promise<any | null> {
  const target = sanitizeEmail(email);
  if (!target) return null;

  const authUser = await findAuthUserByEmail(target);
  if (authUser?.id) return authUser;

  try {
    const profileResult = await fetchProfileByEmailWithSchemaFallback({
      supabase,
      email: target,
      logger: console
    });
    const profile = profileResult.data as any;
    if (profile?.id) {
      console.warn('[Auth] Recuperação usando fallback users.id por e-mail após listUsers não localizar usuário:', {
        email: maskEmail(target),
        userId: sanitizeString(profile.id, 120)
      });
      return {
        id: sanitizeString(profile.id, 120),
        email: sanitizeEmail(profile.email) || target,
        user_metadata: {
          full_name: sanitizeString(profile.name, 180) || undefined,
          type: sanitizeString(profile.type, 80) || undefined
        }
      };
    }
  } catch (error: any) {
    console.warn('[Auth] Fallback de recuperação por users.email falhou:', error?.message || String(error));
  }

  return null;
}

async function insertUserProfileWithSchemaFallback(basePayload: Record<string, any>) {
  let payload = cleanObject({ ...basePayload });
  let lastError: any = null;

  for (let attempt = 0; attempt < 12 && Object.keys(payload).length > 0; attempt += 1) {
    const { error } = await supabase
      .from('users')
      .insert([payload]);

    if (!error) return { error: null, payload };

    lastError = error;
    const missingColumn = extractMissingColumnName(error);
    if (!missingColumn || !(missingColumn in payload)) break;

    console.warn('[Auth] Removendo coluna opcional ausente ao criar perfil no login:', {
      table: 'users',
      removedColumn: missingColumn,
      code: sanitizeString(error?.code, 40) || null,
      message: extractSupabaseErrorMessage(error)
    });
    const nextPayload = { ...payload };
    delete nextPayload[missingColumn];
    payload = nextPayload;
  }

  return { error: lastError, payload };
}

function compactClinicSettingsForSession(settings: any) {
  if (!settings || typeof settings !== 'object') return null;
  return cleanObject({
    clinicName: sanitizeString(settings.clinicName, 160) || null,
    clinicCnpj: sanitizeString(settings.clinicCnpj, 30) || null,
    clinicPhone: sanitizeString(settings.clinicPhone, 30) || null,
    specialty: sanitizeString(settings.specialty, 160) || null,
    council: sanitizeString(settings.council, 80) || null,
    councilNumber: sanitizeString(settings.councilNumber, 80) || null,
    clinicAddress: sanitizeString(settings.clinicAddress, 240) || null,
    clinicLogoUrl: sanitizeSessionUrl(settings.clinicLogoUrl),
    signatureDataUrl: sanitizeSessionUrl(settings.signatureDataUrl),
    therapistSpecialties: sanitizeString(settings.therapistSpecialties, 240) || null,
    therapistMiniCurriculum: sanitizeString(settings.therapistMiniCurriculum, 3000) || null,
    defaultSessionDuration: asSafeNumber(settings.defaultSessionDuration, 20, 240) || 50,
    workStart: sanitizeString(settings.workStart, 5) || '08:00',
    workEnd: sanitizeString(settings.workEnd, 5) || '18:00'
  });
}

function compactWorkspacesForSession(workspaces: any[]) {
  if (!Array.isArray(workspaces)) return [];
  return workspaces.slice(0, 30).map((w: any) => ({
    clinicId: sanitizeString(w?.clinicId, 120),
    clinicName: sanitizeString(w?.clinicName, 160) || 'Clinica',
    clinicLogoUrl: sanitizeSessionUrl(w?.clinicLogoUrl),
    role: ensureRole(w?.role) ? w.role : 'therapist'
  })).filter((w: any) => w.clinicId);
}

function resolveActiveWorkspaceId(
  workspaces: any[],
  preferredWorkspaceId?: string | null,
  fallbackClinicId?: string | null
): string | null {
  const compacted = compactWorkspacesForSession(workspaces);
  const preferred = sanitizeString(preferredWorkspaceId, 120);
  const fallback = sanitizeString(fallbackClinicId, 120);

  if (preferred && compacted.some((w: any) => w.clinicId === preferred)) {
    return preferred;
  }
  if (fallback && compacted.some((w: any) => w.clinicId === fallback)) {
    return fallback;
  }
  if (compacted.length === 1) return compacted[0].clinicId;
  return null;
}

function buildSessionUserPayload(input: any) {
  const workspaces = compactWorkspacesForSession(input?.workspaces || []);
  const activeWorkspaceId = resolveActiveWorkspaceId(
    workspaces,
    input?.activeWorkspaceId,
    input?.clinicId || input?.clinic_id
  );
  const selectedWorkspace = activeWorkspaceId
    ? workspaces.find((w: any) => w.clinicId === activeWorkspaceId) || null
    : null;
  const resolvedRole = selectedWorkspace?.role || input?.role;
  const mustSelectWorkspace = workspaces.length > 1 && !activeWorkspaceId;

  return {
    id: sanitizeString(input?.id, 120),
    email: sanitizeEmail(input?.email) || sanitizeString(input?.email, 320),
    role: ensureRole(resolvedRole) ? resolvedRole : 'therapist',
    name: sanitizeString(input?.name, 180),
    profilePicture: sanitizeSessionUrl(input?.profilePicture),
    profilePicturePath: sanitizeString(input?.profilePicturePath || input?.profile_picture_path, 500) || null,
    address: sanitizeString(input?.address, 320) || null,
    type: sanitizeString(input?.type, 80) || null,
    age: typeof input?.age === 'number' ? input.age : null,
    subscriptionStatus: sanitizeString(input?.subscriptionStatus, 40) || null,
    planName: sanitizeString(input?.planName, 80) || null,
    planPrice: asSafeNumber(input?.planPrice, 0, 100000) || null,
    treatmentStatus: sanitizeString(input?.treatmentStatus, 40) || null,
    clinicId: selectedWorkspace?.clinicId || sanitizeString(input?.clinicId, 120) || null,
    activeWorkspaceId,
    mustSelectWorkspace,
    sessionToken: sanitizeString(input?.sessionToken, 120) || null,
    emailVerified: Boolean(input?.emailVerified),
    phoneVerified: Boolean(input?.phoneVerified),
    portalVerified: Boolean(input?.portalVerified),
    accountState: sanitizeString(input?.accountState, 60) || null,
    passwordStatus: sanitizeString(input?.passwordStatus, 60) || null,
    firstLoginCompleted:
      typeof input?.firstLoginCompleted === 'boolean' ? input.firstLoginCompleted : null,
    activationRequired: Boolean(input?.activationRequired),
    crp: resolveStoredCrp(input),
    signatureDataUrl:
      sanitizeSessionUrl(input?.signatureDataUrl) ||
      sanitizeSessionUrl(input?.clinicSettings?.signatureDataUrl) ||
      null,
    specialties:
      sanitizeString(input?.specialties || input?.clinicSettings?.therapistSpecialties || input?.clinicSettings?.specialty, 240) ||
      null,
    miniCurriculum:
      sanitizeString(input?.miniCurriculum || input?.clinicSettings?.therapistMiniCurriculum, 3000) ||
      null,
    clinicSettings: compactClinicSettingsForSession(input?.clinicSettings),
    workspaces
  };
}

async function derivePatientTreatmentStatus(user: any): Promise<'active' | 'inactive' | 'waiting_treatment'> {
  const role = sanitizeString(user?.role, 40).toLowerCase();
  if (role !== 'patient') return 'active';

  const safeEmail = sanitizeEmail(user?.email);
  const fallbackHasClinic = Boolean(sanitizeString(user?.clinicId || user?.activeWorkspaceId, 120));
  const hasWorkspace = Array.isArray(user?.workspaces) && user.workspaces.length > 0;
  if (hasWorkspace) return 'active';

  let patientRows: any[] = [];
  if (safeEmail) {
    const { data } = await supabase
      .from('patients')
      .select('id, clinic_id, status')
      .ilike('email', safeEmail)
      .eq('is_active', true)
      .is('deleted_at', null)
      .limit(1000);
    patientRows = Array.isArray(data) ? data : [];
  }

  const hasLinkedClinic = patientRows.some((row: any) => Boolean(sanitizeString(row?.clinic_id, 120))) || fallbackHasClinic;
  const hasActivePatientStatus = patientRows.some((row: any) => sanitizeString(row?.status, 40).toLowerCase() === 'active');
  const patientIds = patientRows
    .map((row: any) => sanitizeString(row?.id, 120))
    .filter((id: string) => isUuid(id));

  let hasAssignedTasks = false;
  if (patientIds.length > 0) {
    const { count } = await supabase
      .from('assigned_tasks')
      .select('id', { count: 'exact', head: true })
      .in('patient_id', patientIds);
    hasAssignedTasks = Number(count || 0) > 0;
  }
  if (!hasAssignedTasks && safeEmail) {
    const { count } = await supabase
      .from('assigned_tasks')
      .select('id', { count: 'exact', head: true })
      .eq('patient_email', safeEmail);
    hasAssignedTasks = Number(count || 0) > 0;
  }

  // Regra de vínculo: paciente já vinculado à clínica não deve cair como "sem tratamento ativo"
  // imediatamente após ativação/login, mesmo sem tarefas atribuídas ainda.
  if (hasActivePatientStatus || hasLinkedClinic || hasAssignedTasks) return 'active';
  return 'waiting_treatment';
}

async function resolveProfessionalPlanFromCheckoutSession(
  stripe: Stripe,
  session: Stripe.Checkout.Session,
): Promise<'Essencial' | 'Crescimento' | 'Avançado' | null> {
  const metadataPlan = normalizeProfessionalPlan((session.metadata as any)?.planName);
  if (metadataPlan) return metadataPlan;

  try {
    const lineItems = await stripe.checkout.sessions.listLineItems(session.id, { limit: 10 });
    for (const lineItem of lineItems.data || []) {
      const planByPriceId = resolveProfessionalPlanByPriceId(
        typeof lineItem.price === 'string' ? lineItem.price : lineItem.price?.id,
      );
      if (planByPriceId) return planByPriceId;
    }
  } catch (error: any) {
    console.warn('[Stripe] Falha ao resolver plano pelos line items da sessao:', {
      sessionId: sanitizeString(session.id, 200),
      message: error?.message || String(error)
    });
  }

  return null;
}

async function canAccessPatientInCurrentClinic(patientId: string, user: any): Promise<boolean> {
  if (!isUuid(patientId)) return false;
  if (hasGlobalClinicAccess(user)) return true;
  const clinicId = currentClinicId(user);
  const role = sanitizeString(user?.role, 40).toLowerCase();
  const userId = sanitizeString(user?.id, 120);
  let query = supabase
    .from('patients')
    .select('id, therapist_id, clinic_id')
    .eq('id', patientId)
    .eq('is_active', true)
    .is('deleted_at', null);
  if (clinicId) {
    query = query.eq('clinic_id', clinicId);
  }
  const { data, error } = await query.maybeSingle();
  if (error) return false;
  if (data?.id) {
    if (role === 'coordinator') return true;
    if (role === 'therapist' && sanitizeString(data?.therapist_id, 120) === userId) return true;
    return false;
  }

  // Fallback robusto: se contexto de clínica não estiver pronto na sessão,
  // terapeuta responsável ainda pode acessar seu próprio paciente.
  if (role === 'therapist' && isUuid(userId)) {
    const { data: byTherapist, error: byTherapistError } = await supabase
      .from('patients')
      .select('id')
      .eq('id', patientId)
      .eq('therapist_id', userId)
      .eq('is_active', true)
      .is('deleted_at', null)
      .maybeSingle();
    if (!byTherapistError && byTherapist?.id) return true;
  }

  return false;
}

async function canPortalSessionAccessPatient(patientId: string, user: any): Promise<boolean> {
  if (!isUuid(patientId)) return false;
  const role = sanitizeString(user?.role, 40).toLowerCase();
  if (!['patient', 'responsible', 'responsavel', 'guardian'].includes(role)) {
    return canAccessPatientInCurrentClinic(patientId, user);
  }

  const userId = sanitizeString(user?.id, 120);
  const userEmail = sanitizeEmail(user?.email);
  if (isUuid(userId) && userId === patientId) return true;

  let query = supabase
    .from('patients')
    .select('id, email, responsible_user_id')
    .eq('id', patientId)
    .eq('is_active', true)
    .is('deleted_at', null)
    .limit(1);
  const { data, error } = await query.maybeSingle();
  if (error || !data?.id) return false;

  const responsibleUserId = sanitizeString(data?.responsible_user_id, 120);
  const patientEmail = sanitizeEmail(data?.email);
  return Boolean(
    (isUuid(userId) && responsibleUserId === userId) ||
    (userEmail && patientEmail && userEmail === patientEmail)
  );
}

function normalizeAnamnesisAnswers(input: any, depth = 0): any {
  if (depth > 4) return null;
  if (input === null || input === undefined) return null;
  if (typeof input === 'string') return sanitizeString(input, 5000);
  if (typeof input === 'number') return Number.isFinite(input) ? input : null;
  if (typeof input === 'boolean') return input;
  if (Array.isArray(input)) {
    return input.slice(0, 200).map((item) => normalizeAnamnesisAnswers(item, depth + 1));
  }
  if (typeof input === 'object') {
    const entries = Object.entries(input).slice(0, 1000);
    return Object.fromEntries(entries.map(([key, value]) => [
      sanitizeString(key, 120),
      normalizeAnamnesisAnswers(value, depth + 1)
    ]).filter(([key]) => Boolean(key)));
  }
  return sanitizeString(String(input), 500);
}

function hasAnamnesisAnswers(input: any): boolean {
  if (!input || typeof input !== 'object') return false;
  return Object.values(input).some((value) => {
    if (Array.isArray(value)) return value.length > 0;
    if (value && typeof value === 'object') return hasAnamnesisAnswers(value);
    return String(value ?? '').trim().length > 0;
  });
}

function resolvePatientAnamnesisProfile(patient: any): 'adult' | 'child' {
  const source = sanitizeString(
    patient?.patient_profile_type ||
      patient?.panel_type ||
      patient?.profile_type ||
      patient?.type ||
      patient?.anamnesisData?.formType,
    80
  ).toLowerCase();
  if (['kids_tea', 'kids', 'child', 'infantil', 'crianca', 'criança', 'aba'].includes(source)) return 'child';
  const age = Number(patient?.age);
  if (Number.isFinite(age) && age >= 0 && age <= 12) return 'child';
  return 'adult';
}

function calculateAgeMonthsFromDateOnly(value: unknown): number | null {
  const raw = sanitizeString(value, 40);
  if (!raw) return null;
  const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const birth = match
    ? new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]))
    : new Date(raw);
  if (Number.isNaN(birth.getTime())) return null;
  const today = new Date();
  let months = (today.getFullYear() - birth.getFullYear()) * 12 + (today.getMonth() - birth.getMonth());
  if (today.getDate() < birth.getDate()) months -= 1;
  return months >= 0 ? months : null;
}

function anamnesisTemplateMatchesPatient(row: any, patient: any) {
  if (!row?.id || row?.is_active === false) return false;
  const ageMonths = calculateAgeMonthsFromDateOnly(patient?.birth_date || patient?.birthDate || patient?.dataNascimento);
  const minMonths = row?.age_min_months === null || row?.age_min_months === undefined ? null : Number(row.age_min_months);
  const maxMonths = row?.age_max_months === null || row?.age_max_months === undefined ? null : Number(row.age_max_months);
  const hasAgeRule = Number.isFinite(minMonths) || Number.isFinite(maxMonths);
  const ageMatches =
    ageMonths === null || !hasAgeRule
      ? true
      : (!Number.isFinite(minMonths) || ageMonths >= Number(minMonths)) &&
        (!Number.isFinite(maxMonths) || ageMonths <= Number(maxMonths));
  if (!ageMatches) return false;

  const rowProfile = sanitizeString(row?.patient_profile_type, 80).toUpperCase();
  if (!rowProfile) return true;
  const patientProfile = sanitizeString(
    patient?.patient_profile_type || patient?.panel_type || patient?.profile_type || patient?.type,
    80
  ).toUpperCase();
  if (!patientProfile) return true;
  if (rowProfile === 'TEEN' && patientProfile === 'KIDS') return true;
  if (rowProfile === 'KIDS_TEA' && patientProfile === 'KIDS') return true;
  if (rowProfile === 'ADULT' && patientProfile === 'ABA') return true;
  return rowProfile === patientProfile || patientProfile.includes(rowProfile) || rowProfile.includes(patientProfile);
}

function normalizeAgeBasedAnamnesisTemplate(row: any, patient: any, compatibleRows: any[] = []) {
  const fallback = getDefaultAnamnesisTemplate();
  const profileType = resolvePatientAnamnesisProfile(patient);
  const rawQuestions = row?.questions && typeof row.questions === 'object' ? row.questions : {};
  const template = sanitizeAnamnesisTemplate(
    rawQuestions?.profiles || rawQuestions?.version ? rawQuestions : fallback
  );
  return {
    ...template,
    selectedTemplateId: sanitizeString(row?.id, 120) || null,
    templateName: sanitizeString(row?.name, 180) || (profileType === 'child' ? 'Ficha infantil' : 'Ficha adulta'),
    templateDescription: sanitizeString(row?.description, 500) || null,
    ageMinMonths: Number.isFinite(Number(row?.age_min_months)) ? Number(row.age_min_months) : null,
    ageMaxMonths: Number.isFinite(Number(row?.age_max_months)) ? Number(row.age_max_months) : null,
    patientProfileType: sanitizeString(row?.patient_profile_type, 80) || null,
    compatibleTemplates: compatibleRows.slice(0, 12).map((item: any) => ({
      id: sanitizeString(item?.id, 120),
      name: sanitizeString(item?.name, 180),
      description: sanitizeString(item?.description, 240) || null,
      ageMinMonths: Number.isFinite(Number(item?.age_min_months)) ? Number(item.age_min_months) : null,
      ageMaxMonths: Number.isFinite(Number(item?.age_max_months)) ? Number(item.age_max_months) : null,
      patientProfileType: sanitizeString(item?.patient_profile_type, 80) || null
    })).filter((item: any) => item.id && item.name)
  };
}

function buildPublicAnamnesisTemplate(template: any) {
  const sanitized = sanitizeAnamnesisTemplate(template || getDefaultAnamnesisTemplate());
  return {
    ...sanitized,
    templateName: sanitizeString(template?.templateName, 180) || null,
    templateDescription: sanitizeString(template?.templateDescription, 500) || null,
    ageMinMonths: Number.isFinite(Number(template?.ageMinMonths)) ? Number(template.ageMinMonths) : null,
    ageMaxMonths: Number.isFinite(Number(template?.ageMaxMonths)) ? Number(template.ageMaxMonths) : null,
    patientProfileType: sanitizeString(template?.patientProfileType, 80) || null,
    compatibleTemplates: Array.isArray(template?.compatibleTemplates)
      ? template.compatibleTemplates.map((item: any) => ({
          name: sanitizeString(item?.name, 180),
          description: sanitizeString(item?.description, 240) || null,
          ageMinMonths: Number.isFinite(Number(item?.ageMinMonths)) ? Number(item.ageMinMonths) : null,
          ageMaxMonths: Number.isFinite(Number(item?.ageMaxMonths)) ? Number(item.ageMaxMonths) : null,
          patientProfileType: sanitizeString(item?.patientProfileType, 80) || null
        })).filter((item: any) => item.name)
      : []
  };
}

async function fetchAnamnesisTemplateForClinic(clinicId: string) {
  const templateResult = await fetchClinicAnamnesisTemplateWithSchemaFallback({
    supabase,
    clinicId,
    logger: console
  });
  if (templateResult.error) {
    if (isMissingRelationError(templateResult.error)) return getDefaultAnamnesisTemplate();
    throw templateResult.error;
  }
  return sanitizeAnamnesisTemplate(templateResult.data?.template_json || getDefaultAnamnesisTemplate());
}

async function fetchAnamnesisTemplateForPatient(patient: any, clinicId: string, requestedTemplateId?: string | null) {
  const fallback = await fetchAnamnesisTemplateForClinic(clinicId);
  const safeClinicId = sanitizeString(clinicId, 120);
  if (!isUuid(safeClinicId)) return fallback;
  const requestedId = sanitizeString(requestedTemplateId, 120);

  try {
    let query = supabase
      .from('anamnesis_templates')
      .select(ANAMNESIS_TEMPLATE_SELECT)
      .eq('is_active', true)
      .or(`organization_id.is.null,organization_id.eq.${safeClinicId}`)
      .order('organization_id', { ascending: false })
      .order('is_default', { ascending: false })
      .order('created_at', { ascending: true })
      .limit(120);
    if (isUuid(requestedId)) query = query.eq('id', requestedId);
    const { data, error } = await query;
    if (error) {
      if (isMissingRelationError(error) || extractMissingColumnName(error)) return fallback;
      throw error;
    }
    const rows = Array.isArray(data) ? data : [];
    const compatible = rows.filter((row: any) => anamnesisTemplateMatchesPatient(row, patient));
    const patientProfileKey = sanitizeString(
      patient?.patient_profile_type || patient?.panel_type || patient?.profile_type || patient?.type,
      80
    ).toUpperCase();
    const exactCompatible = compatible.filter((row: any) => (
      patientProfileKey &&
      sanitizeString(row?.patient_profile_type, 80).toUpperCase() === patientProfileKey
    ));
    const selected =
      exactCompatible.find((row: any) => sanitizeString(row?.organization_id, 120) === safeClinicId) ||
      exactCompatible[0] ||
      compatible.find((row: any) => sanitizeString(row?.organization_id, 120) === safeClinicId) ||
      compatible[0] ||
      rows.find((row: any) => sanitizeString(row?.organization_id, 120) === safeClinicId) ||
      rows[0];
    return selected ? normalizeAgeBasedAnamnesisTemplate(selected, patient, compatible) : fallback;
  } catch (error: any) {
    console.warn('[AnamnesisTemplates] fallback para template legado:', error?.message || String(error));
    return fallback;
  }
}

