function getAppPortalUrl(params: Record<string, string> = {}) {
  const baseUrl = sanitizeString(process.env.VERTO_APP_BASE_URL || process.env.APP_BASE_URL || 'https://www.appverto.com.br', 500)
    .replace(/\/+$/, '');
  const url = new URL(baseUrl || 'https://www.appverto.com.br');
  Object.entries(params).forEach(([key, value]) => {
    if (value) url.searchParams.set(key, value);
  });
  return url.toString();
}

function getAppPortalPathUrl(pathname: string, params: Record<string, string> = {}) {
  const baseUrl = sanitizeString(process.env.VERTO_APP_BASE_URL || process.env.APP_BASE_URL || 'https://www.appverto.com.br', 500)
    .replace(/\/+$/, '');
  const url = new URL(baseUrl || 'https://www.appverto.com.br');
  url.pathname = `/${sanitizeString(pathname, 200).replace(/^\/+/, '')}`;
  Object.entries(params).forEach(([key, value]) => {
    if (value) url.searchParams.set(key, value);
  });
  return url.toString();
}

async function createRelationshipConfirmationRequest(params: {
  patientId: string;
  clinicId: string;
  email: string;
  patientName: string;
  responsibleUserId?: string | null;
  createdBy?: string | null;
  metadata?: Record<string, any>;
}) {
  const token = crypto.randomBytes(32).toString('base64url');
  const tokenHash = hashIdentifier(`relationship-confirmation:${token}`);
  const nowIso = new Date().toISOString();
  const expiresAt = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString();
  const id = crypto.randomUUID();
  const payload = cleanObject({
    id,
    organization_id_requesting: params.clinicId,
    patient_id_requesting: params.patientId,
    responsible_user_id: isUuid(params.responsibleUserId || '') ? params.responsibleUserId : null,
    email_normalized: sanitizeEmail(params.email),
    status: 'PENDING',
    confirmation_token_hash: tokenHash,
    sent_at: nowIso,
    expires_at: expiresAt,
    created_by: isUuid(params.createdBy || '') ? params.createdBy : null,
    created_at: nowIso,
    updated_at: nowIso,
    metadata: sanitizeClinicalPayload(params.metadata || {})
  });
  const insert = await insertRowWithSchemaFallback('patient_relationship_confirmations', payload, 'relationship-confirmation');
  if (!insert.success) return { success: false, error: insert.error, sent: false, token: null, confirmationId: null };

  const confirmationUrl = getAppPortalPathUrl('/portal/confirmar-vinculo', { token });
  const emailTemplate = buildRelationshipConfirmationEmail({
    patientName: params.patientName,
    confirmationUrl
  });
  const sent = await sendTransactionalEmailSafe({
    to: sanitizeEmail(params.email),
    subject: emailTemplate.subject,
    html: emailTemplate.html,
    context: 'patient_relationship_confirmation',
    from: OFFICIAL_FROM_NOREPLY,
    replyTo: OFFICIAL_TRANSACTIONAL_REPLY_TO,
    metadata: {
      patientId: params.patientId,
      email: maskEmail(sanitizeEmail(params.email))
    }
  });
  return { success: true, error: null, sent, token, confirmationId: id };
}

async function fetchPatientAnamnesisFlow(patientId: string, clinicId: string) {
  const patient = await fetchPatientForAnamnesis(patientId, clinicId);
  if (!patient?.id) return { patient: null, request: null, response: null, template: getDefaultAnamnesisTemplate() };
  const registrationPayload = await fetchPatientRegistrationPayloadForAnamnesis(patientId, clinicId);
  const patientContext = buildPatientAnamnesisContext(patient, registrationPayload);

  const requestResult = await fetchPatientAnamnesisRequestWithSchemaFallback({ patientId, clinicId });

  if (requestResult.error && !isMissingRelationError(requestResult.error)) throw requestResult.error;
  const requestId = sanitizeString(requestResult.data?.id, 120);
  let responseResult = await fetchLatestPatientAnamnesisResponseWithSchemaFallback(
    patientId,
    clinicId,
    isUuid(requestId) ? requestId : null
  );
  const requestStatus = sanitizeString(requestResult.data?.status, 60).toUpperCase();
  if (!responseResult.data?.id && ['SUBMITTED', 'REVIEWED'].includes(requestStatus)) {
    responseResult = await fetchLatestPatientAnamnesisResponseWithSchemaFallback(patientId, clinicId);
  }
  if (responseResult.error && !isMissingRelationError(responseResult.error)) throw responseResult.error;
  const template = await fetchAnamnesisTemplateForPatient(
    patientContext,
    clinicId,
    sanitizeString(requestResult.data?.template_id || responseResult.data?.template_id, 120)
  );
  const prefillAnswers = buildPatientRegistrationAnamnesisPrefill(patient, registrationPayload);

  return {
    patient,
    patientContext,
    request: requestResult.error ? null : requestResult.data || null,
    response: responseResult.error ? null : responseResult.data || null,
    template,
    prefillAnswers,
    prefilledKeys: Object.entries(prefillAnswers)
      .filter(([, value]) => value !== null && value !== undefined && String(value).trim() !== '')
      .map(([key]) => key)
  };
}

async function upsertAnamnesisResponse(params: {
  patientId: string;
  clinicId: string;
  requestId?: string | null;
  templateId?: string | null;
  respondentUserId?: string | null;
  respondentRole: string;
  answers: any;
  status: 'DRAFT' | 'SUBMITTED' | 'REVIEWED';
}) {
  const nowIso = new Date().toISOString();
  const requestId = sanitizeString(params.requestId, 120);
  const templateId = sanitizeString(params.templateId, 120);
  const answers = normalizeAnamnesisAnswers(params.answers || {});
  let existingQuery = supabase
    .from('patient_anamnesis_responses')
    .select('id')
    .eq('organization_id', params.clinicId)
    .eq('patient_id', params.patientId)
    .order('updated_at', { ascending: false })
    .limit(1);
  existingQuery = isUuid(requestId)
    ? existingQuery.eq('request_id', requestId)
    : existingQuery.is('request_id', null);
  const existing = await existingQuery.maybeSingle();
  if (existing.error && !isMissingRelationError(existing.error)) throw existing.error;
  let nextVersion = 1;
  if (!existing.data?.id) {
    const latestVersion = await supabase
      .from('patient_anamnesis_responses')
      .select('version')
      .eq('organization_id', params.clinicId)
      .eq('patient_id', params.patientId)
      .order('version', { ascending: false })
      .limit(1)
      .maybeSingle();
    if (!latestVersion.error) {
      nextVersion = Math.max(1, Number(latestVersion.data?.version || 0) + 1);
    }
  }

  const payload = cleanObject({
    organization_id: params.clinicId,
    patient_id: params.patientId,
    request_id: isUuid(requestId) ? requestId : null,
    template_id: isUuid(templateId) ? templateId : null,
    respondent_user_id: isUuid(params.respondentUserId || '') ? params.respondentUserId : null,
    respondent_role: sanitizeString(params.respondentRole, 60) || 'family',
    answers,
    status: params.status,
    submitted_at: params.status === 'SUBMITTED' || params.status === 'REVIEWED' ? nowIso : undefined,
    reviewed_at: params.status === 'REVIEWED' ? nowIso : undefined,
    reviewed_by: params.status === 'REVIEWED' && isUuid(params.respondentUserId || '') ? params.respondentUserId : undefined,
    version: existing.data?.id ? undefined : nextVersion,
    updated_at: nowIso
  });

  if (existing.data?.id) {
    const update = await updateRowsWithSchemaFallback({
      tableName: 'patient_anamnesis_responses',
      payload,
      filters: [{ column: 'id', value: existing.data.id }],
      context: 'anamnesis-response-update'
    });
    if (!update.success) throw update.error;
    return { id: sanitizeString(existing.data.id, 120), ...payload };
  }

  const id = crypto.randomUUID();
  const insert = await insertRowWithSchemaFallback(
    'patient_anamnesis_responses',
    { id, ...payload, created_at: nowIso },
    'anamnesis-response-insert'
  );
  if (!insert.success) throw insert.error;
  return { id, ...payload, created_at: nowIso };
}

function sanitizeIsoDateOnly(value: unknown): string | null {
  const raw = sanitizeString(value, 40);
  if (!raw) return null;
  const isValidDateOnlyParts = (year: number, month: number, day: number) => {
    if (!Number.isInteger(year) || !Number.isInteger(month) || !Number.isInteger(day)) return false;
    if (year < 1900 || year > 2200 || month < 1 || month > 12 || day < 1 || day > 31) return false;
    const localDate = new Date(year, month - 1, day);
    return (
      localDate.getFullYear() === year &&
      localDate.getMonth() === month - 1 &&
      localDate.getDate() === day
    );
  };
  const isoDate = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoDate) {
    const year = Number(isoDate[1]);
    const month = Number(isoDate[2]);
    const day = Number(isoDate[3]);
    return isValidDateOnlyParts(year, month, day) ? `${isoDate[1]}-${isoDate[2]}-${isoDate[3]}` : null;
  }
  const brazilianDate = raw.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (brazilianDate) {
    const day = Number(brazilianDate[1]);
    const month = Number(brazilianDate[2]);
    const year = Number(brazilianDate[3]);
    return isValidDateOnlyParts(year, month, day) ? `${brazilianDate[3]}-${brazilianDate[2]}-${brazilianDate[1]}` : null;
  }
  return null;
}

function buildPatientProfileTypeFields(body: any) {
  const canonicalProfileType = normalizePatientProfileType(
    body?.patientProfileType ||
      body?.patient_profile_type ||
      body?.panelType ||
      body?.panel_type ||
      body?.profileType ||
      body?.profile_type ||
      body?.type,
  );
  return {
    patient_profile_type: canonicalProfileType,
    panel_type: canonicalProfileType,
    profile_type: canonicalProfileType,
    type: mapPatientProfileTypeToLegacyPortalType(canonicalProfileType)
  };
}

function buildPatientIdentityPersistenceFields(body: any) {
  const address = body?.address && typeof body.address === 'object' ? body.address : {};
  const guardian = body?.guardian && typeof body.guardian === 'object' ? body.guardian : {};
  const profileFields = buildPatientProfileTypeFields(body);
  const responsiblePhoneSource =
    body?.responsiblePhone ||
    body?.responsible_phone ||
    body?.responsavelTelefone ||
    guardian?.telefone ||
    guardian?.phone;
  const safeMetadata = cleanObject({
    address: cleanObject({
      cep: sanitizeString(body?.cep || address?.cep, 20),
      logradouro: sanitizeString(body?.logradouro || address?.logradouro, 180),
      numero: sanitizeString(body?.numero || address?.numero, 40),
      complemento: sanitizeString(body?.complemento || address?.complemento, 120),
      bairro: sanitizeString(body?.bairro || address?.bairro, 120),
      cidade: sanitizeString(body?.cidade || address?.cidade, 120),
    }),
    isMinor: Boolean(body?.isMinor || body?.is_minor || body?.menorDeIdade),
    guardian: cleanObject({
      nome: sanitizeString(body?.responsibleName || body?.responsible_name || body?.responsavelNome || guardian?.nome || guardian?.name, 160),
      dataNascimento: sanitizeIsoDateOnly(body?.responsibleBirthDate || body?.responsible_birth_date || body?.responsavelDataNascimento || guardian?.dataNascimento || guardian?.birthDate || guardian?.birth_date),
      cpf: normalizeCpf(body?.responsibleCpf || body?.responsible_cpf || body?.responsavelCpf || guardian?.cpf) || undefined,
      telefone: normalizeBrazilMobilePhone(responsiblePhoneSource) || sanitizePhone(responsiblePhoneSource),
      email: sanitizeEmail(body?.responsibleEmail || body?.responsible_email || body?.responsavelEmail || guardian?.email) || undefined,
      relacao: sanitizeString(
        body?.responsibleRelationship ||
          body?.responsible_relationship ||
          body?.responsavelRelacao ||
          guardian?.relacao ||
          guardian?.relationship,
        120
      ),
    }),
    registrationNotes: sanitizeTextField(body?.notes || body?.outrasInformacoes || body?.otherInformation, 4000),
    responsibleRelationship: sanitizeString(
      body?.responsibleRelationship ||
        body?.responsible_relationship ||
        body?.responsavelRelacao ||
        guardian?.relacao ||
        guardian?.relationship,
      120
    ),
  });
  return cleanObject({
    ...profileFields,
    social_name: sanitizeString(body?.socialName || body?.social_name || body?.nomeSocial, 160),
    birth_date: sanitizeIsoDateOnly(body?.birthDate || body?.birth_date || body?.dataNascimento),
    gender: sanitizeString(body?.gender || body?.genero, 60),
    insurance_type: sanitizeString(body?.insuranceType || body?.insurance_type || body?.convenioTipo, 60),
    insurance_name: sanitizeString(body?.insuranceName || body?.insurance_name || body?.convenioNome, 160),
    insurance_card_number: sanitizeString(body?.insuranceCardNumber || body?.insurance_card_number || body?.cardNumber || body?.convenioCarteirinha, 120),
    patient_group: sanitizeString(body?.group || body?.patient_group || body?.grupo, 80),
    lead_source: sanitizeString(body?.source || body?.lead_source || body?.comoConheceu, 120),
    notes: sanitizeTextField(body?.notes || body?.outrasInformacoes || body?.otherInformation, 4000),
    rg: sanitizeString(body?.rg, 40),
    cep: sanitizeString(body?.cep || address?.cep, 20),
    responsible_name: sanitizeString(body?.responsibleName || body?.responsible_name || body?.responsavelNome || guardian?.nome, 160),
    responsible_birth_date: sanitizeIsoDateOnly(body?.responsibleBirthDate || body?.responsible_birth_date || body?.responsavelDataNascimento || guardian?.dataNascimento),
    responsible_cpf: normalizeCpf(body?.responsibleCpf || body?.responsible_cpf || body?.responsavelCpf || guardian?.cpf) || undefined,
    responsible_phone: normalizeBrazilMobilePhone(responsiblePhoneSource) || sanitizePhone(responsiblePhoneSource),
    responsible_email: sanitizeEmail(body?.responsibleEmail || body?.responsible_email || body?.responsavelEmail || guardian?.email) || undefined,
    responsible_relationship: sanitizeString(body?.responsibleRelationship || body?.responsible_relationship || body?.responsavelRelacao || guardian?.relacao || guardian?.relationship, 120),
    metadata: Object.keys(safeMetadata).length ? safeMetadata : undefined,
  });
}

function buildPatientFinancialPlanRows(params: {
  financialPlans: any[];
  patientId: string;
  clinicId: string;
  actorId?: string | null;
}) {
  return normalizePatientFinancialPlans(params.financialPlans)
    .filter(isPatientFinancialPlanComplete)
    .map(serializePatientFinancialPlanForPayload)
    .map((plan: any) => cleanObject({
      id: isUuid(sanitizeString(plan.id, 120)) ? sanitizeString(plan.id, 120) : undefined,
      organization_id: params.clinicId,
      patient_id: params.patientId,
      service_type: sanitizeString(plan.serviceType, 60) || 'CUSTOM',
      custom_service_name: sanitizeString(plan.customServiceName, 120) || null,
      service_name_snapshot: sanitizeString(plan.serviceNameSnapshot || plan.specialty, 120) || null,
      billing_mode: sanitizeString(plan.billingMode, 40) || 'PRIVATE',
      payer_id: isUuid(sanitizeString(plan.payerId, 120)) ? sanitizeString(plan.payerId, 120) : null,
      payer_name_snapshot: sanitizeString(plan.payerNameSnapshot || plan.insuranceName, 160) || null,
      insurance_plan_name: sanitizeString(plan.insurancePlanName, 160) || null,
      authorization_code: sanitizeString(plan.authorizationCode, 120) || null,
      authorization_valid_until: sanitizeIsoDateOnly(plan.authorizationValidUntil),
      sessions_quantity: asSafeNumber(plan.sessionsQuantity, 1, 10000),
      quantity_period: sanitizeString(plan.quantityPeriod, 40) || null,
      amount_cents: Math.max(0, Math.round(Number(plan.amountCents || 0) || 0)),
      copayment_amount_cents: Math.max(0, Math.round(Number(plan.copaymentAmountCents || 0) || 0)),
      payment_method: sanitizeString(plan.paymentMethod || plan.billingMethod, 40) || null,
      due_day: asSafeNumber(plan.dueDay, 1, 31),
      package_valid_until: sanitizeIsoDateOnly(plan.packageValidUntil),
      status: sanitizeString(plan.status, 40) || 'ACTIVE',
      notes: sanitizeTextField(plan.notes, 1000) || null,
      created_by: isUuid(sanitizeString(params.actorId, 120)) ? sanitizeString(params.actorId, 120) : null,
      updated_at: new Date().toISOString()
    }));
}

async function persistPatientFinancialPlans(params: {
  patientId: string;
  clinicId: string;
  actorId?: string | null;
  financialPlans: any[];
}) {
  if (!isUuid(params.patientId) || !isUuid(params.clinicId)) {
    return { success: false, error: 'Paciente ou clínica inválidos.' };
  }
  const rows = buildPatientFinancialPlanRows(params);
  const payerIds = Array.from(new Set(rows.map((row: any) => sanitizeString(row.payer_id, 120)).filter((id: string) => isUuid(id))));
  if (payerIds.length > 0) {
    const { data: payers, error: payerError } = await supabase
      .from('clinic_payers')
      .select('id')
      .eq('organization_id', params.clinicId)
      .in('id', payerIds);
    if (payerError && !isMissingRelationError(payerError)) throw payerError;
    const validPayers = new Set((Array.isArray(payers) ? payers : []).map((payer: any) => sanitizeString(payer?.id, 120)));
    if (!payerIds.every((payerId) => validPayers.has(payerId))) {
      return { success: false, error: 'Pagador fora do escopo da clínica.' };
    }
  }

  const deleteResult = await supabase
    .from('patient_financial_plans')
    .delete()
    .eq('organization_id', params.clinicId)
    .eq('patient_id', params.patientId);
  if (deleteResult.error) {
    if (isMissingRelationError(deleteResult.error)) {
      return { success: false, warning: 'Tabela patient_financial_plans ainda não configurada.' };
    }
    throw deleteResult.error;
  }
  if (!rows.length) return { success: true, data: [] };

  const insertResult = await supabase
    .from('patient_financial_plans')
    .insert(rows)
    .select(PATIENT_FINANCIAL_PLAN_SELECT);
  if (insertResult.error) {
    if (isMissingRelationError(insertResult.error)) {
      return { success: false, warning: 'Tabela patient_financial_plans ainda não configurada.' };
    }
    throw insertResult.error;
  }
  return { success: true, data: insertResult.data || [] };
}

async function updatePatientStatusIfNeeded(user: any): Promise<'active' | 'inactive' | 'waiting_treatment'> {
  const status = await derivePatientTreatmentStatus(user);
  if (sanitizeString(user?.role, 40).toLowerCase() !== 'patient' || !sanitizeString(user?.id, 120)) {
    return status;
  }
  try {
    const safeEmail = sanitizeEmail(user?.email);
    await supabase
      .from('users')
      .update({ status })
      .eq('id', sanitizeString(user.id, 120));
      if (status === 'active' && safeEmail) {
        const patientActivationResult = await supabase
          .from('patients')
          .update({ status: 'active' })
          .ilike('email', safeEmail)
          .eq('is_active', true)
          .is('deleted_at', null)
          .in('status', ['pending', 'waiting_treatment', 'inactive'])
          .or('onboarding_status.is.null,onboarding_status.in.(READY_FOR_CARE,ANAMNESIS_REVIEWED)');
        if (patientActivationResult.error && extractMissingColumnName(patientActivationResult.error) === 'onboarding_status') {
          await supabase
            .from('patients')
            .update({ status: 'active' })
            .ilike('email', safeEmail)
            .eq('is_active', true)
            .is('deleted_at', null)
            .in('status', ['waiting_treatment', 'inactive']);
        }
      }
  } catch (error) {
    console.warn('[Auth] Não foi possível atualizar status clínico do paciente:', (error as any)?.message || error);
  }
  return status;
}

async function ensureClinicAndMembershipForCoordinator(userId: string, clinicName?: string | null) {
  const safeClinicName = sanitizeString(clinicName, 160) || 'Minha Clinica';

  await supabase
    .from('clinics')
    .upsert([{
      id: userId,
      owner_user_id: userId,
      name: safeClinicName,
      created_at: new Date().toISOString()
    }], { onConflict: 'id' });

  await supabase
    .from('clinic_memberships')
    .upsert([{
      user_id: userId,
      clinic_id: userId,
      role: 'coordinator',
      status: 'active',
      created_at: new Date().toISOString()
    }], { onConflict: 'user_id,clinic_id' });
}

// Initialize Supabase Admin Client (using service role for backend access)
const supabaseUrl = process.env.SUPABASE_URL || "";
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || "";
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || process.env.VITE_SUPABASE_ANON_KEY || "";
const supabasePublishableKey = process.env.SUPABASE_PUBLISHABLE_KEY || process.env.VITE_SUPABASE_PUBLISHABLE_KEY || "";
const supabasePublicClientKey = supabasePublishableKey || supabaseAnonKey;

function getProjectRefFromSupabaseUrl(url: string): string | null {
  try {
    const host = new URL(url).host.toLowerCase();
    if (!host.endsWith('.supabase.co')) return null;
    const ref = host.split('.')[0];
    return ref || null;
  } catch {
    return null;
  }
}

function decodeJwtPayload(token: string): Record<string, any> | null {
  try {
    const parts = token.split('.');
    if (parts.length < 2) return null;
    const payloadB64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
    const padded = payloadB64 + '='.repeat((4 - (payloadB64.length % 4)) % 4);
    const json = Buffer.from(padded, 'base64').toString('utf8');
    return JSON.parse(json);
  } catch {
    return null;
  }
}

function tokenMatchesCurrentProject(token: string): { ok: boolean; reason?: string } {
  const payload = decodeJwtPayload(token);
  const iss = String(payload?.iss || '');
  const refFromToken = (() => {
    const m = iss.match(/https:\/\/([a-z0-9-]+)\.supabase\.co\/auth\/v1/i);
    return m?.[1]?.toLowerCase() || null;
  })();
  const refFromServer = getProjectRefFromSupabaseUrl(supabaseUrl)?.toLowerCase() || null;
  if (!refFromToken || !refFromServer) {
    return { ok: true };
  }
  if (refFromToken !== refFromServer) {
    return { ok: false, reason: `token_ref=${refFromToken}, server_ref=${refFromServer}` };
  }
  return { ok: true };
}

