  app.patch('/api/appointments/:appointmentId/billing-context', portalActionLimiter, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'Payload de contexto de pagador')) return;
      const context = await fetchAppointmentForBillingContext(req.params.appointmentId, req.session.user);
      if (!context.ok) return res.status((context as any).status || 404).json(payerSafeError((context as any).status || 404));
      const organizationId = (context as any).organizationId;
      const appointment = (context as any).appointment;
      const payerId = sanitizeString(req.body?.payerId || req.body?.payer_id, 120);
      const requestedPayerName = sanitizeString(req.body?.payerName || req.body?.payer_name_snapshot, 180);
      const payer = isUuid(payerId) ? await fetchPayerForAdmin(payerId, organizationId) : null;
      if (payerId && !payer && !requestedPayerName) return res.status(404).json(payerSafeError(404));
      const hasAppointmentMirror = await ensureAppointmentMirrorForBillingContext({
        organizationId,
        appointment,
        user: req.session.user
      });
      if (!hasAppointmentMirror) {
        console.warn('[PayerRequirements] consulta sem espelho em appointments para salvar pagador.', {
          appointmentId: appointment.id,
          organizationId
        });
        return res.status(409).json({
          success: false,
          error: 'Sincronize a agenda e tente salvar o pagador novamente.'
        });
      }
      const existing = await fetchAppointmentBillingContextRow(organizationId, appointment.id);
      const now = new Date().toISOString();
      const payload = cleanObject({
        id: existing?.id || crypto.randomUUID(),
        organization_id: organizationId,
        appointment_id: appointment.id,
        patient_id: appointment.patient_id,
        payer_id: payer?.id || null,
        payer_type: payer?.payer_type || req.body?.payerType || req.body?.payer_type
          ? normalizePayerType(payer?.payer_type || req.body?.payerType || req.body?.payer_type)
          : null,
        payer_name_snapshot: sanitizeString(payer?.name || requestedPayerName, 180) || null,
        service_type: sanitizeString(req.body?.serviceType || req.body?.service_type || appointment.service_type || appointment.approach, 120) || null,
        insurance_card_number: sanitizeString(req.body?.insuranceCardNumber || req.body?.insurance_card_number || req.body?.cardNumber || req.body?.card_number, 120) || null,
        insurance_plan_name: sanitizeString(req.body?.insurancePlanName || req.body?.insurance_plan_name, 160) || null,
        authorization_code: sanitizeString(req.body?.authorizationCode || req.body?.authorization_code, 120) || null,
        guide_number: sanitizeString(req.body?.guideNumber || req.body?.guide_number, 120) || null,
        procedure_code: sanitizeString(req.body?.procedureCode || req.body?.procedure_code, 80) || null,
        notes: sanitizeTextField(req.body?.notes, 1200) || null,
        source: ['PATIENT_DEFAULT', 'MANUAL'].includes(sanitizeString(req.body?.source, 60).toUpperCase())
          ? sanitizeString(req.body?.source, 60).toUpperCase()
          : 'MANUAL',
        metadata: sanitizeClinicalPayload(cleanObject({
          insurance_card_number: sanitizeString(req.body?.insuranceCardNumber || req.body?.insurance_card_number || req.body?.cardNumber || req.body?.card_number, 120) || undefined,
          insurance_plan_name: sanitizeString(req.body?.insurancePlanName || req.body?.insurance_plan_name, 160) || undefined,
          source: ['PATIENT_DEFAULT', 'MANUAL'].includes(sanitizeString(req.body?.source, 60).toUpperCase())
            ? sanitizeString(req.body?.source, 60).toUpperCase()
            : 'MANUAL'
        })),
        created_by: existing?.created_by || (isUuid(sanitizeString(req.session.user?.id, 120)) ? sanitizeString(req.session.user?.id, 120) : null),
        updated_by: isUuid(sanitizeString(req.session.user?.id, 120)) ? sanitizeString(req.session.user?.id, 120) : null,
        created_at: existing?.created_at || now,
        updated_at: now
      });
      const data = await upsertAppointmentBillingContextRow(payload, Boolean(existing?.id));
      try {
        await writePayerRequirementAuditLog({
          organizationId,
          payerId: data?.payer_id || null,
          appointmentId: appointment.id,
          action: 'BILLING_CONTEXT_UPDATED',
          previousValue: existing,
          newValue: data,
          performedBy: sanitizeString(req.session.user?.id, 120)
        });
      } catch (auditError: any) {
        console.warn('[PayerRequirements] auditoria apos pagador falhou:', auditError?.message || String(auditError));
      }
      let resolvedRequirements: any = null;
      try {
        resolvedRequirements = await fetchClosureRequirements(
          organizationId,
          data?.service_type || appointment.service_type || appointment.approach || null,
          appointment.id
        );
        if (resolvedRequirements?.requireGuide) {
          await upsertRequiredDocumentStatus({
            organizationId,
            appointmentId: appointment.id,
            patientId: appointment.patient_id,
            payerId: data?.payer_id || null,
            serviceType: data?.service_type || appointment.service_type || appointment.approach || null,
            documentType: 'GUIDE',
            status: data?.guide_number ? 'PROVIDED' : 'PENDING',
            performedBy: sanitizeString(req.session.user?.id, 120)
          });
        }
        if (resolvedRequirements?.requireAuthorization) {
          await upsertRequiredDocumentStatus({
            organizationId,
            appointmentId: appointment.id,
            patientId: appointment.patient_id,
            payerId: data?.payer_id || null,
            serviceType: data?.service_type || appointment.service_type || appointment.approach || null,
            documentType: 'AUTHORIZATION',
            status: data?.authorization_code ? 'PROVIDED' : 'PENDING',
            performedBy: sanitizeString(req.session.user?.id, 120)
          });
        }
      } catch (documentError: any) {
        console.warn('[PayerRequirements] pendencias apos pagador falharam:', documentError?.message || String(documentError));
      }
      let documents: any[] = [];
      try {
        documents = await fetchRequiredDocumentsForAppointment(organizationId, appointment.id);
      } catch (documentsError: any) {
        console.warn('[PayerRequirements] documentos apos pagador falharam:', documentsError?.message || String(documentsError));
      }
      try {
        await persistAppointmentClosureCheck({
          appointmentId: appointment.id,
          user: req.session.user,
          force: true
        });
      } catch (closureError: any) {
        console.warn('[PayerRequirements] fechamento pontual apos pagador falhou:', closureError?.message || String(closureError));
      }
      const serialized = serializeBillingContext(data, payer, documents);
      return res.json({ success: true, message: 'Pagador salvo na consulta.', data: serialized, billingContext: serialized });
    } catch (error: any) {
      console.warn('[PayerRequirements] billing context update failed:', error?.message || String(error));
      const code = sanitizeString(error?.code, 40);
      const message = extractSupabaseErrorMessage(error).toLowerCase();
      const status = code === '42501' || message.includes('row-level security') || message.includes('permission denied')
        ? 403
        : ['23502', '23503', '23514', '22P02'].includes(code)
          ? 400
          : 500;
      return res.status(status).json({
        success: false,
        error: 'Não foi possível salvar o pagador da consulta agora.'
      });
    }
  });

  app.post('/api/appointments/:appointmentId/required-documents/:documentId/waive', portalActionLimiter, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 16 * 1024, 'Payload de dispensa de documento')) return;
      const reason = sanitizeTextField(req.body?.reason || req.body?.justification || req.body?.justificativa, 800);
      if (reason.length < 8) return res.status(400).json(payerSafeError(400));
      const context = await fetchAppointmentForBillingContext(req.params.appointmentId, req.session.user);
      if (!context.ok) return res.status((context as any).status || 404).json(payerSafeError((context as any).status || 404));
      const organizationId = (context as any).organizationId;
      const appointment = (context as any).appointment;
      const documentId = sanitizeString(req.params.documentId, 120);
      if (!isUuid(documentId)) return res.status(400).json(payerSafeError(400));
      const existingResult = await supabase
        .from('appointment_required_documents')
        .select(APPOINTMENT_REQUIRED_DOCUMENT_SELECT)
        .eq('organization_id', organizationId)
        .eq('appointment_id', appointment.id)
        .eq('id', documentId)
        .limit(1)
        .maybeSingle();
      if (existingResult.error) {
        if (hasMissingFinancialSchema(existingResult.error)) return res.status(404).json(payerSafeError(404));
        throw existingResult.error;
      }
      if (!existingResult.data?.id) return res.status(404).json(payerSafeError(404));
      const { data, error } = await supabase
        .from('appointment_required_documents')
        .update({
          status: 'WAIVED',
          updated_at: new Date().toISOString()
        })
        .eq('organization_id', organizationId)
        .eq('appointment_id', appointment.id)
        .eq('id', documentId)
        .select(APPOINTMENT_REQUIRED_DOCUMENT_SELECT)
        .maybeSingle();
      if (error) throw error;
      await writePayerRequirementAuditLog({
        organizationId,
        payerId: data?.required_by_payer_id || null,
        appointmentId: appointment.id,
        action: 'DOCUMENT_WAIVED',
        previousValue: existingResult.data,
        newValue: data,
        performedBy: sanitizeString(req.session.user?.id, 120),
        metadata: { reason }
      });
      void regenerateClosureForAppointments([appointment.id], req.session.user, 'required_document_waived');
      return res.json({ success: true, data: serializeBillingContext(null, null, [data]).documents[0] });
    } catch (error: any) {
      console.warn('[PayerRequirements] document waive failed:', error?.message || String(error));
      return res.status(500).json(payerSafeError(500));
    }
  });

  app.get('/api/closure/appointments', checkAuth, requireRoles('coordinator', 'therapist', 'admin', 'owner'), async (req: any, res) => {
    const { page, limit, from, to } = parseClosurePageParams(req.query);
    const emptyClosurePayload = (reason = '') => ({ success: true, data: [], page, limit, totals: {
      ready: 0,
      pending: 0,
      warning: 0,
      notBillable: 0,
      draft: 0,
      total: 0,
      scheduledMinutes: 0,
      actualMinutes: 0,
      blockingIssues: 0,
      warningIssues: 0
    }, warning: process.env.NODE_ENV === 'production' ? undefined : reason || undefined });
    try {
      const range = parseClosureDateRange(req.query);
      if (!range.ok) return res.status(400).json(closureSafeError(400));
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      if (!isUuid(clinicId)) return res.status(400).json(closureSafeError(400));
      const status = parseClosureStatusFilter(req.query?.status);
      const patientId = sanitizeString(req.query?.patientId || req.query?.patient_id, 120);
      const professionalId = sanitizeString(req.query?.professionalId || req.query?.professional_id, 120);
      const serviceType = sanitizeString(req.query?.serviceType || req.query?.service_type, 120);
      const payerId = sanitizeString(req.query?.payerId || req.query?.payer_id, 120);
      const onlyPending = String(req.query?.onlyPending || req.query?.somentePendencias || '').toLowerCase() === 'true';
      const onlyReady = String(req.query?.onlyReady || req.query?.somenteProntas || '').toLowerCase() === 'true';
      const onlyWarnings = String(req.query?.onlyWarnings || req.query?.somenteAlertas || '').toLowerCase() === 'true';
      const missingKind = sanitizeString(req.query?.missing || req.query?.pendencia, 80).toLowerCase();

      const isSignatureMissingFilter = missingKind === 'signature' || missingKind === 'assinatura';
      const isReportMissingFilter = missingKind === 'report' || missingKind === 'relatorio';
      const isGuideMissingFilter = missingKind === 'guide' || missingKind === 'guia';
      const isAuthorizationMissingFilter = missingKind === 'authorization' || missingKind === 'autorizacao';
      const isDocumentsMissingFilter = missingKind === 'documents' || missingKind === 'documentos';

      const variants = [
        {
          label: 'current',
          select: APPOINTMENT_CLOSURE_LIST_SELECT,
          hasPayerFields: true,
          hasDocumentCount: true,
          hasMainIssues: true
        },
        {
          label: 'legacy',
          select: APPOINTMENT_CLOSURE_LEGACY_LIST_SELECT,
          hasPayerFields: false,
          hasDocumentCount: false,
          hasMainIssues: true
        },
        {
          label: 'minimal',
          select: APPOINTMENT_CLOSURE_MINIMAL_LIST_SELECT,
          hasPayerFields: false,
          hasDocumentCount: false,
          hasMainIssues: false
        }
      ];

      const canApplyRequestedFilters = (variant: any) => {
        if (isUuid(payerId) && !variant.hasPayerFields) return false;
        if ((isGuideMissingFilter || isAuthorizationMissingFilter) && !variant.hasPayerFields) return false;
        if (isDocumentsMissingFilter && !variant.hasDocumentCount) return false;
        if ((isSignatureMissingFilter || isReportMissingFilter) && !variant.hasMainIssues) return false;
        return true;
      };

      const applySharedClosureFilters = async (baseQuery: any, variant: any, useRange = true) => {
        let scopedQuery = baseQuery
          .eq('organization_id', clinicId)
          .gte('scheduled_start', range.fromIso)
          .lte('scheduled_start', range.toIso);
        if (useRange) scopedQuery = scopedQuery.order('scheduled_start', { ascending: true }).range(from, to);
        scopedQuery = await applyClosureTenantScope(scopedQuery, req.session.user, clinicId);
        if (status) scopedQuery = scopedQuery.eq('readiness_status', status);
        if (onlyPending) scopedQuery = scopedQuery.eq('readiness_status', 'PENDING');
        if (onlyReady) scopedQuery = scopedQuery.eq('readiness_status', 'READY');
        if (onlyWarnings) scopedQuery = scopedQuery.eq('readiness_status', 'WARNING');
        if (isUuid(patientId)) scopedQuery = scopedQuery.eq('patient_id', patientId);
        if (isUuid(professionalId)) scopedQuery = scopedQuery.eq('professional_id', professionalId);
        if (serviceType) scopedQuery = scopedQuery.eq('service_type', serviceType);
        if (isUuid(payerId) && variant.hasPayerFields) scopedQuery = scopedQuery.eq('payer_id', payerId);
        if (isSignatureMissingFilter && variant.hasMainIssues) scopedQuery = scopedQuery.contains('main_issues', ['Assinatura pendente para fechamento da sessão.']);
        if (isReportMissingFilter && variant.hasMainIssues) scopedQuery = scopedQuery.contains('main_issues', ['Relatório da sessão ainda não foi preenchido.']);
        if (isGuideMissingFilter && variant.hasPayerFields) scopedQuery = scopedQuery.is('guide_number', null);
        if (isAuthorizationMissingFilter && variant.hasPayerFields) scopedQuery = scopedQuery.is('authorization_code', null);
        if (isDocumentsMissingFilter && variant.hasDocumentCount) scopedQuery = scopedQuery.gt('required_document_pending_count', 0);
        return scopedQuery;
      };

      let rows: any[] = [];
      let activeVariant: any = null;
      let lastSchemaError: any = null;

      for (const variant of variants) {
        if (!canApplyRequestedFilters(variant)) continue;
        let query = supabase
          .from('appointment_closure_checks')
          .select(variant.select);
        query = await applySharedClosureFilters(query, variant, true);
        const { data, error } = await query;
        if (error) {
          lastSchemaError = error;
          console.warn(`[Closure] list fallback from ${variant.label}:`, error?.message || String(error));
          continue;
        }
        rows = Array.isArray(data) ? data : [];
        activeVariant = variant;
        break;
      }

      if (!activeVariant) {
        if (lastSchemaError) {
          console.warn('[Closure] list returned empty after schema fallback:', lastSchemaError?.message || String(lastSchemaError));
        }
        return res.json(emptyClosurePayload('closure_schema_unavailable'));
      }

      const patientIds = Array.from(new Set(rows.map((row: any) => sanitizeString(row.patient_id, 120)).filter((id: string) => isUuid(id))));
      const professionalIds = Array.from(new Set(rows.map((row: any) => sanitizeString(row.professional_id, 120)).filter((id: string) => isUuid(id))));

      let totalsRows: any[] = [];
      try {
        if (canApplyRequestedFilters(activeVariant)) {
          let totalsQuery = supabase
            .from('appointment_closure_checks')
            .select('readiness_status, scheduled_minutes, actual_minutes, blocking_issues_count, warning_issues_count', { count: 'exact' })
            .limit(1000);
          totalsQuery = await applySharedClosureFilters(totalsQuery, activeVariant, false);
          const totalsResult = await totalsQuery;
          if (totalsResult.error) {
            console.warn('[Closure] totals skipped:', totalsResult.error?.message || String(totalsResult.error));
          } else {
            totalsRows = Array.isArray(totalsResult.data) ? totalsResult.data : [];
          }
        }
      } catch (totalsError: any) {
        console.warn('[Closure] totals unavailable:', totalsError?.message || String(totalsError));
      }

      const [patientsResult, professionalsResult] = await Promise.all([
        patientIds.length > 0
          ? supabase.from('patients').select('id, name').eq('clinic_id', clinicId).in('id', patientIds).limit(patientIds.length)
          : Promise.resolve({ data: [], error: null } as any),
        professionalIds.length > 0
          ? supabase.from('users').select('id, name, email').in('id', professionalIds).limit(professionalIds.length)
          : Promise.resolve({ data: [], error: null } as any)
      ]);
      if (patientsResult.error) console.warn('[Closure] patient labels unavailable:', patientsResult.error?.message || String(patientsResult.error));
      if (professionalsResult.error) console.warn('[Closure] professional labels unavailable:', professionalsResult.error?.message || String(professionalsResult.error));

      const patientNames = new Map<string, string>((patientsResult.error ? [] : patientsResult.data || []).map((row: any) => [sanitizeString(row.id, 120), sanitizeString(row.name, 180) || 'Paciente']));
      const professionalNames = new Map<string, string>((professionalsResult.error ? [] : professionalsResult.data || []).map((row: any) => [sanitizeString(row.id, 120), sanitizeString(row.name || row.email, 180) || 'Equipe']));
      const totals = {
        ready: totalsRows.filter((row: any) => row.readiness_status === 'READY').length,
        pending: totalsRows.filter((row: any) => row.readiness_status === 'PENDING').length,
        warning: totalsRows.filter((row: any) => row.readiness_status === 'WARNING').length,
        notBillable: totalsRows.filter((row: any) => row.readiness_status === 'NOT_BILLABLE').length,
        draft: totalsRows.filter((row: any) => row.readiness_status === 'DRAFT').length,
        total: totalsRows.length,
        scheduledMinutes: totalsRows.reduce((sum: number, row: any) => sum + (Number(row.scheduled_minutes) || 0), 0),
        actualMinutes: totalsRows.reduce((sum: number, row: any) => sum + (Number(row.actual_minutes) || 0), 0),
        blockingIssues: totalsRows.reduce((sum: number, row: any) => sum + (Number(row.blocking_issues_count) || 0), 0),
        warningIssues: totalsRows.reduce((sum: number, row: any) => sum + (Number(row.warning_issues_count) || 0), 0)
      };
      return res.json({
        success: true,
        data: rows.map((row: any) => normalizeClosureListRow(row, patientNames, professionalNames)),
        page,
        limit,
        totals
      });
    } catch (error: any) {
      console.warn('[Closure] list degraded to empty payload:', error?.message || String(error));
      return res.json(emptyClosurePayload('closure_list_degraded'));
    }
  });

  app.get('/api/closure/appointments/:appointmentId', checkAuth, requireRoles('coordinator', 'therapist', 'admin', 'owner'), async (req: any, res) => {
    try {
      const appointmentId = sanitizeString(req.params.appointmentId, 120);
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      if (!isUuid(appointmentId) || !isUuid(clinicId)) return res.status(400).json(closureSafeError(400));
      const closureResult = await fetchAppointmentClosureCheckRow({
        organizationId: clinicId,
        appointmentId,
        user: req.session.user
      });
      let data = closureResult.data;
      if (!data || closureResult.omittedColumns.size > 0) {
        const generated = await persistAppointmentClosureCheck({ appointmentId, user: req.session.user, force: true });
        if ((generated as any).ok) data = (generated as any).data;
        else if (!data) return res.status((generated as any).status || 404).json(closureSafeError((generated as any).status || 404));
      }
      const patientId = sanitizeString(data?.patient_id, 120);
      const professionalId = sanitizeString(data?.professional_id, 120);
      if (patientId && !(await canAccessPatientInCurrentClinic(patientId, req.session.user))) {
        return res.status(404).json(closureSafeError(404));
      }
      const [patientResult, professionalResult] = await Promise.all([
        isUuid(patientId)
          ? supabase.from('patients').select('id, name').eq('id', patientId).eq('clinic_id', clinicId).maybeSingle()
          : Promise.resolve({ data: null, error: null } as any),
        isUuid(professionalId)
          ? supabase.from('users').select('id, name, email').eq('id', professionalId).maybeSingle()
          : Promise.resolve({ data: null, error: null } as any)
      ]);
      if (patientResult.error && !hasMissingFinancialSchema(patientResult.error)) throw patientResult.error;
      if (professionalResult.error && !hasMissingFinancialSchema(professionalResult.error)) throw professionalResult.error;
      await writeClosureAuditLog({
        organizationId: clinicId,
        appointmentId,
        abaSessionId: data?.aba_session_id || null,
        patientId,
        action: 'VIEWED_DETAIL',
        previousStatus: data?.readiness_status || null,
        newStatus: data?.readiness_status || null,
        performedBy: sanitizeString(req.session.user?.id, 120),
        metadata: { source: 'closure_detail' }
      });
      return res.json({
        success: true,
        data: {
          ...normalizeClosureListRow(
            data,
            new Map([[patientId, sanitizeString(patientResult.data?.name, 180) || 'Paciente']]),
            new Map([[professionalId, sanitizeString(professionalResult.data?.name || professionalResult.data?.email, 180) || 'Equipe']])
          ),
          checklist: Array.isArray(data?.checklist) ? data.checklist : []
        }
      });
    } catch (error: any) {
      console.warn('[Closure] detail failed:', error?.message || String(error));
      return res.status(500).json(closureSafeError(500));
    }
  });

  app.post('/api/closure/appointments/:appointmentId/revalidate', portalActionLimiter, checkAuth, requireRoles('coordinator', 'therapist', 'admin', 'owner'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'Payload de revalidação de fechamento')) return;
      const appointmentId = sanitizeString(req.params.appointmentId, 120);
      if (!isUuid(appointmentId)) return res.status(400).json(closureSafeError(400));
      const generated = await persistAppointmentClosureCheck({ appointmentId, user: req.session.user, force: true });
      if (!generated.ok) return res.status((generated as any).status || 404).json(closureSafeError((generated as any).status || 404));
      return res.json({ success: true, data: (generated as any).data, reused: Boolean((generated as any).reused) });
    } catch (error: any) {
      console.warn('[Closure] revalidate failed:', error?.message || String(error));
      return res.status(500).json(closureSafeError(500));
    }
  });

  app.patch('/api/closure/appointments/:appointmentId/override', portalActionLimiter, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 48 * 1024, 'Payload de override de fechamento')) return;
      const appointmentId = sanitizeString(req.params.appointmentId, 120);
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const reason = sanitizeTextField(req.body?.reason || req.body?.justificativa, 600);
      const requestedStatus = parseClosureStatusFilter(req.body?.readinessStatus || req.body?.readiness_status || req.body?.status);
      if (!isUuid(appointmentId) || !isUuid(clinicId) || !requestedStatus || reason.length < 8) {
        return res.status(400).json(closureSafeError(400));
      }
      const generated = await persistAppointmentClosureCheck({
        appointmentId,
        user: req.session.user,
        force: false,
        manualNotBillable: requestedStatus === 'NOT_BILLABLE'
      });
      if (!generated.ok) return res.status((generated as any).status || 404).json(closureSafeError((generated as any).status || 404));
      const existing = (generated as any).data;
      const previousStatus = sanitizeString(existing?.readiness_status, 40) || null;
      const { data, error } = await supabase
        .from('appointment_closure_checks')
        .update({
          readiness_status: requestedStatus,
          updated_at: new Date().toISOString()
        })
        .eq('organization_id', clinicId)
        .eq('appointment_id', appointmentId)
        .select(APPOINTMENT_CLOSURE_CHECK_SELECT)
        .maybeSingle();
      if (error) throw error;
      await writeClosureAuditLog({
        organizationId: clinicId,
        appointmentId,
        abaSessionId: data?.aba_session_id || existing?.aba_session_id || null,
        patientId: data?.patient_id || existing?.patient_id || null,
        action: requestedStatus === 'NOT_BILLABLE' ? 'MARKED_NOT_BILLABLE' : 'MANUAL_OVERRIDE',
        previousStatus,
        newStatus: requestedStatus,
        performedBy: sanitizeString(req.session.user?.id, 120),
        metadata: {
          reason,
          originalBlockingIssuesCount: Number(existing?.blocking_issues_count || 0),
          originalWarningIssuesCount: Number(existing?.warning_issues_count || 0)
        }
      });
      return res.json({ success: true, data });
    } catch (error: any) {
      console.warn('[Closure] override failed:', error?.message || String(error));
      return res.status(500).json(closureSafeError(500));
    }
  });

  const conferenceSafeError = (status = 500) => ({
    success: false,
    error: status === 400 ? 'Filtros inválidos para a conferência.' : 'Não foi possível carregar a conferência agora.'
  });

  const parseConferenceFilters = (source: any = {}) => {
    const range = parseClosureDateRange(source);
    const pageParams = parseClosurePageParams(source);
    const patientId = sanitizeString(source?.patientId || source?.patient_id, 120);
    const professionalId = sanitizeString(source?.professionalId || source?.professional_id, 120);
    const payerId = sanitizeString(source?.payerId || source?.payer_id, 120);
    const serviceType = sanitizeString(source?.serviceType || source?.service_type, 120);
    const readinessStatus = parseClosureStatusFilter(source?.readinessStatus || source?.readiness_status || source?.status);
    const appointmentStatus = sanitizeString(source?.appointmentStatus || source?.appointment_status, 40).toLowerCase();
    const onlyPending = String(source?.onlyPending || source?.only_pending || '').toLowerCase() === 'true';
    const onlyReady = String(source?.onlyReady || source?.only_ready || '').toLowerCase() === 'true';
    const onlyNotBillable = String(source?.onlyNotBillable || source?.only_not_billable || '').toLowerCase() === 'true';
    const missingKind = sanitizeString(source?.missing || source?.pendingKind || source?.pendencia, 80).toLowerCase();
    const invalidUuid =
      (patientId && !isUuid(patientId)) ||
      (professionalId && !isUuid(professionalId)) ||
      (payerId && !isUuid(payerId));
    const validAppointmentStatuses = ['', 'scheduled', 'pending', 'confirmed', 'completed', 'cancelled', 'canceled', 'no_show', 'missed'];
    return {
      ok: range.ok && !invalidUuid && validAppointmentStatuses.includes(appointmentStatus),
      ...range,
      ...pageParams,
      patientId,
      professionalId,
      payerId,
      serviceType,
      readinessStatus,
      appointmentStatus,
      onlyPending,
      onlyReady,
      onlyNotBillable,
      missingKind
    };
  };

  const applyConferenceFilters = (query: any, filters: any) => {
    let scoped = query;
    if (filters.readinessStatus) scoped = scoped.eq('readiness_status', filters.readinessStatus);
    if (filters.onlyPending) scoped = scoped.eq('readiness_status', 'PENDING');
    if (filters.onlyReady) scoped = scoped.eq('readiness_status', 'READY');
    if (filters.onlyNotBillable) scoped = scoped.eq('readiness_status', 'NOT_BILLABLE');
    if (filters.patientId) scoped = scoped.eq('patient_id', filters.patientId);
    if (filters.professionalId) scoped = scoped.eq('professional_id', filters.professionalId);
    if (filters.payerId) scoped = scoped.eq('payer_id', filters.payerId);
    if (filters.serviceType) scoped = scoped.eq('service_type', filters.serviceType);
    if (filters.appointmentStatus === 'completed') scoped = scoped.gt('actual_minutes', 0);
    if (filters.appointmentStatus === 'scheduled' || filters.appointmentStatus === 'pending') scoped = scoped.is('actual_start', null);
    if (filters.appointmentStatus === 'cancelled' || filters.appointmentStatus === 'canceled') scoped = scoped.eq('readiness_status', 'NOT_BILLABLE');
    if (filters.missingKind === 'signature' || filters.missingKind === 'assinatura') scoped = scoped.contains('main_issues', ['Assinatura pendente para fechamento da sessão.']);
    if (filters.missingKind === 'report' || filters.missingKind === 'relatorio') scoped = scoped.contains('main_issues', ['Relatório da sessão ainda não foi preenchido.']);
    if (filters.missingKind === 'guide' || filters.missingKind === 'guia') scoped = scoped.is('guide_number', null);
    if (filters.missingKind === 'authorization' || filters.missingKind === 'autorizacao') scoped = scoped.is('authorization_code', null);
    if (filters.missingKind === 'documents' || filters.missingKind === 'documentos') scoped = scoped.gt('required_document_pending_count', 0);
    return scoped;
  };

  const hydrateConferenceRows = async (rows: any[], clinicId: string) => {
    const patientIds = Array.from(new Set(rows.map((row: any) => sanitizeString(row.patient_id, 120)).filter((id: string) => isUuid(id))));
    const professionalIds = Array.from(new Set(rows.map((row: any) => sanitizeString(row.professional_id, 120)).filter((id: string) => isUuid(id))));
    const [patientsResult, professionalsResult] = await Promise.all([
      patientIds.length > 0
        ? supabase.from('patients').select('id, name').eq('clinic_id', clinicId).in('id', patientIds).limit(patientIds.length)
        : Promise.resolve({ data: [], error: null } as any),
      professionalIds.length > 0
        ? supabase.from('users').select('id, name, email').in('id', professionalIds).limit(professionalIds.length)
        : Promise.resolve({ data: [], error: null } as any)
    ]);
    if (patientsResult.error && !hasMissingFinancialSchema(patientsResult.error)) throw patientsResult.error;
    if (professionalsResult.error && !hasMissingFinancialSchema(professionalsResult.error)) throw professionalsResult.error;
    const patientNames = new Map<string, string>((patientsResult.data || []).map((row: any) => [sanitizeString(row.id, 120), sanitizeString(row.name, 180) || 'Paciente']));
    const professionalNames = new Map<string, string>((professionalsResult.data || []).map((row: any) => [sanitizeString(row.id, 120), sanitizeString(row.name || row.email, 180) || 'Equipe']));
    return rows.map((row: any) => normalizeClosureListRow(row, patientNames, professionalNames));
  };

  const loadConferenceClosureRows = async (params: {
    clinicId: string;
    user: any;
    filters: any;
    paginated?: boolean;
    hardLimit?: number;
  }) => {
    const limit = Math.min(Math.max(Number(params.hardLimit || params.filters.limit || 50), 1), 2000);
    let query = supabase
      .from('appointment_closure_checks')
      .select(APPOINTMENT_CLOSURE_LIST_SELECT)
      .eq('organization_id', params.clinicId)
      .gte('scheduled_start', params.filters.fromIso)
      .lte('scheduled_start', params.filters.toIso)
      .order('scheduled_start', { ascending: true });
    query = applyConferenceFilters(query, params.filters);
    query = params.paginated ? query.range(params.filters.from, params.filters.to) : query.limit(limit);
    query = await applyClosureTenantScope(query, params.user, params.clinicId);
    const { data, error } = await query;
    if (error) {
      if (hasMissingFinancialSchema(error)) return [];
      throw error;
    }
    return Array.isArray(data) ? data : [];
  };

  const writeConferenceExportAudit = async (params: {
    organizationId: string;
    exportType: string;
    filters: any;
    generatedBy?: string | null;
    rowCount: number;
    status: 'GENERATED' | 'FAILED';
    metadata?: Record<string, any>;
  }) => {
    if (!isUuid(params.organizationId)) return;
    const payload = cleanObject({
      id: crypto.randomUUID(),
      organization_id: params.organizationId,
      export_type: sanitizeString(params.exportType, 80) || 'sessions',
      filters: sanitizeClinicalPayload(params.filters || {}),
      generated_by: isUuid(sanitizeString(params.generatedBy, 120)) ? sanitizeString(params.generatedBy, 120) : null,
      generated_at: new Date().toISOString(),
      row_count: Math.max(0, Math.round(Number(params.rowCount || 0))),
      status: params.status,
      metadata: sanitizeClinicalPayload(params.metadata || {})
    });
    const { error } = await supabase.from('operational_closure_exports').insert([payload]);
    if (error && !hasMissingFinancialSchema(error)) {
      console.warn('[MonthlyConference] export audit failed:', error?.message || String(error));
    }
    await writeClosureAuditLog({
      organizationId: params.organizationId,
      action: params.status === 'GENERATED' ? 'EXPORT_GENERATED' : 'EXPORT_FAILED',
      performedBy: params.generatedBy || null,
      metadata: {
        exportType: payload.export_type,
        rowCount: payload.row_count,
        filters: payload.filters
      }
    });
  };

  const assertConferenceFilterOwnership = async (filters: any, clinicId: string) => {
    if (filters.patientId) {
      const { data, error } = await supabase
        .from('patients')
        .select('id')
        .eq('id', filters.patientId)
        .eq('clinic_id', clinicId)
        .eq('is_active', true)
        .is('deleted_at', null)
        .limit(1)
        .maybeSingle();
      if (error && !hasMissingFinancialSchema(error)) throw error;
      if (!data?.id) return false;
    }
    if (filters.payerId) {
      const payer = await fetchPayerForAdmin(filters.payerId, clinicId);
      if (!payer) return false;
    }
    if (filters.professionalId) {
      const { data, error } = await supabase
        .from('users')
        .select('id, clinic_id')
        .eq('id', filters.professionalId)
        .limit(1)
        .maybeSingle();
      if (error && !hasMissingFinancialSchema(error)) throw error;
      if (!data?.id || sanitizeString(data?.clinic_id, 120) !== clinicId) return false;
    }
    return true;
  };

  app.get('/api/conference/monthly', checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const filters = parseConferenceFilters(req.query);
      if (!isUuid(clinicId) || !filters.ok) return res.status(400).json(conferenceSafeError(400));
      if (!(await assertConferenceFilterOwnership(filters, clinicId))) return res.status(404).json(conferenceSafeError(404));
      const [pageRows, aggregateRows] = await Promise.all([
        loadConferenceClosureRows({ clinicId, user: req.session.user, filters, paginated: true }),
        loadConferenceClosureRows({ clinicId, user: req.session.user, filters, hardLimit: 2000 })
      ]);
      const hydratedPageRows = await hydrateConferenceRows(pageRows, clinicId);
      const hydratedAggregateRows = await hydrateConferenceRows(aggregateRows, clinicId);
      const summary = buildMonthlyConferenceSummary(hydratedAggregateRows);
      await writeClosureAuditLog({
        organizationId: clinicId,
        action: 'CONFERENCE_VIEWED',
        performedBy: sanitizeString(req.session.user?.id, 120),
        metadata: { from: filters.fromIso, to: filters.toIso, page: filters.page, limit: filters.limit }
      });
      return res.json({
        success: true,
        data: hydratedPageRows,
        rows: hydratedPageRows,
        kpis: summary.kpis,
        pendingByType: summary.pendingByType,
        page: filters.page,
        limit: filters.limit,
        filters: {
          from: filters.fromIso,
          to: filters.toIso,
          patientId: filters.patientId || null,
          professionalId: filters.professionalId || null,
          payerId: filters.payerId || null,
          serviceType: filters.serviceType || null,
          readinessStatus: filters.readinessStatus || null
        }
      });
    } catch (error: any) {
      console.warn('[MonthlyConference] list failed:', error?.message || String(error));
      return res.status(500).json(conferenceSafeError(500));
    }
  });

  const handleConferenceSummary = (summaryKey: 'byPatient' | 'byProfessional' | 'byPayer' | 'byServiceType') => async (req: any, res: any) => {
    try {
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const filters = parseConferenceFilters(req.query);
      if (!isUuid(clinicId) || !filters.ok) return res.status(400).json(conferenceSafeError(400));
      if (!(await assertConferenceFilterOwnership(filters, clinicId))) return res.status(404).json(conferenceSafeError(404));
      const rows = await loadConferenceClosureRows({ clinicId, user: req.session.user, filters, hardLimit: 2000 });
      const hydratedRows = await hydrateConferenceRows(rows, clinicId);
      const summary = buildMonthlyConferenceSummary(hydratedRows);
      return res.json({ success: true, data: (summary as any)[summaryKey] || [], kpis: summary.kpis });
    } catch (error: any) {
      console.warn('[MonthlyConference] summary failed:', error?.message || String(error));
      return res.status(500).json(conferenceSafeError(500));
    }
  };

  app.get('/api/conference/monthly/summary-by-patient', checkAuth, requireRoles('coordinator', 'admin', 'owner'), handleConferenceSummary('byPatient'));
  app.get('/api/conference/monthly/summary-by-professional', checkAuth, requireRoles('coordinator', 'admin', 'owner'), handleConferenceSummary('byProfessional'));
  app.get('/api/conference/monthly/summary-by-payer', checkAuth, requireRoles('coordinator', 'admin', 'owner'), handleConferenceSummary('byPayer'));
  app.get('/api/conference/monthly/summary-by-service-type', checkAuth, requireRoles('coordinator', 'admin', 'owner'), handleConferenceSummary('byServiceType'));

  app.get('/api/conference/monthly/session/:appointmentId', checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      const appointmentId = sanitizeString(req.params.appointmentId, 120);
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      if (!isUuid(appointmentId) || !isUuid(clinicId)) return res.status(400).json(conferenceSafeError(400));
      let query = supabase
        .from('appointment_closure_checks')
        .select(APPOINTMENT_CLOSURE_CHECK_SELECT)
        .eq('organization_id', clinicId)
        .eq('appointment_id', appointmentId)
        .limit(1);
      query = await applyClosureTenantScope(query, req.session.user, clinicId);
      const { data, error } = await query.maybeSingle();
      if (error) {
        if (hasMissingFinancialSchema(error)) return res.status(404).json(conferenceSafeError(404));
        throw error;
      }
      if (!data?.appointment_id) return res.status(404).json(conferenceSafeError(404));
      const hydrated = await hydrateConferenceRows([data], clinicId);
      await writeClosureAuditLog({
        organizationId: clinicId,
        appointmentId,
        abaSessionId: data?.aba_session_id || null,
        patientId: data?.patient_id || null,
        action: 'SESSION_DETAIL_VIEWED',
        previousStatus: data?.readiness_status || null,
        newStatus: data?.readiness_status || null,
        performedBy: sanitizeString(req.session.user?.id, 120),
        metadata: { source: 'monthly_conference' }
      });
      return res.json({
        success: true,
        data: {
          ...(hydrated[0] || {}),
          checklist: Array.isArray(data?.checklist) ? data.checklist : [],
          payerRules: {
            payerName: sanitizeString(data?.payer_name_snapshot, 180) || null,
            source: sanitizeString(data?.payer_requirement_source, 40) || null,
            guideNumber: sanitizeString(data?.guide_number, 120) || null,
            authorizationCode: sanitizeString(data?.authorization_code, 120) || null,
            pendingDocuments: Number(data?.required_document_pending_count || 0)
          },
          audit: {
            generatedAt: data?.generated_at || null,
            updatedAt: data?.updated_at || null
          }
        }
      });
    } catch (error: any) {
      console.warn('[MonthlyConference] detail failed:', error?.message || String(error));
      return res.status(500).json(conferenceSafeError(500));
    }
  });

  app.post('/api/conference/monthly/session/:appointmentId/revalidate', portalActionLimiter, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'Payload de revalidação da conferência')) return;
      const appointmentId = sanitizeString(req.params.appointmentId, 120);
      if (!isUuid(appointmentId)) return res.status(400).json(conferenceSafeError(400));
      const generated = await persistAppointmentClosureCheck({ appointmentId, user: req.session.user, force: true });
      if (!generated.ok) return res.status((generated as any).status || 404).json(conferenceSafeError((generated as any).status || 404));
      await writeClosureAuditLog({
        organizationId: sanitizeString(currentClinicId(req.session.user), 120),
        appointmentId,
        action: 'REVALIDATED_FROM_CONFERENCE',
        performedBy: sanitizeString(req.session.user?.id, 120),
        metadata: { source: 'monthly_conference' }
      });
      return res.json({ success: true, data: (generated as any).data });
    } catch (error: any) {
      console.warn('[MonthlyConference] revalidate failed:', error?.message || String(error));
      return res.status(500).json(conferenceSafeError(500));
    }
  });

  app.post('/api/conference/monthly/export', portalActionLimiter, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
    try {
      if (!enforcePayloadLimit(req, res, 64 * 1024, 'Payload de exportação da conferência')) return;
      const exportType = sanitizeString(req.body?.exportType || req.body?.export_type || 'sessions', 80);
      const filters = parseConferenceFilters(req.body?.filters || req.body || {});
      if (!isUuid(clinicId) || !filters.ok) return res.status(400).json(conferenceSafeError(400));
      if (!(await assertConferenceFilterOwnership(filters, clinicId))) return res.status(404).json(conferenceSafeError(404));
      const requestedFields = Array.isArray(req.body?.fields) ? req.body.fields.map((field: any) => sanitizeString(field, 80)) : [];
      const rows = await loadConferenceClosureRows({ clinicId, user: req.session.user, filters, hardLimit: 2000 });
      const hydratedRows = await hydrateConferenceRows(rows, clinicId);
      const summary = buildMonthlyConferenceSummary(hydratedRows);
      const sessionRows = buildMonthlyConferenceExportRows(hydratedRows);
      let exportRows: any[] = sessionRows;
      let defaultFields: string[] = ['scheduledDate', 'patientName', 'professionalName', 'serviceType', 'payerName', 'scheduledMinutes', 'actualMinutes', 'readinessStatus', 'pendingKinds'];
      if (exportType === 'pending') {
        exportRows = sessionRows.filter((row: any) => String(row.pendingKinds || '').trim());
      } else if (exportType === 'time_by_patient') {
        exportRows = summary.byPatient.map((row: any) => ({ name: row.name, totalSessions: row.totalSessions, realizedSessions: row.realizedSessions, scheduledMinutes: row.scheduledMinutes, actualMinutes: row.actualMinutes, pendingSignatures: row.pendingSignatures, pendingReports: row.pendingReports }));
        defaultFields = ['name', 'totalSessions', 'realizedSessions', 'scheduledMinutes', 'actualMinutes', 'pendingSignatures', 'pendingReports'];
      } else if (exportType === 'time_by_professional') {
        exportRows = summary.byProfessional.map((row: any) => ({ name: row.name, workedDaysCount: row.workedDaysCount, totalSessions: row.totalSessions, realizedSessions: row.realizedSessions, scheduledMinutes: row.scheduledMinutes, actualMinutes: row.actualMinutes, pendingReports: row.pendingReports }));
        defaultFields = ['name', 'workedDaysCount', 'totalSessions', 'realizedSessions', 'scheduledMinutes', 'actualMinutes', 'pendingReports'];
      } else if (exportType === 'time_by_payer') {
        exportRows = summary.byPayer.map((row: any) => ({ payerName: row.payerName, totalSessions: row.totalSessions, ready: row.ready, pending: row.pending, pendingGuides: row.pendingGuides, pendingAuthorizations: row.pendingAuthorizations, pendingSignatures: row.pendingSignatures, pendingReports: row.pendingReports }));
        defaultFields = ['payerName', 'totalSessions', 'ready', 'pending', 'pendingGuides', 'pendingAuthorizations', 'pendingSignatures', 'pendingReports'];
      }
      const fields = (requestedFields.length > 0 ? requestedFields : defaultFields)
        .filter((field: string) => (MONTHLY_CONFERENCE_EXPORT_FIELDS as readonly string[]).includes(field));
      const csv = rowsToCsv(exportRows, fields.length > 0 ? fields : defaultFields);
      await writeConferenceExportAudit({
        organizationId: clinicId,
        exportType,
        filters,
        generatedBy: sanitizeString(req.session.user?.id, 120),
        rowCount: exportRows.length,
        status: 'GENERATED',
        metadata: { fieldCount: fields.length }
      });
      return res.json({
        success: true,
        fileName: `conferencia-mensal-${new Date().toISOString().slice(0, 10)}.csv`,
        contentType: 'text/csv; charset=utf-8',
        rowCount: exportRows.length,
        csv
      });
    } catch (error: any) {
      console.warn('[MonthlyConference] export failed:', error?.message || String(error));
      await writeConferenceExportAudit({
        organizationId: clinicId,
        exportType: sanitizeString(req.body?.exportType || req.body?.export_type || 'sessions', 80),
        filters: req.body?.filters || {},
        generatedBy: sanitizeString(req.session?.user?.id, 120),
        rowCount: 0,
        status: 'FAILED'
      });
      return res.status(500).json(conferenceSafeError(500));
    }
  });

  const fetchFutureAppointmentsForMaintenance = async (params: {
    patientId: string;
    clinicId: string;
    organizationId?: string;
    fromIso?: string;
    toIso?: string;
    limit?: number;
  }) => {
    const limit = Math.min(50, Math.max(1, Math.round(Number(params.limit || 20) || 20)));
    const mergeMaintenanceAppointments = (rows: any[]) => {
      const byId = new Map<string, any>();
      for (const row of rows) {
        const id = sanitizeString(row?.id || row?.appointment_id || row?.appointmentId, 180);
        if (!id) continue;
        if (!byId.has(id)) byId.set(id, row);
      }
      return Array.from(byId.values())
        .sort((a: any, b: any) => new Date(a?.scheduled_at || 0).getTime() - new Date(b?.scheduled_at || 0).getTime())
        .slice(0, limit);
    };
    const fetchStateFallback = async () => {
      const stateResult = await fetchClinicStateWithSchemaFallback({ supabase, clinicId: params.clinicId, logger: console });
      if (stateResult.error) {
        if (hasMissingFinancialSchema(stateResult.error)) return [];
        throw stateResult.error;
      }
      const fromMs = new Date(sanitizeIsoDateTime(params.fromIso || new Date().toISOString())).getTime();
      const toMs = params.toIso ? new Date(sanitizeIsoDateTime(params.toIso)).getTime() : Number.POSITIVE_INFINITY;
      return (Array.isArray(stateResult.data?.appointments) ? stateResult.data.appointments : [])
        .map((appointment: any) => {
          const scheduledAt = buildAppointmentScheduledAt(appointment);
          const patientId = sanitizeString(appointment?.patient_id || appointment?.patientId, 120);
          return cleanObject({
            id: sanitizeString(appointment?.id, 180),
            organization_id: sanitizeString(appointment?.organization_id || appointment?.organizationId || params.organizationId || params.clinicId, 120),
            clinic_id: params.clinicId,
            patient_id: patientId,
            therapist_id: sanitizeString(appointment?.therapist_id || appointment?.therapistId || appointment?.professional_id || appointment?.professionalId, 120) || null,
            therapist_name: sanitizeString(appointment?.therapist_name || appointment?.therapistName || appointment?.professionalName || appointment?.professional, 180) || null,
            scheduled_at: scheduledAt,
            scheduled_start_at: scheduledAt,
            scheduled_duration_minutes: getClinicStateAppointmentDurationMinutes(appointment),
            service_type: sanitizeString(appointment?.service_type || appointment?.serviceType || appointment?.type || appointment?.approach, 120) || null,
            approach: sanitizeString(appointment?.approach || appointment?.type || appointment?.service_type || appointment?.serviceType, 120) || null,
            room_id: sanitizeString(appointment?.room_id || appointment?.roomId || appointment?.room, 180) || null,
            room_name: sanitizeString(appointment?.room_name || appointment?.roomName || appointment?.roomDisplayName, 180) || null,
            location_type: sanitizeString(appointment?.location_type || appointment?.locationType || appointment?.location, 120) || null,
            status: normalizeAppointmentStatusForTable(appointment?.status),
            source: 'clinic_state'
          });
        })
        .filter((appointment: any) => {
          if (!appointment.id || !appointment.scheduled_at) return false;
          if (appointment.patient_id !== params.patientId) return false;
          if (!getClinicStateAppointmentStatusBlocksConflict(appointment)) return false;
          const scheduledMs = new Date(appointment.scheduled_at).getTime();
          return Number.isFinite(scheduledMs) && scheduledMs >= fromMs && scheduledMs <= toMs;
        })
        .sort((a: any, b: any) => new Date(a.scheduled_at).getTime() - new Date(b.scheduled_at).getTime())
        .slice(0, limit);
    };
    let columns = [...ABA_APPOINTMENT_MAINTENANCE_COLUMNS];
    for (let attempt = 0; attempt < ABA_APPOINTMENT_MAINTENANCE_COLUMNS.length; attempt += 1) {
      let query = supabase
        .from('appointments')
        .select(columns.join(',') || ABA_APPOINTMENT_MAINTENANCE_SELECT)
        .eq('patient_id', params.patientId)
        .gte('scheduled_at', sanitizeIsoDateTime(params.fromIso || new Date().toISOString()))
        .eq('is_active', true)
        .is('deleted_at', null)
        .not('status', 'in', '("cancelled","canceled","deleted")')
        .order('scheduled_at', { ascending: true })
        .limit(limit);
      if (params.organizationId && isUuid(params.organizationId) && columns.includes('organization_id')) query = query.eq('organization_id', params.organizationId);
      if (params.clinicId) query = query.eq('clinic_id', params.clinicId);
      if (params.toIso) query = query.lte('scheduled_at', sanitizeIsoDateTime(params.toIso));
      const result = await query;
      if (!result.error) {
        const stateAppointments = await fetchStateFallback();
        const appointments = mergeMaintenanceAppointments([...(result.data || []), ...stateAppointments]);
        logAbaPlanningEgress({ helper: 'fetchFutureAppointmentsForMaintenance', table: 'appointments,clinic_state', limit, rows: appointments.length });
        return appointments;
      }
      const missingColumn = extractMissingColumnName(result.error);
      if (missingColumn && columns.includes(missingColumn)) {
        columns = columns.filter((column) => column !== missingColumn);
        continue;
      }
      if (hasMissingFinancialSchema(result.error)) return fetchStateFallback();
      throw result.error;
    }
    return fetchStateFallback();
  };

  const fetchMaintenanceAppointmentById = async (params: {
    appointmentId: string;
    patientId: string;
    clinicId: string;
    organizationId: string;
  }) => {
    const appointmentId = sanitizeString(params.appointmentId, 180);
    if (!appointmentId) return null;
    if (isUuid(appointmentId)) {
      let query = supabase
        .from('appointments')
        .select(ABA_APPOINTMENT_MAINTENANCE_SELECT)
        .eq('id', appointmentId)
        .eq('patient_id', params.patientId)
        .eq('clinic_id', params.clinicId)
        .limit(1);
      if (isUuid(params.organizationId)) query = query.eq('organization_id', params.organizationId);
      const result = await query.maybeSingle();
      if (!result.error && result.data) return result.data;
      if (result.error) {
        if (hasMissingFinancialSchema(result.error)) return null;
        const missingColumn = extractMissingColumnName(result.error);
        if (missingColumn && ABA_APPOINTMENT_MAINTENANCE_COLUMNS.includes(missingColumn)) {
          const fallback = await supabase
            .from('appointments')
            .select('id,clinic_id,patient_id,therapist_id,scheduled_at,status')
            .eq('id', appointmentId)
            .eq('patient_id', params.patientId)
            .eq('clinic_id', params.clinicId)
            .limit(1)
            .maybeSingle();
          if (!fallback.error && fallback.data) return fallback.data;
          if (fallback.error && !hasMissingFinancialSchema(fallback.error)) throw fallback.error;
        } else {
          throw result.error;
        }
      }
    }
    const stateResult = await fetchClinicStateWithSchemaFallback({ supabase, clinicId: params.clinicId, logger: console });
    if (stateResult.error) {
      if (hasMissingFinancialSchema(stateResult.error)) return null;
      throw stateResult.error;
    }
    const appointment = (Array.isArray(stateResult.data?.appointments) ? stateResult.data.appointments : [])
      .find((item: any) => String(item?.id || '') === appointmentId);
    if (!appointment) return null;
    const scheduledAt = buildAppointmentScheduledAt(appointment);
    const patientId = sanitizeString(appointment?.patient_id || appointment?.patientId, 120);
    if (patientId !== params.patientId || !scheduledAt || !getClinicStateAppointmentStatusBlocksConflict(appointment)) return null;
    return cleanObject({
      id: appointmentId,
      organization_id: sanitizeString(appointment?.organization_id || appointment?.organizationId || params.organizationId || params.clinicId, 120),
      clinic_id: params.clinicId,
      patient_id: params.patientId,
      therapist_id: sanitizeString(appointment?.therapist_id || appointment?.therapistId || appointment?.professional_id || appointment?.professionalId, 120) || null,
      therapist_name: sanitizeString(appointment?.therapist_name || appointment?.therapistName || appointment?.professionalName || appointment?.professional, 180) || null,
      scheduled_at: scheduledAt,
      scheduled_start_at: scheduledAt,
      scheduled_duration_minutes: getClinicStateAppointmentDurationMinutes(appointment),
      service_type: sanitizeString(appointment?.service_type || appointment?.serviceType || appointment?.type || appointment?.approach, 120) || null,
      approach: sanitizeString(appointment?.approach || appointment?.type || appointment?.service_type || appointment?.serviceType, 120) || null,
      room_id: sanitizeString(appointment?.room_id || appointment?.roomId || appointment?.room, 180) || null,
      room_name: sanitizeString(appointment?.room_name || appointment?.roomName || appointment?.roomDisplayName, 180) || null,
      location_type: sanitizeString(appointment?.location_type || appointment?.locationType || appointment?.location, 120) || null,
      status: normalizeAppointmentStatusForTable(appointment?.status),
      source: 'clinic_state'
    });
  };

  const fetchTargetForMaintenance = async (params: {
    targetId: string;
    patientId: string;
    clinicId: string;
    organizationId: string;
  }) => {
    let query = supabase
      .from('aba_targets')
      .select(ABA_TARGET_RECOMMENDATION_SELECT)
      .eq('id', params.targetId)
      .eq('organization_id', params.organizationId)
      .eq('clinic_id', params.clinicId)
      .eq('patient_id', params.patientId)
      .limit(1);
    const result = await query.maybeSingle();
    if (result.error) {
      if (hasMissingFinancialSchema(result.error)) return null;
      throw result.error;
    }
    return result.data || null;
  };

  const isLegacyMaintenanceScheduleConstraintError = (error: any) => {
    const code = sanitizeString(error?.code, 40);
    const message = extractSupabaseErrorMessage(error).toLowerCase();
    return (
      code === '23514' ||
      code === '23502' ||
      message.includes('aba_maintenance_schedules_status_check') ||
      (message.includes('null value') && message.includes('scheduled_for'))
    );
  };

  const buildLegacyMaintenanceScheduleRow = (row: any, now: string) => {
    const scheduledFor = row?.scheduled_for || row?.scheduledFor || row?.target_due_date || row?.targetDueDate || row?.due_date || row?.dueDate || now;
    const targetDueDate = row?.target_due_date || row?.targetDueDate || scheduledFor;
    return cleanObject({
      ...row,
      status: ['COMPLETED', 'MISSED', 'CANCELLED'].includes(sanitizeString(row?.status, 60).toUpperCase())
        ? sanitizeString(row.status, 60).toUpperCase()
        : 'PENDING',
      scheduled_for: scheduledFor,
      due_date: row?.due_date || scheduledFor,
      target_due_date: targetDueDate,
      metadata: sanitizeClinicalPayload({
        ...(row?.metadata && typeof row.metadata === 'object' ? row.metadata : {}),
        legacyScheduleFallback: true,
        originalStatus: row?.status || null
      }),
      raw_payload: sanitizeClinicalPayload({
        ...(row?.raw_payload && typeof row.raw_payload === 'object' ? row.raw_payload : {}),
        legacyScheduleFallback: true,
        originalStatus: row?.status || null,
        humanMessage: 'Agendamento salvo em modo compatível porque o schema de manutenção do banco ainda está defasado.'
      })
    });
  };

  const saveMaintenanceScheduleRowWithLegacyFallback = async (row: any, now: string) => {
    const raw = row?.raw_payload && typeof row.raw_payload === 'object' ? row.raw_payload : {};
    const rowId = sanitizeString(row?.id, 180);
    const persistedRow = isUuid(rowId)
      ? row
      : cleanObject({
        ...row,
        id: undefined,
        raw_payload: sanitizeClinicalPayload({
          ...raw,
          clientGeneratedId: rowId || null,
          noAutomaticClinicalMutation: true
        })
      });
    const firstResult = await writeAbaRowWithSchemaFallback('aba_maintenance_schedules', persistedRow, 'upsert');
    if (!firstResult.error) return { ...firstResult, row: persistedRow };
    if (!isLegacyMaintenanceScheduleConstraintError(firstResult.error)) return { ...firstResult, row };
    const legacyRow = buildLegacyMaintenanceScheduleRow(persistedRow, now);
    const retryResult = await writeAbaRowWithSchemaFallback('aba_maintenance_schedules', legacyRow, 'upsert');
    return { ...retryResult, row: retryResult.error ? persistedRow : legacyRow };
  };

  const createMaintenanceScheduleForTarget = async (params: {
    targetId: string;
    patientId: string;
    organizationId: string;
    clinicId: string;
    scheduleMode?: unknown;
    dueDate?: unknown;
    appointmentId?: unknown;
    intervals?: unknown;
    createdBy?: string;
    masteryEvaluationId?: string | null;
    approvedAt?: unknown;
  }) => {
    const targetId = sanitizeString(params.targetId, 180);
    const patientId = sanitizeString(params.patientId, 120);
    const clinicId = sanitizeString(params.clinicId, 120);
    const organizationId = sanitizeString(params.organizationId || clinicId, 120);
    const scheduleMode = normalizeAbaMaintenanceScheduleMode(params.scheduleMode);
    const createdBy = sanitizeString(params.createdBy, 120) || null;
    if (!isUuid(targetId)) {
      return { ok: false, status: 400, error: 'Habilidade inválida para agendamento de manutenção.' };
    }
    if (!isUuid(patientId) || !clinicId) {
      return { ok: false, status: 400, error: 'Dados insuficientes para agendar a sondagem.' };
    }

    const now = new Date().toISOString();
    const target = await fetchTargetForMaintenance({ targetId, patientId, clinicId, organizationId });
    if (!target?.id) {
      return { ok: false, status: 404, error: 'Habilidade não encontrada.' };
    }
    const masteryEvaluationId = sanitizeString(params.masteryEvaluationId, 180) || `manual-${targetId}`;
    const rows: any[] = [];

    if (scheduleMode === 'DEFAULT_SEQUENCE') {
      let existingSequenceQuery = supabase
        .from('aba_maintenance_schedules')
        .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
        .eq('organization_id', organizationId)
        .eq('patient_id', patientId)
        .eq('target_id', targetId)
        .in('status', [...ABA_ACTIVE_MAINTENANCE_SCHEDULE_STATUSES, 'COMPLETED'])
        .order('target_due_date', { ascending: true })
        .limit(10);
      existingSequenceQuery = applyAbaTenantScope(existingSequenceQuery, { role: 'owner' }, clinicId, organizationId);
      const existingSequenceResult = await existingSequenceQuery;
      if (existingSequenceResult.error && !hasMissingFinancialSchema(existingSequenceResult.error)) throw existingSequenceResult.error;
      const existingSequenceRows = (existingSequenceResult.data || []).filter((item: any) => isUuid(sanitizeString(item?.id, 180)));
      if (existingSequenceRows.length > 0) {
        const enrichedRows = await enrichMaintenanceRowsWithTargetDisplay(existingSequenceRows, clinicId, organizationId, { role: 'owner' });
        return { ok: true, status: 200, data: enrichedRows };
      }
    }

    if (scheduleMode === 'NEXT_PATIENT_SESSION' || scheduleMode === 'NEXT_AVAILABLE_SESSION') {
      let existingQuery = supabase
        .from('aba_maintenance_schedules')
        .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
        .eq('organization_id', organizationId)
        .eq('patient_id', patientId)
        .eq('target_id', targetId)
        .in('status', ABA_ACTIVE_MAINTENANCE_SCHEDULE_STATUSES)
        .order('target_due_date', { ascending: true })
        .limit(1);
      existingQuery = applyAbaTenantScope(existingQuery, { role: 'owner' }, clinicId, organizationId);
      const existingResult = await existingQuery;
      if (existingResult.error && !hasMissingFinancialSchema(existingResult.error)) throw existingResult.error;
      const existingSchedule = Array.isArray(existingResult.data)
        ? existingResult.data.find((item: any) => isUuid(sanitizeString(item?.id, 180)))
        : null;
      if (existingSchedule?.id) {
        const raw = existingSchedule.raw_payload && typeof existingSchedule.raw_payload === 'object' ? existingSchedule.raw_payload : {};
        const update = await updateAbaScheduleWithSchemaFallback(
          sanitizeString(existingSchedule.id, 180),
          cleanObject({
            status: 'PENDING_NEXT_SESSION',
            appointment_id: null,
            candidate_appointment_id: null,
            scheduled_for: null,
            due_date: null,
            metadata: sanitizeClinicalPayload({
              ...(existingSchedule.metadata && typeof existingSchedule.metadata === 'object' ? existingSchedule.metadata : {}),
              auditAction: 'MAINTENANCE_SCHEDULE_UPDATED',
              legacyAction: 'MAINTENANCE_NEXT_SESSION_SET',
              nextSessionPolicy: true,
              scheduleReason: 'NEXT_SESSION_REUSED'
            }),
            raw_payload: sanitizeClinicalPayload({
              ...raw,
              targetName: target?.name || raw.targetName || null,
              scheduledForNextSession: true,
              noAutomaticClinicalMutation: true
            }),
            updated_at: now
          }),
          clinicId,
          organizationId,
          patientId
        );
        if (update.error) throw update.error;
        void persistActivityLog({
          userId: createdBy || '',
          clinicId,
          actorName: 'Equipe',
          title: 'Sondagem aguardando proxima sessao',
          content: 'Maintenance Schedule existente foi colocado para aguardar a proxima sessao.',
          type: 'clinical',
          actionType: 'MAINTENANCE_SCHEDULE_UPDATED',
          payload: { scheduleId: existingSchedule.id, targetId, patientId }
        });
        const [enrichedSchedule] = await enrichMaintenanceRowsWithTargetDisplay(
          [{
            ...existingSchedule,
            status: 'PENDING_NEXT_SESSION',
            appointment_id: null,
            candidate_appointment_id: null,
            scheduled_for: null,
            due_date: null,
            updated_at: now
          }],
          clinicId,
          organizationId,
          { role: 'owner' }
        );
        return { ok: true, status: 200, data: [enrichedSchedule || existingSchedule] };
      }
    }

    if (scheduleMode === 'CUSTOM_DATE') {
      const appointmentId = sanitizeString(params.appointmentId, 180) || null;
      const dueDate = sanitizeIsoDateTime(params.dueDate || now);
      const appointment = appointmentId
        ? await fetchMaintenanceAppointmentById({ appointmentId, patientId, clinicId, organizationId })
        : null;
      if (appointmentId && !appointment?.id) {
        return { ok: false, status: 400, error: 'A sessao sugerida nao pertence a este paciente.' };
      }
      const scheduledFor = appointment?.scheduled_at || null;
      let existingQuery = supabase
        .from('aba_maintenance_schedules')
        .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
        .eq('organization_id', organizationId)
        .eq('patient_id', patientId)
        .eq('target_id', targetId)
        .in('status', ABA_ACTIVE_MAINTENANCE_SCHEDULE_STATUSES)
        .order('target_due_date', { ascending: true })
        .limit(1);
      existingQuery = applyAbaTenantScope(existingQuery, { role: 'owner' }, clinicId, organizationId);
      const existingResult = await existingQuery;
      if (existingResult.error && !hasMissingFinancialSchema(existingResult.error)) throw existingResult.error;
      const existingSchedule = Array.isArray(existingResult.data)
        ? existingResult.data.find((item: any) => isUuid(sanitizeString(item?.id, 180)))
        : null;
      if (existingSchedule?.id) {
        const raw = existingSchedule.raw_payload && typeof existingSchedule.raw_payload === 'object' ? existingSchedule.raw_payload : {};
        const update = await updateAbaScheduleWithSchemaFallback(
          sanitizeString(existingSchedule.id, 180),
          cleanObject({
            status: 'SCHEDULED',
            appointment_id: appointmentId,
            candidate_appointment_id: null,
            due_date: scheduledFor || dueDate,
            target_due_date: dueDate,
            scheduled_for: scheduledFor,
            schedule_mode: 'CUSTOM_DATE',
            metadata: sanitizeClinicalPayload({
              ...(existingSchedule.metadata && typeof existingSchedule.metadata === 'object' ? existingSchedule.metadata : {}),
              auditAction: 'MAINTENANCE_SCHEDULE_UPDATED',
              scheduleReason: appointmentId ? 'CUSTOM_DATE_LINKED_UPDATED' : 'CUSTOM_DATE_UPDATED'
            }),
            raw_payload: sanitizeClinicalPayload({
              ...raw,
              targetName: target?.name || raw.targetName || null,
              noAutomaticClinicalMutation: true
            }),
            updated_at: now
          }),
          clinicId,
          organizationId,
          patientId
        );
        if (update.error) throw update.error;
        void persistActivityLog({
          userId: createdBy || '',
          clinicId,
          actorName: 'Equipe',
          title: 'Sondagem de manutencao atualizada',
          content: 'Maintenance Schedule existente foi atualizado para a data escolhida.',
          type: 'clinical',
          actionType: 'MAINTENANCE_SCHEDULE_UPDATED',
          payload: { scheduleId: existingSchedule.id, targetId, patientId, dueDate }
        });
        const [enrichedSchedule] = await enrichMaintenanceRowsWithTargetDisplay(
          [{
            ...existingSchedule,
            status: 'SCHEDULED',
            appointment_id: appointmentId,
            candidate_appointment_id: null,
            due_date: scheduledFor || dueDate,
            target_due_date: dueDate,
            scheduled_for: scheduledFor,
            schedule_mode: 'CUSTOM_DATE',
            updated_at: now
          }],
          clinicId,
          organizationId,
          { role: 'owner' }
        );
        return { ok: true, status: 200, data: [enrichedSchedule || existingSchedule] };
      }
    }

    if (scheduleMode === 'DEFAULT_SEQUENCE') {
      const intervals = normalizeMaintenanceDayList(params.intervals);
      const approvedAt = sanitizeIsoDateTime(params.approvedAt || now);
      const maxDay = Math.max(...intervals, 60);
      const lookupEnd = new Date(approvedAt);
      lookupEnd.setUTCDate(lookupEnd.getUTCDate() + maxDay + 14);
      const appointments = await fetchFutureAppointmentsForMaintenance({
        patientId,
        clinicId,
        organizationId,
        fromIso: approvedAt,
        toIso: lookupEnd.toISOString(),
        limit: Math.min(50, intervals.length * 12)
      });
      const preview = buildDefaultMaintenanceSchedulePreview({
        approvedAt,
        maintenanceDays: intervals,
        appointments
      });
      for (const item of preview) {
        const id = `maintenance-${abaPlanningHash([targetId, masteryEvaluationId, item.scheduleDay, item.targetDueDate])}`;
        rows.push(cleanObject({
          id,
          organization_id: organizationId,
          clinic_id: clinicId,
          patient_id: patientId,
          target_id: targetId,
          mastery_evaluation_id: masteryEvaluationId,
          source_mastery_evaluation_id: masteryEvaluationId,
          schedule_day: item.scheduleDay,
          interval_label: `${item.scheduleDay} dias`,
          due_date: item.scheduledFor || item.targetDueDate,
          target_due_date: item.targetDueDate,
          scheduled_for: item.scheduledFor,
          appointment_id: item.appointmentId,
          schedule_mode: 'DEFAULT_SEQUENCE',
          sequence_index: intervals.indexOf(item.scheduleDay) + 1,
          window_start: item.toleranceStart,
          window_end: item.toleranceEnd,
          status: item.status,
          created_by: createdBy,
          metadata: sanitizeClinicalPayload({
            auditAction: 'MAINTENANCE_SCHEDULE_CREATED',
            scheduleReason: 'PLAN_7_14_30_60',
            matchStatus: item.status
          }),
          raw_payload: sanitizeClinicalPayload({
            targetName: target?.name || null,
            previewMessage: item.message,
            maxAppointmentLookupDay: maxDay,
            noAutomaticClinicalMutation: true
          }),
          created_at: now,
          updated_at: now
        }));
      }
    } else if (scheduleMode === 'NEXT_PATIENT_SESSION' || scheduleMode === 'NEXT_AVAILABLE_SESSION') {
      rows.push(cleanObject({
        id: `maintenance-${abaPlanningHash([targetId, 'next-session-pending', patientId])}`,
        organization_id: organizationId,
        clinic_id: clinicId,
        patient_id: patientId,
        target_id: targetId,
        mastery_evaluation_id: masteryEvaluationId,
        source_mastery_evaluation_id: masteryEvaluationId,
        schedule_day: 1,
        interval_label: 'Proxima sessao',
        due_date: null,
        target_due_date: null,
        scheduled_for: null,
        appointment_id: null,
        candidate_appointment_id: null,
        schedule_mode: scheduleMode,
        sequence_index: 1,
        status: 'PENDING_NEXT_SESSION',
        created_by: createdBy,
        metadata: sanitizeClinicalPayload({
          auditAction: 'MAINTENANCE_SCHEDULE_CREATED',
          legacyAction: 'MAINTENANCE_NEXT_SESSION_SET',
          nextSessionPolicy: true,
          scheduleReason: 'NEXT_SESSION_WITHOUT_APPOINTMENT'
        }),
        raw_payload: sanitizeClinicalPayload({
          targetName: target?.name || null,
          scheduledForNextSession: true,
          nextSessionPolicy: true,
          humanMessage: 'A sondagem ficou aguardando a proxima sessao e sera sugerida quando uma consulta real estiver disponivel.',
          noAutomaticClinicalMutation: true
        }),
        created_at: now,
        updated_at: now
      }));
    } else {
      const dueDate = sanitizeIsoDateTime(params.dueDate || now);
      const appointmentId = sanitizeString(params.appointmentId, 180) || null;
      const appointment = appointmentId
        ? await fetchMaintenanceAppointmentById({ appointmentId, patientId, clinicId, organizationId })
        : null;
      if (appointmentId && !appointment?.id) {
        return { ok: false, status: 400, error: 'A sessao sugerida nao pertence a este paciente.' };
      }
      const scheduledFor = appointment?.scheduled_at || null;
      rows.push(cleanObject({
        id: `maintenance-${abaPlanningHash([targetId, 'custom', dueDate, appointmentId || 'date'])}`,
        organization_id: organizationId,
        clinic_id: clinicId,
        patient_id: patientId,
        target_id: targetId,
        mastery_evaluation_id: masteryEvaluationId,
        source_mastery_evaluation_id: masteryEvaluationId,
        schedule_day: Math.max(1, Math.ceil((new Date(dueDate).getTime() - new Date(now).getTime()) / 86_400_000)),
        interval_label: 'Data personalizada',
        due_date: scheduledFor || dueDate,
        target_due_date: dueDate,
        scheduled_for: scheduledFor,
        appointment_id: appointmentId,
        schedule_mode: 'CUSTOM_DATE',
        sequence_index: 1,
        status: 'SCHEDULED',
        created_by: createdBy,
        metadata: sanitizeClinicalPayload({
          auditAction: 'MAINTENANCE_SCHEDULE_CREATED',
          scheduleReason: appointmentId ? 'CUSTOM_DATE_LINKED' : 'CUSTOM_DATE_BY_DATE'
        }),
        raw_payload: sanitizeClinicalPayload({
          targetName: target?.name || null,
          noAutomaticClinicalMutation: true
        }),
        created_at: now,
        updated_at: now
      }));
    }

    const saved: any[] = [];
    for (const row of rows) {
      const result = await saveMaintenanceScheduleRowWithLegacyFallback(row, now);
      if (result.error) return { ok: false, status: hasMissingFinancialSchema(result.error) ? 503 : 500, error: 'Não foi possível salvar o agendamento agora.' };
      const savedRow = cleanObject({
        ...(result.row || row),
        id: (result.data as any)?.id || (isUuid((result.row as any)?.id) ? (result.row as any).id : null),
        persisted: Boolean((result.data as any)?.id || isUuid((result.row as any)?.id))
      });
      saved.push(savedRow);
      const isNextSessionSchedule = scheduleMode === 'NEXT_PATIENT_SESSION' || scheduleMode === 'NEXT_AVAILABLE_SESSION';
      const actionType = 'MAINTENANCE_SCHEDULE_CREATED';
      void persistActivityLog({
        userId: createdBy || '',
        clinicId,
        actorName: 'Equipe',
        title: isNextSessionSchedule ? 'Sondagem aguardando proxima sessao' : 'Sondagem de manutencao criada',
        content: isNextSessionSchedule
          ? 'Maintenance Schedule foi criado para aguardar a proxima sessao.'
          : 'Maintenance Schedule foi criado para uma habilidade real do PEI.',
        type: 'clinical',
        actionType,
        payload: { scheduleId: savedRow?.id || row?.id, targetId, patientId, scheduleMode }
      });
    }
    logAbaPlanningEgress({ helper: 'createMaintenanceScheduleForTarget', table: 'aba_maintenance_schedules', limit: rows.length, rows: saved.length });
    return { ok: true, status: 200, data: saved };
  };

  const fetchNextMaintenanceProbeForTarget = async (params: {
    targetId: string;
    patientId: string;
    clinicId: string;
    organizationId: string;
  }) => {
    let query = supabase
      .from('aba_maintenance_schedules')
      .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
      .eq('organization_id', params.organizationId)
      .eq('patient_id', params.patientId)
      .eq('target_id', params.targetId)
      .in('status', ABA_ACTIVE_MAINTENANCE_SCHEDULE_STATUSES)
      .order('target_due_date', { ascending: true })
      .limit(10);
    query = applyAbaTenantScope(query, { role: 'owner' }, params.clinicId, params.organizationId);
    const result = await query;
    if (result.error) {
      if (hasMissingFinancialSchema(result.error)) return getNextMaintenanceProbeForTarget([]);
      throw result.error;
    }
    logAbaPlanningEgress({ helper: 'getNextMaintenanceProbeForTarget', table: 'aba_maintenance_schedules', limit: 10, rows: (result.data || []).length });
    const enrichedRows = await enrichMaintenanceRowsWithTargetDisplay(
      result.data || [],
      params.clinicId,
      params.organizationId,
      { role: 'owner' }
    );
    return getNextMaintenanceProbeForTarget(enrichedRows);
  };

  const updateAbaScheduleWithSchemaFallback = async (scheduleId: string, patchBase: Record<string, any>, clinicId: string, organizationId?: string, patientId?: string) => {
    let patch: Record<string, any> = { ...patchBase };
    while (Object.keys(patch).length > 0) {
      let query = supabase
        .from('aba_maintenance_schedules')
        .update(patch)
        .eq('id', scheduleId)
        .in('status', ABA_ACTIVE_MAINTENANCE_SCHEDULE_STATUSES);
      if (clinicId) query = query.eq('clinic_id', clinicId);
      if (organizationId) query = query.eq('organization_id', organizationId);
      if (patientId) query = query.eq('patient_id', patientId);
      const result = await query.select('id').maybeSingle();
      if (!result.error) return { data: result.data, error: null };
      const missingColumn = extractMissingColumnName(result.error);
      if (missingColumn && missingColumn in patch) {
        delete patch[missingColumn];
        continue;
      }
      return { data: null, error: result.error };
    }
    return { data: null, error: { message: 'Patch ABA vazio apos fallback de schema.' } };
  };

  async function flagPendingMaintenanceProbesForAppointment(params: {
    appointmentId: string;
    organizationId: string;
    clinicId: string;
    patientId: string;
    scheduledAt: string;
    actorId?: string | null;
  }) {
    const appointmentId = sanitizeString(params.appointmentId, 180);
    const patientId = sanitizeString(params.patientId, 120);
    const clinicId = sanitizeString(params.clinicId, 120);
    const organizationId = sanitizeString(params.organizationId || clinicId, 120);
    const scheduledAt = sanitizeIsoDateTime(params.scheduledAt);
    if (!isUuid(appointmentId) || !isUuid(patientId) || !clinicId) return { flagged: 0 };

    let query = supabase
      .from('aba_maintenance_schedules')
      .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
      .eq('patient_id', patientId)
      .is('appointment_id', null)
      .in('status', ['PENDING_NEXT_SESSION', 'PENDING_LINK', 'PENDING_SCHEDULING', 'UNSCHEDULED'])
      .order('target_due_date', { ascending: true })
      .limit(50);
    if (isUuid(organizationId)) query = query.eq('organization_id', organizationId);
    if (clinicId) query = query.eq('clinic_id', clinicId);
    const result = await query;
    if (result.error) {
      if (hasMissingFinancialSchema(result.error)) return { flagged: 0 };
      throw result.error;
    }

    const appointmentMs = new Date(scheduledAt).getTime();
    const rows = Array.isArray(result.data) ? result.data : [];
    let flagged = 0;
    for (const row of rows) {
      const status = normalizeAbaMaintenanceScheduleStatus(row?.status);
      const raw = row?.raw_payload && typeof row.raw_payload === 'object' ? row.raw_payload : {};
      const ignoredIds = Array.isArray(raw.ignoredAppointmentIds) ? raw.ignoredAppointmentIds.map((value: any) => String(value)) : [];
      if (ignoredIds.includes(appointmentId)) continue;
      if (sanitizeString((row as any)?.candidate_appointment_id || raw.candidateAppointmentId, 180) === appointmentId) continue;

      const scheduleMode = sanitizeString(row?.schedule_mode || row?.scheduleMode, 80).toUpperCase();
      const targetDueDate = row?.target_due_date || row?.targetDueDate || row?.scheduled_for || row?.scheduledFor || null;
      const targetMs = targetDueDate ? new Date(targetDueDate).getTime() : NaN;
      let eligible = status === 'PENDING_NEXT_SESSION' || scheduleMode === 'NEXT_PATIENT_SESSION';
      if (!eligible && Number.isFinite(targetMs) && Number.isFinite(appointmentMs)) {
        const scheduleDay = Number(row?.schedule_day || row?.scheduleDay || 7);
        const { before, after } = getMaintenanceToleranceDays(scheduleDay);
        eligible = appointmentMs >= targetMs - before * 86_400_000 && appointmentMs <= targetMs + after * 86_400_000;
      }
      if (!eligible) continue;

      const patch = cleanObject({
        status: 'PENDING_CONFIRMATION',
        candidate_appointment_id: appointmentId,
        metadata: sanitizeClinicalPayload({
          ...(row?.metadata && typeof row.metadata === 'object' ? row.metadata : {}),
          candidateAppointmentId: appointmentId,
          candidateScheduledAt: scheduledAt,
          pendingConfirmationPreviousStatus: status,
          auditAction: 'MAINTENANCE_PROBE_PENDING_CONFIRMATION'
        }),
        raw_payload: sanitizeClinicalPayload({
          ...raw,
          candidateAppointmentId: appointmentId,
          candidateScheduledAt: scheduledAt,
          pendingConfirmationPreviousStatus: status,
          humanMessage: 'Ha sondagem de manutencao pendente para esta consulta. Confirme antes de vincular.',
          noSilentLink: true
        }),
        updated_at: new Date().toISOString()
      });
      const update = await updateAbaScheduleWithSchemaFallback(
        sanitizeString(row?.id, 180),
        patch,
        clinicId,
        organizationId,
        patientId
      );
      if (!update.error) {
        flagged += 1;
        void persistActivityLog({
          userId: sanitizeString(params.actorId, 120),
          clinicId,
          actorName: 'Sistema',
          title: 'Sondagem pendente de confirmacao',
          content: 'Maintenance Probe pendente foi sugerida para uma nova consulta, sem vinculo automatico.',
          type: 'clinical',
          actionType: 'MAINTENANCE_PROBE_PENDING_CONFIRMATION',
          payload: { scheduleId: row?.id, appointmentId, patientId }
        });
      } else if (!hasMissingFinancialSchema(update.error)) {
        console.warn('[ABA Maintenance] Falha ao marcar confirmacao pendente.', update.error?.message || String(update.error));
      }
    }
    return { flagged };
  }

  const completeMaintenanceScheduleAfterProbe = async (params: {
    scheduleId?: string | null;
    clinicId: string;
    organizationId: string;
    patientId: string;
    completedAt: string;
    completedBy?: string | null;
  }) => {
    const scheduleId = sanitizeString(params.scheduleId, 180);
    if (!scheduleId) return;
    const result = await updateAbaScheduleWithSchemaFallback(scheduleId, cleanObject({
      status: 'COMPLETED',
      completed_at: sanitizeIsoDateTime(params.completedAt),
      completed_by: sanitizeString(params.completedBy, 120) || null,
      updated_at: new Date().toISOString()
    }), params.clinicId, params.organizationId, params.patientId);
    if (result.error && !hasMissingFinancialSchema(result.error)) throw result.error;
  };

  const persistTargetMaintenanceApproval = async (params: {
    targetId: string;
    patientId: string;
    organizationId: string;
    clinicId: string;
    evaluationId: string;
    changedBy: string;
  }) => {
    const targetId = sanitizeString(params.targetId, 180);
    if (!targetId || !isUuid(params.patientId) || !params.evaluationId) return null;
    const targetResult = await supabase
      .from('aba_targets')
      .select('id,clinical_status')
      .eq('organization_id', params.organizationId)
      .eq('clinic_id', params.clinicId)
      .eq('patient_id', params.patientId)
      .eq('id', targetId)
      .limit(1)
      .maybeSingle();
    if (targetResult.error) {
      if (hasMissingFinancialSchema(targetResult.error)) return null;
      throw targetResult.error;
    }
    const previousStatus = sanitizeString(targetResult.data?.clinical_status, 80) || 'ACQUISITION';
    if (previousStatus === 'MAINTENANCE') return { previousStatus, newStatus: previousStatus };
    let updatePatch: Record<string, any> = { clinical_status: 'MAINTENANCE', updated_at: new Date().toISOString() };
    while (Object.keys(updatePatch).length > 0) {
      const updateResult = await supabase
        .from('aba_targets')
        .update(updatePatch)
        .eq('organization_id', params.organizationId)
        .eq('clinic_id', params.clinicId)
        .eq('patient_id', params.patientId)
        .eq('id', targetId)
        .select('id,clinical_status')
        .maybeSingle();
      if (!updateResult.error) break;
      const missingColumn = extractMissingColumnName(updateResult.error);
      if (missingColumn && missingColumn in updatePatch) {
        delete updatePatch[missingColumn];
        continue;
      }
      if (!hasMissingFinancialSchema(updateResult.error)) throw updateResult.error;
      break;
    }
    const audit = buildTargetStatusAuditLog({
      organizationId: params.organizationId,
      patientId: params.patientId,
      targetId,
      previousStatus,
      newStatus: 'MAINTENANCE',
      evaluationId: params.evaluationId,
      changedBy: sanitizeString(params.changedBy, 120) || 'supervisor',
      reason: 'Maestria aprovada por supervisor; target entrou em manutencao sem regressao automatica.',
      changedAt: new Date().toISOString()
    });
    await writeAbaRowWithSchemaFallback('aba_target_status_audit_logs', { ...audit, clinic_id: params.clinicId }, 'upsert');
    return { previousStatus, newStatus: 'MAINTENANCE' };
  };

  const fetchAbaPlanningContextSummaryDriven = async (params: {
    patientId: string;
    clinicId: string;
    organizationId: string;
    sourceSessionId?: string | null;
    focusType: string;
  }) => {
    const patientId = params.patientId;
    const clinicId = params.clinicId;
    const organizationId = params.organizationId;
    const sourceSessionId = sanitizeString(params.sourceSessionId, 180) || null;
    const activeScheduleStatuses = ABA_ACTIVE_MAINTENANCE_SCHEDULE_STATUSES;
    const recommendationStatuses = ['SUGGESTED', 'ACCEPTED', 'EDITED', 'APPLIED_TO_NEXT_SESSION'];
    const limit = 40;

    const summaryQueryBase = supabase
      .from('aba_session_summaries')
      .select(ABA_SESSION_REPORT_SELECT)
      .eq('patient_id', patientId)
      .order('updated_at', { ascending: false })
      .limit(1);
    let summaryQuery = sourceSessionId ? summaryQueryBase.eq('session_id', sourceSessionId) : summaryQueryBase;
    summaryQuery = applyAbaTenantScope(summaryQuery, { role: 'owner' }, clinicId, organizationId);

    const queries = await Promise.all([
      summaryQuery.maybeSingle(),
      applyAbaTenantScope(
        supabase
          .from('aba_session_metric_snapshots')
          .select(ABA_SESSION_METRIC_SNAPSHOT_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .order('changed_at', { ascending: false })
          .limit(limit),
        { role: 'owner' },
        clinicId,
        organizationId
      ),
      applyAbaTenantScope(
        supabase
          .from('aba_mastery_evaluations')
          .select(ABA_MASTERY_LIST_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .order('evaluated_at', { ascending: false })
          .limit(20),
        { role: 'owner' },
        clinicId,
        organizationId
      ),
      applyAbaTenantScope(
        supabase
          .from('aba_maintenance_schedules')
          .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .in('status', activeScheduleStatuses)
          .order('target_due_date', { ascending: true })
          .limit(40),
        { role: 'owner' },
        clinicId,
        organizationId
      ),
      applyAbaTenantScope(
        supabase
          .from('aba_maintenance_probe_results')
          .select(ABA_MAINTENANCE_PROBE_RESULT_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .order('occurred_at', { ascending: false })
          .limit(20),
        { role: 'owner' },
        clinicId,
        organizationId
      ),
      applyAbaTenantScope(
        supabase
          .from('aba_regression_alerts')
          .select(ABA_REGRESSION_ALERT_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .is('resolved_at', null)
          .order('created_at', { ascending: false })
          .limit(20),
        { role: 'owner' },
        clinicId,
        organizationId
      ),
      applyAbaTenantScope(
        supabase
          .from('aba_targets')
          .select(ABA_TARGET_RECOMMENDATION_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .in('clinical_status', ['ACQUISITION', 'READY_FOR_REVIEW', 'MASTERED', 'MAINTENANCE', 'REGRESSION_RISK'])
          .order('updated_at', { ascending: false })
          .limit(60),
        { role: 'owner' },
        clinicId,
        organizationId
      ),
      applyAbaTenantScope(
        supabase
          .from('aba_behavior_daily_summaries')
          .select(ABA_BEHAVIOR_DAILY_CHART_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .order('date', { ascending: false })
          .limit(20),
        { role: 'owner' },
        clinicId,
        organizationId
      ),
      applyAbaTenantScope(
        supabase
          .from('aba_clinical_recommendations')
          .select(ABA_CLINICAL_RECOMMENDATION_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .in('status', recommendationStatuses)
          .order('created_at', { ascending: false })
          .limit(30),
        { role: 'owner' },
        clinicId,
        organizationId
      )
    ]);

    for (const result of queries) {
      if ((result as any).error && !hasMissingFinancialSchema((result as any).error)) throw (result as any).error;
    }
    const safeData = (index: number, fallback: any) => (queries[index] as any).error ? fallback : ((queries[index] as any).data ?? fallback);
    logAbaPlanningEgress({
      helper: 'fetchAbaPlanningContextSummaryDriven',
      tables: 'aba_session_summaries,aba_session_metric_snapshots,aba_mastery_evaluations,aba_maintenance_schedules,aba_maintenance_probe_results,aba_regression_alerts,aba_targets,aba_behavior_daily_summaries,aba_clinical_recommendations',
      limit,
      rows: queries.map((result: any) => Array.isArray(result.data) ? result.data.length : (result.data ? 1 : 0))
    });
    const [maintenanceSchedules, maintenanceProbeResults, regressionAlerts] = await Promise.all([
      enrichMaintenanceRowsWithTargetDisplay(safeData(3, []), clinicId, organizationId, { role: 'owner' }),
      enrichMaintenanceRowsWithTargetDisplay(safeData(4, []), clinicId, organizationId, { role: 'owner' }),
      enrichMaintenanceRowsWithTargetDisplay(safeData(5, []), clinicId, organizationId, { role: 'owner' })
    ]);
    return {
      sessionSummary: safeData(0, null),
      metricSnapshots: safeData(1, []),
      masteryEvaluations: safeData(2, []),
      maintenanceSchedules,
      maintenanceProbeResults,
      regressionAlerts,
      targets: safeData(6, []),
      behaviorDailySummaries: safeData(7, []),
      existingRecommendations: safeData(8, [])
    };
  };

  const persistGeneratedRecommendations = async (params: {
    recommendations: AbaClinicalRecommendation[];
    clinicId: string;
    createdBy: string;
  }) => {
    const saved: any[] = [];
    for (const recommendation of params.recommendations) {
      const payload = cleanObject({
        ...recommendation,
        clinic_id: params.clinicId,
        patient_id: sanitizeString(recommendation.patient_id, 120),
        organization_id: sanitizeString(recommendation.organization_id, 120),
        source_session_id: sanitizeString(recommendation.source_session_id, 180) || null,
        recommendation_type: normalizeAbaRecommendationType(recommendation.recommendation_type),
        priority: normalizeAbaRecommendationPriority(recommendation.priority),
        title: sanitizeTextField(recommendation.title, 240),
        summary: sanitizeTextField(recommendation.summary, 500),
        rationale: sanitizeTextField(recommendation.rationale, 1000),
        suggested_action: sanitizeTextField(recommendation.suggested_action, 1000),
        evidence: sanitizeClinicalPayload(recommendation.evidence || {}),
        status: normalizeAbaRecommendationStatus(recommendation.status),
        created_at: recommendation.created_at || new Date().toISOString(),
        updated_at: new Date().toISOString()
      });
      const result = await writeAbaRowWithSchemaFallback('aba_clinical_recommendations', payload, 'upsert');
      if (result.error) {
        if (hasMissingFinancialSchema(result.error)) return { ok: false, status: 503, error: 'Schema de planejamento ABA ainda não aplicado.', data: saved };
        throw result.error;
      }
      saved.push({ ...payload, id: (result.data as any)?.id || payload.id });
      const auditPayload = cleanObject({
        id: `audit-${abaPlanningHash([payload.id, 'GENERATED', payload.context_hash])}`,
        organization_id: payload.organization_id,
        clinic_id: params.clinicId,
        patient_id: payload.patient_id,
        recommendation_id: payload.id,
        action: 'GENERATED',
        previous_status: null,
        new_status: payload.status,
        performed_by: params.createdBy,
        performed_at: new Date().toISOString(),
        metadata: sanitizeClinicalPayload({ contextHash: payload.context_hash, summaryDriven: true })
      });
      await writeAbaRowWithSchemaFallback('aba_clinical_recommendation_audit_logs', auditPayload, 'upsert');
    }
    return { ok: true, status: 200, data: saved };
  };

