  app.post('/api/aba/patients/:patientId/charts/annotations', requireAbaV2Feature, checkAuth, requireRoles('coordinator', 'therapist', 'admin', 'owner'), checkPatientAccess, async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 48 * 1024, 'Payload da anotação de gráfico ABA')) return;
      const { patientId, clinicId, organizationId } = resolveAbaChartPatientScope(req);
      if (!clinicId) return res.status(400).json({ success: false, error: 'Clínica não identificada.' });
      if (!isUuid(patientId)) return res.status(400).json({ success: false, error: 'Paciente inválido.' });
      const annotationType = sanitizeString(req.body?.annotation_type || req.body?.annotationType || 'NOTE', 40).toUpperCase();
      if (!['GOAL_LINE', 'CONDITION_LINE', 'NOTE'].includes(annotationType)) {
        return res.status(400).json({ success: false, error: 'Tipo de anotação inválido.' });
      }
      const chartType = sanitizeString(req.body?.chart_type || req.body?.chartType || 'overview', 80);
      const label = sanitizeTextField(req.body?.label, 180);
      if (!label) return res.status(400).json({ success: false, error: 'Rótulo é obrigatório.' });
      const payload = cleanObject({
        id: sanitizeString(req.body?.id || crypto.randomUUID(), 180),
        organization_id: organizationId || clinicId,
        clinic_id: clinicId,
        patient_id: patientId,
        session_id: sanitizeString(req.body?.session_id || req.body?.sessionId, 180) || null,
        target_id: sanitizeString(req.body?.target_id || req.body?.targetId, 180) || null,
        behavior_id: sanitizeString(req.body?.behavior_id || req.body?.behaviorId, 180) || null,
        chart_type: chartType,
        annotation_type: annotationType,
        date: sanitizeIsoDateTime(req.body?.date || req.body?.changed_at || req.body?.changedAt),
        value: req.body?.value !== undefined && req.body?.value !== null && req.body?.value !== ''
          ? asSafeNumber(req.body.value, -100000000, 100000000)
          : null,
        label,
        description: sanitizeTextField(req.body?.description, 1000),
        created_by: sanitizeString(req.session.user?.id, 120),
        created_at: new Date().toISOString()
      });
      const result = await writeAbaRowWithSchemaFallback('aba_graph_annotations', payload, 'upsert');
      if (result.error) {
        if (hasMissingFinancialSchema(result.error)) return res.status(503).json({ success: false, error: 'Schema dos gráficos ABA ainda não aplicado.' });
        throw result.error;
      }
      return res.json({ success: true, data: { ...payload, id: (result.data as any)?.id || payload.id } });
    } catch (error: any) {
      return res.status(500).json({ success: false, error: error?.message || 'Erro interno do servidor.' });
    }
  });

  app.post('/api/aba/maintenance-probe-results', requireAbaV2Feature, checkAuth, requireRoles('coordinator', 'therapist', 'admin', 'owner'), checkPatientAccess, async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 96 * 1024, 'Payload de maintenance probe ABA')) return;
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const patientId = sanitizeString(req.resolvedPatientId || req.body?.patient_id || req.body?.patientId, 120);
      if (!clinicId) return res.status(400).json({ success: false, error: 'Clínica não identificada.' });
      if (!isUuid(patientId)) return res.status(400).json({ success: false, error: 'Paciente inválido.' });
      const targetId = sanitizeString(req.body?.target_id || req.body?.targetId, 180);
      if (!targetId) return res.status(400).json({ success: false, error: 'Target é obrigatório.' });

      const totalTrials = asSafeNumber(req.body?.total_trials ?? req.body?.totalTrials, 0, 100000) || 0;
      const independentTrials = asSafeNumber(req.body?.independent_trials ?? req.body?.independentTrials, 0, 100000) || 0;
      const promptedTrials = asSafeNumber(req.body?.prompted_trials ?? req.body?.promptedTrials, 0, 100000) || 0;
      const errorTrials = asSafeNumber(req.body?.error_trials ?? req.body?.errorTrials, 0, 100000) || 0;
      const accuracyPercent = req.body?.accuracy_percent !== undefined || req.body?.accuracyPercent !== undefined
        ? asSafeNumber(req.body?.accuracy_percent ?? req.body?.accuracyPercent, 0, 100)
        : (totalTrials > 0 ? Math.round(((independentTrials + promptedTrials) / totalTrials) * 10000) / 100 : 0);
      const independencePercent = req.body?.independence_percent !== undefined || req.body?.independencePercent !== undefined
        ? asSafeNumber(req.body?.independence_percent ?? req.body?.independencePercent, 0, 100)
        : (totalTrials > 0 ? Math.round((independentTrials / totalTrials) * 10000) / 100 : 0);
      const occurredAt = sanitizeIsoDateTime(req.body?.occurred_at || req.body?.occurredAt);
      const organizationId = sanitizeString(req.body?.organization_id || req.body?.organizationId || req.session.user?.organizationId || req.session.user?.organization_id || clinicId, 120);
      const sessionId = sanitizeString(req.body?.session_id || req.body?.sessionId, 180) || null;
      const appointmentId = await resolveAbaAppointmentIdForClinicalWrite({
        requestedAppointmentId: req.body?.appointment_id || req.body?.appointmentId,
        sessionId,
        patientId,
        clinicId,
        user: req.session.user
      });
      let maintenanceScheduleId = sanitizeString(req.body?.maintenance_schedule_id || req.body?.maintenanceScheduleId, 180) || null;
      if (maintenanceScheduleId) {
        const scheduleScopeResult = await supabase
          .from('aba_maintenance_schedules')
          .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
          .eq('id', maintenanceScheduleId)
          .eq('organization_id', organizationId)
          .eq('clinic_id', clinicId)
          .eq('patient_id', patientId)
          .eq('target_id', targetId)
          .maybeSingle();
        if (scheduleScopeResult.error) {
          if (hasMissingFinancialSchema(scheduleScopeResult.error)) {
            return res.status(503).json({ success: false, error: 'Schema ABA de manutencao ainda não aplicado.' });
          }
          throw scheduleScopeResult.error;
        }
        if (!scheduleScopeResult.data?.id) {
          return res.status(403).json({ success: false, error: 'Sondagem de manutenção fora do escopo do paciente.' });
        }
        const scopedScheduleStatus = normalizeAbaMaintenanceScheduleStatus(scheduleScopeResult.data.status);
        if (!ABA_ACTIVE_MAINTENANCE_SCHEDULE_STATUSES.includes(scopedScheduleStatus)) {
          return res.status(409).json({ success: false, error: 'Sondagem de manutenção não está pendente.' });
        }
      }
      if (!maintenanceScheduleId) {
        let scheduleQuery = supabase
          .from('aba_maintenance_schedules')
          .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
          .eq('organization_id', organizationId)
          .eq('clinic_id', clinicId)
          .eq('patient_id', patientId)
          .eq('target_id', targetId)
          .in('status', ABA_ACTIVE_MAINTENANCE_SCHEDULE_STATUSES)
          .order('target_due_date', { ascending: true })
          .limit(20);
        const scheduleResult = await scheduleQuery;
        if (!scheduleResult.error) {
          const schedule = selectMaintenanceScheduleForProbe(scheduleResult.data || [], { appointmentId, occurredAt });
          maintenanceScheduleId = sanitizeString(schedule?.id, 180) || null;
        } else if (!hasMissingFinancialSchema(scheduleResult.error)) {
          throw scheduleResult.error;
        }
      }
      let probeStatus = normalizeAbaMaintenanceProbeStatus(req.body?.status ?? req.body?.probeStatus);
      if (req.body?.status === undefined && req.body?.probeStatus === undefined) {
        const { criterion } = await fetchAbaMasteryCriterion({
          organizationId,
          clinicId,
          patientId,
          targetId,
          programId: sanitizeString(req.body?.program_id || req.body?.programId, 180)
        });
        const minAccuracy = asSafeNumber(criterion?.minAccuracyPercent ?? criterion?.min_accuracy_percent, 80, 0, 100) || 80;
        const minIndependence = asSafeNumber(criterion?.minIndependencePercent ?? criterion?.min_independence_percent, 80, 0, 100) || 80;
        const minTrials = Math.max(1, Math.round(asSafeNumber(criterion?.minTrialsPerSession ?? criterion?.min_trials_per_session, 1, 1, 100000) || 1));
        const accuracyDrop = minAccuracy - Number(accuracyPercent || 0);
        const independenceDrop = minIndependence - Number(independencePercent || 0);
        probeStatus = totalTrials < minTrials
          ? 'WATCH'
          : accuracyDrop >= 20 || independenceDrop >= 20
            ? 'REGRESSION_RISK'
            : accuracyDrop > 0 || independenceDrop > 0
              ? 'WATCH'
              : 'MAINTAINED';
      }
      const payload = cleanObject({
        id: sanitizeString(req.body?.id || req.body?.result_id || req.body?.resultId || crypto.randomUUID(), 180),
        organization_id: organizationId,
        clinic_id: clinicId,
        patient_id: patientId,
        appointment_id: appointmentId,
        target_id: targetId,
        maintenance_schedule_id: maintenanceScheduleId,
        session_id: sessionId,
        occurred_at: occurredAt,
        total_trials: totalTrials,
        independent_trials: independentTrials,
        prompted_trials: promptedTrials,
        error_trials: errorTrials,
        accuracy_percent: accuracyPercent,
        independence_percent: independencePercent,
        status: probeStatus,
        raw_payload: sanitizeClinicalPayload({
          ...(req.body?.raw_payload || req.body?.rawPayload || {}),
          appointmentId: appointmentId || undefined,
          targetName: sanitizeTextField(req.body?.target_name || req.body?.targetName, 240),
          noAutomaticTargetMutation: true,
          humanReviewRequiredForRegressionConfirmed: true
        }),
        created_at: new Date().toISOString()
      });

      const result = await writeAbaRowWithSchemaFallback('aba_maintenance_probe_results', payload, 'upsert');
      if (result.error) {
        if (hasMissingFinancialSchema(result.error)) return res.status(503).json({ success: false, error: 'Schema ABA de manutencao ainda não aplicado.' });
        throw result.error;
      }
      await completeMaintenanceScheduleAfterProbe({
        scheduleId: maintenanceScheduleId,
        clinicId,
        organizationId,
        patientId,
        completedAt: occurredAt,
        completedBy: sanitizeString(req.session.user?.id, 120)
      });
      return res.json({ success: true, data: result.data || payload });
    } catch (error: any) {
      return res.status(500).json({ success: false, error: error?.message || 'Erro interno do servidor.' });
    }
  });

  const resolvePatientClinicIdForAbaSession = async (patientId: string) => {
    const safePatientId = sanitizeString(patientId, 120);
    if (!isUuid(safePatientId)) return '';
    const { data, error } = await supabase
      .from('patients')
      .select('clinic_id')
      .eq('id', safePatientId)
      .limit(1)
      .maybeSingle();
    if (error) {
      if (hasMissingFinancialSchema(error) || extractMissingColumnName(error)) return '';
      throw error;
    }
    return firstUuidValue(data?.clinic_id);
  };

  const resolveAbaSessionClinicId = async (params: {
    patientId: string;
    body: any;
    user: any;
  }) => {
    const snapshot = parseStoredJsonObject(params.body?.appointment_snapshot || params.body?.appointmentSnapshot);
    const patientClinicId = await resolvePatientClinicIdForAbaSession(params.patientId);
    return firstUuidValue(
      patientClinicId,
      currentClinicId(params.user),
      params.user?.clinicId,
      params.user?.clinic_id,
      params.user?.organizationId,
      params.user?.organization_id,
      params.user?.activeWorkspaceId,
      params.body?.clinic_id,
      params.body?.clinicId,
      params.body?.organization_id,
      params.body?.organizationId,
      snapshot?.clinic_id,
      snapshot?.clinicId,
      snapshot?.organization_id,
      snapshot?.organizationId
    );
  };

  const buildAbaSessionAppointmentMirrorFallback = (params: {
    appointmentId: string;
    patientId: string;
    clinicId: string;
    body: any;
    user: any;
  }) => {
    const appointmentId = sanitizeString(params.appointmentId, 120);
    const patientId = sanitizeString(params.patientId, 120);
    const clinicId = sanitizeString(params.clinicId, 120);
    if (!isUuid(appointmentId) || !isUuid(patientId) || !isUuid(clinicId)) return null;

    const snapshot = parseStoredJsonObject(params.body?.appointment_snapshot || params.body?.appointmentSnapshot);
    const snapshotId = sanitizeString(snapshot?.id || snapshot?.appointment_id || snapshot?.appointmentId, 120);
    if (snapshotId && snapshotId !== appointmentId) return null;
    const snapshotPatientId = sanitizeString(snapshot?.patient_id || snapshot?.patientId, 120);
    if (snapshotPatientId && snapshotPatientId !== patientId) return null;

    const scheduledStart =
      sanitizeIsoDateTime(
        params.body?.scheduled_start ||
          params.body?.scheduledStart ||
          params.body?.scheduled_start_at ||
          params.body?.scheduledStartAt ||
          snapshot?.scheduled_start_at ||
          snapshot?.scheduledStartAt ||
          snapshot?.scheduledAt ||
          snapshot?.scheduled_at,
        ''
      ) ||
      (
        snapshot?.date && snapshot?.time
          ? buildAppointmentDateTime(snapshot.date, snapshot.time)?.toISOString()
          : null
      );
    if (!scheduledStart) return null;

    const durationMinutes =
      asSafeNumber(
        params.body?.scheduled_duration_minutes ??
          params.body?.scheduledDurationMinutes ??
          snapshot?.scheduled_duration_minutes ??
          snapshot?.scheduledDurationMinutes ??
          snapshot?.duration_minutes ??
          snapshot?.durationMinutes,
        1,
        1440
      ) || 50;
    const scheduledEnd =
      sanitizeIsoDateTime(
        params.body?.scheduled_end ||
          params.body?.scheduledEnd ||
          params.body?.scheduled_end_at ||
          params.body?.scheduledEndAt ||
          snapshot?.scheduled_end_at ||
          snapshot?.scheduledEndAt ||
          snapshot?.scheduledEnd ||
          snapshot?.scheduled_end,
        ''
      ) ||
      calculateAppointmentEnd(scheduledStart, durationMinutes)?.toISOString() ||
      null;
    const professionalId = sanitizeString(
      params.body?.professional_id ||
        params.body?.professionalId ||
        params.body?.therapist_id ||
        params.body?.therapistId ||
        snapshot?.professional_id ||
        snapshot?.professionalId ||
        snapshot?.therapist_id ||
        snapshot?.therapistId ||
        params.user?.id,
      120
    );

    return cleanObject({
      ...snapshot,
      id: appointmentId,
      appointment_id: appointmentId,
      appointmentId,
      organization_id: snapshot?.organization_id || snapshot?.organizationId || clinicId,
      organizationId: snapshot?.organizationId || snapshot?.organization_id || clinicId,
      clinic_id: snapshot?.clinic_id || snapshot?.clinicId || clinicId,
      clinicId: snapshot?.clinicId || snapshot?.clinic_id || clinicId,
      patient_id: patientId,
      patientId,
      patient_name: sanitizeString(params.body?.patient_name || params.body?.patientName || snapshot?.patient_name || snapshot?.patientName || snapshot?.name, 180) || null,
      patientName: sanitizeString(params.body?.patientName || params.body?.patient_name || snapshot?.patientName || snapshot?.patient_name || snapshot?.name, 180) || null,
      therapist_id: professionalId || null,
      therapistId: professionalId || null,
      professional_id: professionalId || null,
      professionalId: professionalId || null,
      therapist_name: sanitizeString(params.body?.therapist_name || params.body?.therapistName || params.body?.professionalName || snapshot?.therapist_name || snapshot?.therapistName || snapshot?.professional, 180) || null,
      professional: sanitizeString(params.body?.professionalName || params.body?.therapistName || snapshot?.professional || snapshot?.therapistName || snapshot?.therapist_name, 180) || null,
      scheduled_at: scheduledStart,
      scheduledAt: scheduledStart,
      scheduled_start_at: scheduledStart,
      scheduledStartAt: scheduledStart,
      scheduled_end_at: scheduledEnd,
      scheduledEndAt: scheduledEnd,
      scheduled_duration_minutes: durationMinutes,
      scheduledDurationMinutes: durationMinutes,
      duration_minutes: durationMinutes,
      durationMinutes: durationMinutes,
      date: sanitizeDate(snapshot?.date) || formatDateInAppointmentTimezone(scheduledStart),
      time: normalizeAppointmentTime(snapshot?.time) || formatTimeInAppointmentTimezone(scheduledStart),
      status: snapshot?.status || 'SCHEDULED',
      room_id: sanitizeString(params.body?.room_id || params.body?.roomId || snapshot?.room_id || snapshot?.roomId || snapshot?.room, 180) || null,
      roomId: sanitizeString(params.body?.roomId || params.body?.room_id || snapshot?.roomId || snapshot?.room_id || snapshot?.room, 180) || null,
      room_name: sanitizeString(params.body?.room_name || params.body?.roomName || snapshot?.room_name || snapshot?.roomName || snapshot?.roomDisplayName, 180) || null,
      roomName: sanitizeString(params.body?.roomName || params.body?.room_name || snapshot?.roomName || snapshot?.room_name || snapshot?.roomDisplayName, 180) || null,
      location_type: sanitizeString(params.body?.location_type || params.body?.locationType || snapshot?.location_type || snapshot?.locationType || snapshot?.location, 80) || null,
      locationType: sanitizeString(params.body?.locationType || params.body?.location_type || snapshot?.locationType || snapshot?.location_type || snapshot?.location, 80) || null,
      service_type: sanitizeString(params.body?.service_type || params.body?.serviceType || snapshot?.service_type || snapshot?.serviceType || snapshot?.type || snapshot?.approach, 120) || null,
      serviceType: sanitizeString(params.body?.serviceType || params.body?.service_type || snapshot?.serviceType || snapshot?.service_type || snapshot?.type || snapshot?.approach, 120) || null,
      approach: sanitizeString(snapshot?.approach || snapshot?.type || params.body?.service_type || params.body?.serviceType, 120) || null
    });
  };

  app.post('/api/aba/sessions', requireAbaV2Feature, checkAuth, requireRoles('coordinator', 'therapist', 'admin', 'owner'), checkPatientAccess, async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 96 * 1024, 'Payload da sessão ABA')) return;
      const patientId = sanitizeString(req.resolvedPatientId || req.body?.patient_id || req.body?.patientId, 120);
      if (!isUuid(patientId)) return res.status(400).json({ success: false, error: 'Paciente inválido.' });
      const clinicId = await resolveAbaSessionClinicId({
        patientId,
        body: req.body || {},
        user: req.session.user
      });
      if (!clinicId) return res.status(400).json({ success: false, error: 'Clínica não identificada.' });

      const startedAt = sanitizeIsoDateTime(req.body?.started_at || req.body?.startedAt);
      const requestSource = resolveAbaRequestSource(req.body);
      const appointmentStartRequested = ['appointment', 'agenda', 'calendar'].includes(
        sanitizeString(requestSource, 80).toLowerCase()
      );
      const rawAppointmentId = sanitizeString(req.body?.appointment_id || req.body?.appointmentId, 180);
      if (!rawAppointmentId && appointmentStartRequested) {
        logAbaSessionStartDebug({
          hasAppointmentId: false,
          appointmentFound: false,
          organizationMatched: false,
          reasonCode: 'MISSING_APPOINTMENT_ID'
        });
        return res.status(400).json({ success: false, error: 'Consulta não informada.' });
      }
      if (rawAppointmentId && !isUuid(rawAppointmentId)) {
        logAbaSessionStartDebug({
          hasAppointmentId: true,
          appointmentFound: false,
          organizationMatched: false,
          reasonCode: 'INVALID_APPOINTMENT_ID'
        });
        return res.status(400).json({
          success: false,
          code: 'INVALID_APPOINTMENT_ID',
          error: 'Consulta inválida.'
        });
      }
      const appointmentId = rawAppointmentId || null;
      let linkedAppointment: any = null;
      let existingInProgressSession: any = null;
      let resolvedProfessionalId = sanitizeString(
        req.body?.professional_id ||
          req.body?.professionalId ||
          req.body?.therapist_id ||
          req.body?.therapistId ||
          req.session.user?.id,
        120
      );
      let professionalScopeIds = collectAbaSessionProfessionalScopeIds({
        body: req.body || {},
        user: req.session.user
      });
      if (appointmentId) {
        const fallbackAppointment = buildAbaSessionAppointmentMirrorFallback({
          appointmentId,
          patientId,
          clinicId,
          body: req.body || {},
          user: req.session.user
        });
        linkedAppointment = await getAppointmentForSessionStart(
          appointmentId,
          clinicId,
          req.session.user,
          {
            fallbackAppointment,
            professionalScopeIds
          }
        );
        if (!linkedAppointment?.id) {
          logAbaSessionStartDebug({
            hasAppointmentId: true,
            appointmentFound: false,
            organizationMatched: false,
            reasonCode: 'APPOINTMENT_NOT_FOUND'
          });
          return res.status(404).json({ success: false, error: 'Consulta não encontrada.' });
        }
        if (sanitizeString(linkedAppointment.patient_id, 120) !== patientId) {
          logAbaSessionStartDebug({
            hasAppointmentId: true,
            appointmentFound: true,
            appointmentStatus: normalizeOperationalAppointmentStatus(linkedAppointment.status),
            organizationMatched: true,
            reasonCode: 'PATIENT_MISMATCH'
          });
          return res.status(409).json({ success: false, error: 'Os dados da consulta não conferem com o paciente selecionado.' });
        }
        const appointmentStatus = normalizeOperationalAppointmentStatus(linkedAppointment.status);
        if (appointmentStatus === 'DELETED') {
          logAbaSessionStartDebug({
            hasAppointmentId: true,
            appointmentFound: false,
            appointmentStatus,
            organizationMatched: true,
            reasonCode: 'APPOINTMENT_DELETED'
          });
          return res.status(404).json({ success: false, error: 'Consulta não encontrada.' });
        }
        if (appointmentStatus === 'CANCELLED' || appointmentStatus === 'CANCEL_REQUESTED') {
          logAbaSessionStartDebug({
            hasAppointmentId: true,
            appointmentFound: true,
            appointmentStatus,
            organizationMatched: true,
            reasonCode: 'APPOINTMENT_CANCELLED'
          });
          return res.status(409).json({ success: false, error: 'Esta consulta está cancelada e não pode ser iniciada.' });
        }
        if (appointmentStatus === 'COMPLETED') {
          logAbaSessionStartDebug({
            hasAppointmentId: true,
            appointmentFound: true,
            appointmentStatus,
            organizationMatched: true,
            reasonCode: 'APPOINTMENT_COMPLETED'
          });
          return res.status(409).json({ success: false, error: 'Esta consulta já possui sessão encerrada.' });
        }
        if (!ABA_SESSION_STARTABLE_APPOINTMENT_STATUSES.has(appointmentStatus)) {
          logAbaSessionStartDebug({
            hasAppointmentId: true,
            appointmentFound: true,
            appointmentStatus,
            organizationMatched: true,
            reasonCode: 'APPOINTMENT_STATUS_NOT_STARTABLE'
          });
          return res.status(409).json({ success: false, error: 'Esta consulta não pode ser iniciada neste status.' });
        }
        const appointmentProfessionalId = resolveAppointmentProfessionalId(linkedAppointment);
        professionalScopeIds = collectAbaSessionProfessionalScopeIds({
          body: req.body || {},
          user: req.session.user,
          appointment: linkedAppointment
        });
        const explicitProfessionalId = sanitizeString(
          req.body?.professional_id ||
            req.body?.professionalId ||
            req.body?.therapist_id ||
            req.body?.therapistId,
          120
        );
        if (
          explicitProfessionalId &&
          appointmentProfessionalId &&
          explicitProfessionalId !== appointmentProfessionalId &&
          !appointmentBelongsToProfessional(linkedAppointment, explicitProfessionalId)
        ) {
          logAbaSessionStartDebug({
            hasAppointmentId: true,
            appointmentFound: true,
            appointmentStatus,
            organizationMatched: true,
            reasonCode: 'PROFESSIONAL_MISMATCH'
          });
          return res.status(409).json({ success: false, error: 'Consulta vinculada a outro profissional.' });
        }
        resolvedProfessionalId = appointmentProfessionalId || explicitProfessionalId || resolvedProfessionalId;
        existingInProgressSession = await fetchInProgressAbaSessionForAppointment({
          appointmentId,
          patientId,
          clinicId,
          user: req.session.user,
          professionalIds: professionalScopeIds
        });
        if (!existingInProgressSession?.id) {
          const existingCompletedSession = await fetchCompletedAbaSessionForAppointment({
            appointmentId,
            patientId,
            clinicId,
            user: req.session.user,
            professionalIds: professionalScopeIds
          });
          if (existingCompletedSession?.id) {
            logAbaSessionStartDebug({
              hasAppointmentId: true,
              appointmentFound: true,
              appointmentStatus,
              organizationMatched: true,
              reasonCode: 'SESSION_ALREADY_COMPLETED'
            });
            return res.status(409).json({ success: false, error: 'Esta consulta já possui sessão encerrada.' });
          }
          const conflictingInProgressSession = await fetchConflictingInProgressAbaSessionForAppointment({
            appointmentId,
            patientId,
            professionalId: resolvedProfessionalId,
            clinicId,
            user: req.session.user,
            scheduledStartAt: linkedAppointment?.scheduled_start_at || linkedAppointment?.scheduled_at || null,
            scheduledEndAt: linkedAppointment?.scheduled_end_at || null
          });
          if (conflictingInProgressSession?.id) {
            logAbaSessionStartDebug({
              hasAppointmentId: true,
              appointmentFound: true,
              appointmentStatus,
              organizationMatched: true,
              reasonCode: 'CONFLICTING_SESSION_IN_PROGRESS'
            });
            return res.status(409).json({ success: false, error: 'Já existe uma sessão em andamento para este paciente/profissional.' });
          }
        }
        logAbaSessionStartDebug({
          hasAppointmentId: true,
          appointmentFound: true,
          appointmentStatus,
          organizationMatched: true,
          reasonCode: existingInProgressSession?.id ? 'REUSE_IN_PROGRESS_SESSION' : 'START_ALLOWED'
        });
      }
      const requestedSessionId = sanitizeString(req.body?.id || req.body?.session_id || req.body?.sessionId || crypto.randomUUID(), 180);
      const sessionId = sanitizeString(existingInProgressSession?.id || requestedSessionId, 180);
      const requestedStatus = normalizeAbaSessionStatus(req.body?.status);
      const sessionStatus = appointmentId && requestedStatus === 'active' ? 'in_progress' : requestedStatus;
      const resolvedActualEndAt = req.body?.actual_end || req.body?.actualEnd || req.body?.actual_end_at || req.body?.actualEndAt
        ? sanitizeIsoDateTime(req.body?.actual_end || req.body?.actualEnd || req.body?.actual_end_at || req.body?.actualEndAt)
        : null;
      const resolvedActualStartAt = existingInProgressSession?.actual_start_at || (
        req.body?.actual_start || req.body?.actualStart || req.body?.actual_start_at || req.body?.actualStartAt
          ? sanitizeIsoDateTime(req.body?.actual_start || req.body?.actualStart || req.body?.actual_start_at || req.body?.actualStartAt)
          : startedAt
      );
      const payload = cleanObject({
        id: sessionId,
        organization_id: sanitizeString(linkedAppointment?.organization_id || linkedAppointment?.clinic_id || clinicId, 120),
        clinic_id: clinicId,
        patient_id: patientId,
        patient_name: sanitizeString(req.body?.patient_name || req.body?.patientName, 180),
        therapist_id: resolvedProfessionalId,
        device_id: sanitizeString(req.body?.device_id || req.body?.deviceId, 180),
        source: requestSource,
        status: sessionStatus,
        appointment_id: appointmentId,
        scheduled_start_at: req.body?.scheduled_start || req.body?.scheduledStart || req.body?.scheduled_start_at || req.body?.scheduledStartAt
          ? sanitizeIsoDateTime(req.body?.scheduled_start || req.body?.scheduledStart || req.body?.scheduled_start_at || req.body?.scheduledStartAt)
          : linkedAppointment?.scheduled_start_at || linkedAppointment?.scheduled_at || null,
        scheduled_end_at: req.body?.scheduled_end || req.body?.scheduledEnd || req.body?.scheduled_end_at || req.body?.scheduledEndAt
          ? sanitizeIsoDateTime(req.body?.scheduled_end || req.body?.scheduledEnd || req.body?.scheduled_end_at || req.body?.scheduledEndAt)
          : linkedAppointment?.scheduled_end_at || null,
        scheduled_duration_minutes: req.body?.scheduled_duration_minutes !== undefined || req.body?.scheduledDurationMinutes !== undefined
          ? asSafeNumber(req.body?.scheduled_duration_minutes ?? req.body?.scheduledDurationMinutes, 0, 1440)
          : linkedAppointment?.scheduled_duration_minutes || linkedAppointment?.duration_minutes || null,
        actual_start_at: resolvedActualStartAt,
        actual_end_at: resolvedActualEndAt,
        actual_duration_minutes: req.body?.actual_duration_minutes !== undefined || req.body?.actualDurationMinutes !== undefined
          ? asSafeNumber(req.body?.actual_duration_minutes ?? req.body?.actualDurationMinutes, 0, 1440)
          : calculateAbaSessionDurationMinutes(resolvedActualStartAt, resolvedActualEndAt),
        room_id: sanitizeString(req.body?.room_id || req.body?.roomId || linkedAppointment?.room_id, 180) || null,
        room_name: sanitizeString(req.body?.room_name || req.body?.roomName || linkedAppointment?.room_name, 180) || null,
        location_type: sanitizeString(req.body?.location_type || req.body?.locationType || linkedAppointment?.location_type, 80) || null,
        service_type: sanitizeString(req.body?.service_type || req.body?.serviceType || linkedAppointment?.service_type || linkedAppointment?.approach, 120) || null,
        started_at: existingInProgressSession?.started_at || startedAt,
        ended_at: req.body?.ended_at || req.body?.endedAt ? sanitizeIsoDateTime(req.body?.ended_at || req.body?.endedAt, startedAt) : resolvedActualEndAt,
        duration_seconds: req.body?.duration_seconds !== undefined || req.body?.durationSeconds !== undefined
          ? asSafeNumber(req.body?.duration_seconds ?? req.body?.durationSeconds, 0, 86400)
          : null,
        duration_minutes: req.body?.duration_minutes !== undefined || req.body?.durationMinutes !== undefined
          ? asSafeNumber(req.body?.duration_minutes ?? req.body?.durationMinutes, 0, 1440)
          : calculateAbaSessionDurationMinutes(resolvedActualStartAt, resolvedActualEndAt),
        reference_date: sanitizeDate(req.body?.reference_date || req.body?.referenceDate) || startedAt.slice(0, 10),
        record_count: existingInProgressSession?.record_count ?? (asSafeNumber(req.body?.record_count ?? req.body?.recordCount, 0, 100000) || 0),
        sync_status: 'synced',
        notes: sanitizeTextField(req.body?.notes, 2000),
        created_by: sanitizeString(req.session.user?.id, 120),
        updated_at: new Date().toISOString()
      });

      const result = await writeAbaRowWithSchemaFallback('aba_sessions', payload, 'upsert');
      if (result.error) {
        if (hasMissingFinancialSchema(result.error)) {
          return res.status(503).json({ success: false, error: 'Schema ABA ainda não aplicado.' });
        }
        throw result.error;
      }
      if (payload.appointment_id) {
        const appointmentStatus = payload.status === 'completed'
          ? 'COMPLETED'
          : isAbaSessionInProgressStatus(payload.status)
            ? 'IN_PROGRESS'
            : null;
        if (appointmentStatus) {
          await patchAppointmentOperationalFromAbaSession({
            appointmentId: payload.appointment_id,
            user: req.session.user,
            status: appointmentStatus,
            actualStartAt: payload.actual_start_at || payload.started_at,
            actualEndAt: payload.actual_end_at || payload.ended_at,
            actualDurationMinutes: payload.actual_duration_minutes || payload.duration_minutes,
            abaSessionId: payload.id
          });
        }
        await regenerateClosureForAppointments(
          [payload.appointment_id],
          req.session.user,
          'aba_session_saved'
        );
      }
      const data = { ...payload, id: (result.data as any)?.id || payload.id };
      return res.json({ success: true, idempotent: Boolean(existingInProgressSession?.id), data, session: data });
    } catch (error: any) {
      console.error('[ABA Sessions] start error:', error?.message || String(error));
      return res.status(500).json({ success: false, error: 'Não foi possível iniciar a sessão agora.' });
    }
  });

  app.patch('/api/aba/sessions/:sessionId', requireAbaV2Feature, checkAuth, requireRoles('coordinator', 'therapist', 'admin', 'owner'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 64 * 1024, 'Payload da sessão ABA')) return;
      const sessionId = sanitizeString(req.params.sessionId, 180);
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      if (!sessionId) return res.status(400).json({ success: false, error: 'Sessão inválida.' });

      const patch = cleanObject({
        status: req.body?.status !== undefined ? normalizeAbaSessionStatus(req.body?.status) : undefined,
        appointment_id: req.body?.appointment_id !== undefined || req.body?.appointmentId !== undefined
          ? (isUuid(sanitizeString(req.body?.appointment_id || req.body?.appointmentId, 180)) ? sanitizeString(req.body?.appointment_id || req.body?.appointmentId, 180) : null)
          : undefined,
        scheduled_start_at: req.body?.scheduled_start !== undefined || req.body?.scheduledStart !== undefined || req.body?.scheduled_start_at !== undefined || req.body?.scheduledStartAt !== undefined
          ? sanitizeIsoDateTime(req.body?.scheduled_start || req.body?.scheduledStart || req.body?.scheduled_start_at || req.body?.scheduledStartAt)
          : undefined,
        scheduled_end_at: req.body?.scheduled_end !== undefined || req.body?.scheduledEnd !== undefined || req.body?.scheduled_end_at !== undefined || req.body?.scheduledEndAt !== undefined
          ? sanitizeIsoDateTime(req.body?.scheduled_end || req.body?.scheduledEnd || req.body?.scheduled_end_at || req.body?.scheduledEndAt)
          : undefined,
        scheduled_duration_minutes: req.body?.scheduled_duration_minutes !== undefined || req.body?.scheduledDurationMinutes !== undefined
          ? asSafeNumber(req.body?.scheduled_duration_minutes ?? req.body?.scheduledDurationMinutes, 0, 1440)
          : undefined,
        actual_start_at: req.body?.actual_start !== undefined || req.body?.actualStart !== undefined || req.body?.actual_start_at !== undefined || req.body?.actualStartAt !== undefined
          ? sanitizeIsoDateTime(req.body?.actual_start || req.body?.actualStart || req.body?.actual_start_at || req.body?.actualStartAt)
          : undefined,
        actual_end_at: req.body?.actual_end !== undefined || req.body?.actualEnd !== undefined || req.body?.actual_end_at !== undefined || req.body?.actualEndAt !== undefined
          ? sanitizeIsoDateTime(req.body?.actual_end || req.body?.actualEnd || req.body?.actual_end_at || req.body?.actualEndAt)
          : undefined,
        actual_duration_minutes: req.body?.actual_duration_minutes !== undefined || req.body?.actualDurationMinutes !== undefined
          ? asSafeNumber(req.body?.actual_duration_minutes ?? req.body?.actualDurationMinutes, 0, 1440)
          : undefined,
        room_id: req.body?.room_id !== undefined || req.body?.roomId !== undefined ? sanitizeString(req.body?.room_id || req.body?.roomId, 180) || null : undefined,
        room_name: req.body?.room_name !== undefined || req.body?.roomName !== undefined ? sanitizeString(req.body?.room_name || req.body?.roomName, 180) || null : undefined,
        location_type: req.body?.location_type !== undefined || req.body?.locationType !== undefined ? sanitizeString(req.body?.location_type || req.body?.locationType, 80) || null : undefined,
        ended_at: req.body?.ended_at !== undefined || req.body?.endedAt !== undefined
          ? sanitizeIsoDateTime(req.body?.ended_at || req.body?.endedAt)
          : undefined,
        duration_seconds: req.body?.duration_seconds !== undefined || req.body?.durationSeconds !== undefined
          ? asSafeNumber(req.body?.duration_seconds ?? req.body?.durationSeconds, 0, 86400)
          : undefined,
        duration_minutes: req.body?.duration_minutes !== undefined || req.body?.durationMinutes !== undefined
          ? asSafeNumber(req.body?.duration_minutes ?? req.body?.durationMinutes, 0, 1440)
          : undefined,
        record_count: req.body?.record_count !== undefined || req.body?.recordCount !== undefined
          ? asSafeNumber(req.body?.record_count ?? req.body?.recordCount, 0, 100000)
          : undefined,
        notes: req.body?.notes !== undefined ? sanitizeTextField(req.body?.notes, 2000) : undefined,
        updated_at: new Date().toISOString()
      });
      if (patch.status === 'completed') {
        const completedAt = patch.actual_end_at || patch.ended_at || new Date().toISOString();
        if (patch.actual_end_at === undefined) patch.actual_end_at = completedAt;
        if (patch.ended_at === undefined) patch.ended_at = completedAt;
      }

      let safePatch: Record<string, any> = { ...patch };
      while (Object.keys(safePatch).length > 0) {
        let query = supabase.from('aba_sessions').update(safePatch).eq('id', sessionId);
        if (!hasGlobalClinicAccess(req.session.user) && clinicId) query = query.eq('clinic_id', clinicId);
        if (sanitizeString(req.session.user?.role, 40).toLowerCase() === 'therapist') {
          query = query.eq('therapist_id', sanitizeString(req.session.user?.id, 120));
        }
        const result = await query.select('id,status,appointment_id,scheduled_start_at,scheduled_end_at,scheduled_duration_minutes,actual_start_at,actual_end_at,actual_duration_minutes,room_id,room_name,location_type,ended_at,duration_seconds,duration_minutes,record_count,updated_at').maybeSingle();
        if (!result.error) {
          const appointmentIdForClosure = sanitizeString(result.data?.appointment_id || safePatch.appointment_id, 120);
          if (isUuid(appointmentIdForClosure)) {
            const sessionData = result.data || { id: sessionId, ...safePatch };
            const actualEndAt = sessionData.actual_end_at || sessionData.ended_at || null;
            const actualDurationMinutes = calculateAbaSessionDurationMinutes(
              sessionData.actual_start_at || sessionData.started_at,
              actualEndAt,
              sessionData.actual_duration_minutes ?? sessionData.duration_minutes
            );
            const appointmentStatus = sanitizeString(sessionData.status || safePatch.status, 40).toLowerCase() === 'completed'
              ? 'COMPLETED'
              : isAbaSessionInProgressStatus(sessionData.status || safePatch.status)
                ? 'IN_PROGRESS'
                : null;
            if (appointmentStatus) {
              await patchAppointmentOperationalFromAbaSession({
                appointmentId: appointmentIdForClosure,
                user: req.session.user,
                status: appointmentStatus,
                actualStartAt: sessionData.actual_start_at || sessionData.started_at,
                actualEndAt,
                actualDurationMinutes,
                abaSessionId: sessionId
              });
            }
            await regenerateClosureForAppointments(
              [appointmentIdForClosure],
              req.session.user,
              'aba_session_updated'
            );
          }
          return res.json({ success: true, data: result.data || { id: sessionId, ...safePatch } });
        }
        const missingColumn = extractMissingColumnName(result.error);
        if (missingColumn && missingColumn in safePatch) {
          delete safePatch[missingColumn];
          continue;
        }
        if (hasMissingFinancialSchema(result.error)) {
          return res.status(503).json({ success: false, error: 'Schema ABA ainda não aplicado.' });
        }
        throw result.error;
      }
      return res.status(400).json({ success: false, error: 'Nada para atualizar.' });
    } catch (error: any) {
      return res.status(500).json({ success: false, error: error?.message || 'Erro interno do servidor.' });
    }
  });

